(window.GIM_TS=window.GIM_TS||{})["Shevuot.1"]={"from":24,"a":[["\u0003בטומאת מקדש וקדשיו; במה הם מתכפרין? מוטב שיתכפרו בפרו של אהרן שהרי הותר מכללו\u0004 בכתוב \u0003אצל ביתו,\u0004 שאין כפרתו מיוחדת רק לאהרן, \u0003ואל יתכפרו בשעיר הנעשה בפנים, שהרי לא הותר מכללו.\u0004","\u0003ואם נפשך לומר\u0004 כלומר, אם רצונך להקשות על כך יכול אתה לומר תירוץ אחר — \u0003הרי הוא אומר: \"בית אהרן ברכו את ה' \"\u0004(תהלים קלה, יט).","וממשיכים בביאור הברייתא, ושואלים: \u0003ומאי\u0004 \u0005[ומה]\u0006 ענינו של \u0003\"אם נפשך לומר\"?\u0004 מה היה הקושי שבשלו הוצרך להוכחה נוספת? ומסבירים: זהו הקושי, \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003\"ביתו\" כתיב\u0004 \u0005[נאמר],\u0006 \"וכפר בעדו ובעד ביתו\", ולא אחרים! לכן אמר כי הכהנים \u0003כולן קרויין \"ביתו\", שנאמר: \"בית אהרן ברכו את ה'\u0004 בית הלוי ברכו את ה' \u0003יראי ה' ברכו את ה' \".\u0004","ועל מה ששנינו בברייתא \"ושחט את שעיר החטאת אשר לעם\" — שאין הכהנים מתכפרים בו שואלים: \u0003והאי\u0004 \u0005[ו\u0006הכתוב \u0005הזה]\u0006 \u0003\"אשר לעם\" להכי\u0004 \u0005[לכך\u0006 לדבר זה\u0005]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא\u0006 ללמד\u0005]?\u0006 \u0003האי מיבעי ליה\u0004 \u0005[זה נצרך לו]\u0006 \u0003דקאמר רחמנא\u0004 \u0005[שאומרת התורה]:\u0006 \u0003מ\u0004של ה\u0003עם ליהוי\u0004 \u0005[שיהיה],\u0006 ולא משל אהרן עצמו! ודוחים: \u0003ההוא\u0004 \u0005[אותו\u0006 דין\u0005]\u0006 \u0003מ\"ומאת עדת בני ישראל\u0004 יקח שני שעירי עזים וחטאת ואיל אחד לעולה\" (ויקרא טז, ה) \u0003נפקא\u0004 \u0005[יוצא].\u0006 ועוד שואלים על פרט אחר בברייתא: \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003\"אשר לו\" להכי\u0004 \u0005[לכך\u0006 לדבר זה\u0005]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 לומר שאין הכהנים מתכפרים בפרו של אהרן? \u0003האי מיבעי ליה לכדתניא\u0004 \u0005[זה נחוץ לו לכמו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003משלו הוא מביא ואינו מביא משל צבור.\u0004","","\u0003יכול לא יביא משל צבור,\u0004 מפני \u0003שאין הצבור מתכפרין בו\u0004 ולכן אין להם קשר אליו, \u0003אבל יביא\u0004 את הפר \u0003משל אחיו הכהנים, ש\u0004הרי \u0003אחיו הכהנים\u0004 על כל פנים \u0003מתכפרין בו? תלמוד לומר: \"אשר לו\",\u0004 לדייק: משלו ולא משל אחרים. \u0003יכול לא יביא\u0004 משל אחרים, \u0003ואם הביא כשר? תלמוד לומר שוב \"אשר לו\",\u0004 לומר ש\u0003הכתוב שנה עליו\u0004 ואמר את הדבר הזה פעמיים \u0003לעכב,\u0004 שאם אינו עושה כן הרי זה מעכב ומבטל את המעשה!","ומסבירים כי הברייתא אכן מתבססת על לימוד זה עצמו, ויש להסביר כך: \u0003תנא הכי קא קשיא ליה\u0004 \u0005[התנא כך היה קשה לו]:\u0006 \u0003מאי שנא בדעם דלא מכפר\u0004 \u0005[מדוע שונה\u0006 הדבר \u0005ב\u0006שעיר \u0005של העם שאינו מכפר\u0006 לכהנים\u0005]?\u0006 \u0003דלא קא חסרי ביה ממונא\u0004 \u0005[\u0006משום \u0005שאין חסרים בו ממון],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אשר לעם\"\u0004 ולא משל הכהנים, אולם \u0003ב\u0004של \u0003אהרן נמי לא קא חסרי ביה ממונא\u0004 \u0005[גם כן אין הם חסרים ממון],\u0006 שהרי נאמר בו \"אשר לו\", ולכן אפשר היה לומר שלא יתכפרו משלו! \u0003וקאמר\u0004 \u0005[ו\u0006על כן \u0005הוא אמר]:\u0006 \u0003כולן קרויין \"ביתו\"\u0004 ולכן יתכפרו בשל אהרן, למרות שאינם משלמים עבורו.","ושבים לדון בעיקר המחלוקת שבין ר' יהודה ור' שמעון, ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' שמעון,\u0004 הסבור שהכהנים מתכפרים בפרו של אהרן, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בפר \u0003תרי\u0004 \u0005[שני]\u0006 \u0003וידוין ו\u0004כן זריקת \u0003דם הפר,\u0004 לומר שוידוי \u0003חד\u0004 \u0005[אחד]\u0006 \u0003כנגד\u0004 מה שמכפר על כל ישראל \u0003שעיר הנעשה בפנים, וחד\u0004 \u0005[ואחד]\u0006 \u0003כנגד\u0004 מה שמכפר על ישראל \u0003שעיר הנעשה בחוץ, וחד\u0004 \u0005[ואחד]\u0006 \u0003כנגד\u0004 מה שמכפר על ישראל \u0003שעיר המשתלח.\u0004","\u0003אלא לר' יהודה\u0004 שסבור שהכהנים מתכפרים בשאר עבירות בשעיר המשתלח (חוץ מטומאת מקדש וקדשיו), \u0003תרי\u0004 \u0005[שני]\u0006 \u0003וידוין\u0004 בפר \u0003ודם הפר למה לי? בחד וידוי ודמו סגיא\u0004 \u0005[בוידוי אחד ובדם\u0006 ההזייה \u0005די\u0006 לו\u0005],\u0006 אחד כנגד השעיר הנעשה בפנים, ואחד כנגד השעיר הנעשה בחוץ!","ומשיבים: וידוי \u0003אחד לו\u0004 לאהרן, \u0003ו\u0004וידוי \u0003אחד לביתו\u0004 כלומר, לכהנים. \u0003כדתנא דבי\u0004 \u0005[כמו ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כך היא מדת הדין נוהגת\u0004 כלומר, כך ראוי להיות, ש\u0003מוטב יבוא זכאי\u0004 שכבר נתכפר לו העוון על ידי וידויו \u0003ויכפר על החייב, ואל יבוא חייב\u0004 שעדיין לא נתכפר לו \u0003ויכפר על החייב.\u0004","","את האמור בקיצור במשנה בפרק הראשון בידיעות הטומאה שבים ומבארים כאן. \u0003ידיעות הטומאה\u0004 הן \u0003שתים שהן ארבע,\u0004 כיצד? אם \u0003נטמא וידע\u0004 שנטמא, \u0003ונעלמה\u0004 (ונשכחה) \u0003ממנו הטומאה\u0004 שהוא טמא, \u0003ו\u0004הוא \u0003זכור את הקדש\u0004 שיודע שהוא אוכל בשר קודש, הרי זה אופן אחד מארבע ידיעות הטומאה.","וכן אם \u0003נעלם ממנו\u0004 ששכח שהוא אוכל בשר \u0003הקדש ו\u0004אולם \u0003זכור\u0004 עדיין \u0003את הטומאה\u0004 שנטמא, והרי זה אופן שני מארבע ידיעות הטומאה. או \u0003נעלמו ממנו זה וזה,\u0004 ששכח גם את זה וגם את זה, \u0003ו\u0004בכל המקרים הללו \u0003אכל את הקדש ולא ידע, ומשאכל\u0004 (לאחר שאכל) \u0003ידע\u0004 — \u0003הרי זה\u0004 חייב \u0003ב\u0004קרבן \u0003עולה ויורד\u0004 (שהקרבן עולה ויורד, בבהמה או עוף, לפי מצבו הכלכלי של החוטא).","וכן לענין טומאת מקדש: אם \u0003נטמא וידע\u0004 שנטמא, \u0003ונעלמה ממנו טומאה,\u0004 ששכח שנטמא, \u0003ו\u0004הוא \u0003זכור את המקדש;\u0004 או \u0003נעלם ממנו\u0004 שהוא מצוי ב\u0003מקדש ו\u0004הוא \u0003זכור את הטומאה;\u0004 וכן אם \u0003נעלם ממנו זה וזה,\u0004 הטומאה והמקדש, \u0003ונכנס למקדש ולא ידע, ומשיצא ידע\u0004 — \u0003הרי זה בעולה ויורד.\u0004","ובענין תחומי המקדש לדין זה של טומאת המקדש, \u0003אחד הנכנס לעזרה\u0004 הראשונה שנתקדשה, \u0003ואחד הנכנס לתוספת העזרה,\u0004 לשטח שהוסיפו לה לאחר זמן. משום שגם תוספת העזרה מתקדשת בקדושת העזרה, לפי \u0003שאין מוסיפין על העיר ועל העזרות אלא\u0004 \u0003ב\u0004הרכב מיוחד של \u0003מלך ונביא, ואורים ותומים, וסנהדרין של שבעים ואחד, ובשתי תודות\u0004 (שני קורבנות תודה) \u0003ובשיר\u0004 שהיו שרים שם. ומכיון שהדברים נעשים בהרכב השלם ביותר, יש בתוספת זו קדושה כקדושת העזרה עצמה. \u0003ו\u0004בפרטי הדברים, \u0003בית דין מהלכין ושתי תודות אחריהן, וכל ישראל אחריהם\u0004 כאשר עוד יבוארו פרטי הדברים בגמרא.",""],["התודה \u0003הפנימית נאכלת ו\u0004התודה \u0003החיצונה נשרפת\u0004 וכאשר יבוארו הדברים לפרטיהם בגמרא. \u0003וכל\u0004 תוספת למקדש \u0003שלא נעשית בכל אלו, הנכנס לשם\u0004 כשהוא טמא \u0003אין חייב עליה\u0004 קרבן (בשוגג) או כרת (במזיד).","בתחילה עסקה המשנה במי שנטמא קודם שנכנס למקדש. ומביאים מקרה אחר, במי שקודם כניסתו לעזרה היה טהור ו\u0003נטמא\u0004 בהיותו \u0003בעזרה, ו\u0004אחר כך \u0003נעלמה ממנו טומאה וזכור את המקדש\u0004 כלומר, זכר שהוא נמצא במקדש, או \u0003נעלם הימנו\u0004 שהוא ב\u0003מקדש וזכור הטומאה,\u0004 וכן אם \u0003נעלם ממנו זה וזה, ו\u0004בכל אחד ממקרים אלה, אם בזמן שנעלם ממנו \u0003השתחוה\u0004 כלפי פנים המקדש \u0003או ששהה\u0004 בעזרה זמן \u0003בכדי השתחואה\u0004 אף שלא השתחווה בפועל, \u0003או בא לו בארוכה\u0004 כלומר, יצא מן המקדש בדרך ארוכה כשאפשר היה לו לקצר את הדרך — הרי זה \u0003חייב\u0004 להביא קרבן עולה ויורד. אבל אם יצא מהמקדש \u0003ב\u0004דרך \u0003קצרה\u0004 ביותר — \u0003פטור.\u0004","ומצוה \u0003זו\u0004 שצריך לשלח את הטמא מן המקדש \u0003היא מצות עשה שבמקדש\u0004 ששנינו בה במסכת הוריות \u0003שאין חייבין עליה\u0004 הסנהדרין קרבן (פר העלם דבר), אם שגגו והורו לו בטעות לצאת בארוכה.","\u0003ואיזו היא מצות עשה שבנדה\u0004 ששנינו בה שם \u0003שחייבין עליה\u0004 בהוראה? אם \u0003היה משמש עם\u0004 אשתו \u0003הטהורה, ואמרה לו\u0004 תוך כדי ביאה \u0003\"נטמאתי\", ופירש\u0004 ממנה \u0003מיד\u0004 כשאמרה לו כן, ולא המתין עד שלא יהא בקישוי — \u0003חייב, מפני ש\u0004במקרה כזה \u0003יציאתו הנאה לו כביאתו.\u0004","\u0003ר' אליעזר אומר:\u0004 נאמר בדיני קרבן עולה ויורד: \"או נפש אשר תגע בכל דבר טמא... או בנבלת \u0003שרץ\u0004 טמא \u0003ונעלם ממנו\"\u0004 (ויקרא ה, ב), ויש לדייק: \u0003על העלם\u0004 ידיעה שנגע ונטמא ב\u0003שרץ חייב\u0004 קרבן עולה ויורד בטומאת מקדש וקדשיו, \u0003ואינו חייב\u0004 קרבן \u0003על העלם מקדש.\u0004","ובדומה לכך \u0003ר' עקיבא אומר:\u0004 נאמר \u0003\"ונעלם ממנו והוא טמא\"\u0004 (ויקרא ה, ב) — להדגיש: \u0003על העלם טומאה חייב\u0004 קרבן כשנודע לו, \u0003ואינו חייב על העלם מקדש.\u0004","\u0003ר' ישמעאל אמר: \"ונעלם\" \"ונעלם\"\u0004 שנאמר \u0003שתי פעמים\u0004 באותו כתוב בענין ידיעות הטומאה — הרי זה בא לרבות ו\u0003לחייב\u0004 גם \u0003על העלם טומאה ו\u0004גם \u0003על העלם מקדש.\u0004","שנינו במשנה \"ידיעות הטומאה שתים שהן ארבע\", \u0003אמר רב פפא לאביי:\u0004 וכי \u0003שתים שהן ארבע\u0004 הן? הלוא כפי שפירטה המשנה לאחר מכן \u0003שתים שהן שש הויין\u0004 \u0005[הן],\u0006 כיצד? \u0003ידיעות הטומאה תחלה וסוף, ידיעות הקודש תחלה וסוף, ידיעות מקדש תחלה וסוף!\u0004","והשיב לו אביי: \u0003ולטעמיך\u0004 \u0005[ולשיטתך]\u0006 שאתה מונה את המקרים השונים שפירטה המשנה, \u0003תמני הויין\u0004 \u0005[שמונה הן],\u0006 \u0003דהא איכא\u0004 \u0005[שהרי יש]\u0006 ידיעה של \u0003טומאה\u0004 של \u0003קודש\u0004 בתחילה וסוף, \u0003ו\u0004ידיעה של \u0003טומאה\u0004 של \u0003מקדש תחלה וסוף,\u0004 שהרי המשנה הזכירה ידיעות טומאה הן בדין הראשון העוסק בקודש, והן בדין השני העוסק במקדש!","ודחה רב פפא: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 \u0003שם טומאה אחת היא,\u0004 שמכל מקום טמא הוא, ונעלם ממנו, ואין לחלק בין טומאת קודש וטומאת מקדש. וחוזרת איפוא השאלה: \u0003מכל מקום שית הויין\u0004 \u0005[שש הן]!\u0006","\u0003אמר רב פפא\u0004 עצמו, שנתן תשובה לשאלתו שלו ואמר: \u0003לעולם תמני הויין\u0004 \u0005[שמונה הן],\u0006 שתי ידיעות (תחילה וסוף) של טומאה לענין קודש, שתי ידיעות של טומאה לענין מקדש, שתי ידיעות קודש ושתי ידיעות מקדש. אלא \u0003ארבעי קמייתא דלא מייתן ליה\u0004 \u0005[ארבע\u0006 ידיעות \u0005ראשונות שאין מביאות אותו]\u0006 כשלעצמן \u0003לידי קרבן לא קא חשיב\u0004 \u0005[אינו מונה\u0006 אותן\u0005],\u0006 שהרי אם לא נודע לו בסוף — אינו מביא קרבן, שהרי אינו יודע שחטא. \u0003ארבעה בתרייתא דמייתן ליה\u0004 \u0005[ארבע\u0006 ידיעות \u0005אחרונות שמביאות אותו]\u0006 \u0003לידי קרבן קא חשיב\u0004 \u0005[מונה אותן].\u0006","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003אמר רב פפא\u0004 כך: \u0003לעולם תמני הויין\u0004 \u0005[שמונה הן],\u0006 \u0003וארבעי קמייתא דליתנהו\u0004 \u0005[וארבע\u0006 ידיעות \u0005ראשונות שאינן]\u0006 \u0003בכל התורה כולה קא חשיב\u0004 \u0005[מונה\u0006 אותן\u0005],\u0006 שבכל מקום שמביא קרבן על שגגה אינו צריך שתהא לו ידיעה בדבר מתחילה, וכיון שחידוש הן מונה אותן. \u0003ארבעי בתרייתא דאיתנהו\u0004 \u0005[ארבע אחרונות שישנן]\u0006 \u0003בכל התורה כולה\u0004 כאשר נודע לו לאחר מעשה שחטא — \u0003לא קא חשיב\u0004 \u0005[אינו מונה\u0006 אותן\u0005].\u0006","ומעתה דנים בהגדרה של ידיעת הטומאה שבמשנה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם \u0003נעלמו ממנו הלכות טומאה, מהו?\u0004 האם גם על כך מתחייב קרבן עולה ויורד? ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דלא ידע\u0004 \u0005[שאינו יודע]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003שרץ\u0004 \u0003טמא אי\u0004 \u0005[אם]\u0006 \u0003צפרדע טמא\u0004 — זו אינה נקראת העלמה, \u0003זיל קרי בי רב הוא\u0004 \u0005[לך קרא\u0006 מקרא \u0005בבית הרב הוא]\u0006 שהדברים האלו כתובים וידועים לכל, ואין זו העלמה!","אלא \u0003לעולם\u0004 יש לומר ש\u0003ידע ב\u0004עיקר \u0003טומאת שרץ, וכגון\u0004 ש\u0003נגע ב\u0004חתיכת שרץ שגודלו רק \u0003כעדשה, ולא ידע\u0004 את ההלכה, האם \u0003כעדשה אי\u0004 \u0005[אם]\u0006 הוא \u0003מטמא אי\u0004 \u0005[אם]\u0006 \u0003לא מטמא,\u0004 אם כן \u0003מאי\u0004 \u0005[מה דינו]?\u0006 וצדדי השאלה: \u0003כיון דידע\u0004 \u0005[ש\u0006הוא \u0005יודע]\u0006 ש\u0003מטמא שרץ בעולם\u0004 (בכלל) — \u0003ידיעה היא, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003כעדשה לא ידע אי\u0004 \u0005[אינו יודע אם]\u0006 \u0003מטמא אי\u0004 \u0005[אם]\u0006 \u0003לא מטמא\u0004 — \u0003העלמה היא?\u0004 שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד].\u0006","ושאלה אחרת הנוגעת להגדרה של ידיעת המקדש \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: בן בבל\u0004 או מקום אחר \u0003שעלה לארץ ישראל, ונעלם ממנו מקום מקדש,\u0004 שלא ידע שזהו המקדש ונכנס לתוכו בטומאה, \u0003מהו?\u0004 האם חייב בקרבן?","ושואלים: \u0003אליבא דמאן\u0004 \u0005[לפי שיטת מי\u0006 הוא שואל\u0005]?\u0006 \u0003אי אליבא\u0004 \u0005[אם לפי שיטתו]\u0006 של \u0003ר' עקיבא דבעי\u0004 \u0005[שמצריך]\u0006 שתהיה \u0003ידיעה בתחלה\u0004 כדי לחייבו בקרבן — \u0003הא לא מחייב\u0004 \u0005[הרי\u0006 הוא \u0005אינו מחייב]\u0006 כלל \u0003על העלם מקדש! אי אליבא\u0004 \u0005[אם לפי שיטתו]\u0006 של \u0003ר' ישמעאל\u0004 ש\u0003מחייב על העלם מקדש\u0004 — \u0003הא לא בעי\u0004 \u0005[הרי אינו מצריך]\u0006 \u0003ידיעה בתחלה,\u0004 ואם כן אין פה שאלה לא לשיטה זו ולא לשיטה זו!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 שאלה זו אלא \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003רבי, דבעי\u0004 \u0005[שמצריך]\u0006 \u0003ידיעה בתחלה ו\u0004גם \u0003מחייב על העלם מקדש, ואמר\u0004 \u0005[ו\u0006הוא \u0005גם אומר]\u0006 כי \u0003ידיעת בית רבו שמה\u0004 (נקראת) \u0003ידיעה,\u0004 ואם כן אינו צריך לדעת מתחילה שהמקום המסויים אליו הוא נכנס הוא המקדש, אם כן \u0003מאי\u0004 \u0005[מה הדין]\u0006 במקרה זה? האם נאמר: \u0003כיון\u0004 ש\u0003ידע דאיכא\u0004 \u0005[שיש]\u0006 \u0003מקדש בעולם\u0004 — \u0003ידיעה היא, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003מקומו\u0004 של המקדש \u0003לא ידע ליה\u0004 \u0005[אינו יודע אותו]\u0006 — \u0003העלמה היא\u0004 ואין היא נחשבת לידיעה? אף שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה: \u0003אחד הנכנס לעזרה\u0004 ואחר הנכנס לתוספת העזרה, שאין מוסיפים על העיר ועל העזרות אלא במלך ונביא \u0003וכו'.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב שימי בר חייא\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ככל\u0004 \u0003אשר אני מראה אותך את תבנית המשכן ואת תבנית כל כליו\u0004"],["\u0003וכן תעשו\"\u0004 (שמות כה, ט), ומה שנוסף \"וכן תעשו\" הרי זה מקרא יתר, לומר: כפי שנעשה במשכן כך יש לעשות \u0003לדורות.\u0004","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רבא\u0004 ממה ששנינו בברייתא: \u0003כל הכלים שעשה משה\u0004 — \u0003משיחתן\u0004 שמשח אותם בשמן המשחה \u0003מקדשתן\u0004 להיות כלי קודש, \u0003מכאן ואילך\u0004 אין צורך במשיחה כדי לקדשם, אלא \u0003עבודתן מחנכתן,\u0004 שעל ידי זה שעושים בהם עבודה פעם ראשונה הם נעשים כלי קודש; \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003ונימא\u0004 \u0005[ונאמר]\u0006 גם כאן: \u0003\"וכן תעשו\"\u0004 — \u0003לדורות!\u0004","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במזבח וכליו: \u0003\"וימשחם ויקדש אתם\"\u0004 (במדבר ז, א), ויש כאן הדגשה: \u0003אותם במשיחה ולא לדורות במשיחה.\u0004","ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 אחרת: \u0003אותם במשיחה\u0004 דווקא, אבל \u0003לדורות או במשיחה או בעבודה! אמר רב פפא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"כלי השרת \u0003אשר ישרתו בם בקדש\"\u0004 (במדבר ד, יב), \u0003תלאן הכתוב בשירות\u0004 (עבודה), שלעתיד העבודה היא המקדשת אותם.","ושואלים: \u0003השתא דכתב רחמנא\u0004 \u0005[עכשיו שכתבה התורה]\u0006 \u0003\"אשר ישרתו\",\u0004 אם כן המיעוט \u0003\"אתם\" למה לי?\u0004 ומשיבים: \u0003אי לא כתב רחמנא\u0004 \u0005[אם לא היתה כותבת התורה]\u0006 \u0003\"אתם\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני הוא\u0004 \u0005[אלה הם]\u0006 ש\u0003במשיחה\u0004 בלבד מתקדשים, ו\u0003לדורות\u0004 צריכים גם \u0003במשיחה ו\u0004גם \u0003בעבודה, דהא כתב\u0004 \u0005[שהרי נאמר]\u0006 \u0003\"וכן תעשו\",\u0004 וכוונתו לעשות לדורות, על כן \u0003מיעט רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003\"אתם\",\u0004 לומר: \u0003אותם במשיחה ולא לדורות במשיחה.\u0004","\u0003ו\u0004עוד שנינו במשנה שמעשה ההקדשה של תוספת העיר והעזרה הוא \u0003בשתי תודות. תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003שתי תודות שאמרו\u0004 — הכוונה היא \u0003בלחמן\u0004 בלחמי התודה, \u0003ולא בבשרן\u0004 של קרבנות התודה. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב חסדא,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בחנוכה של חומת ירושלים בימי עזרא: \u0003\"ואעמידה שתי תודת גדולת ותהלכת לימין מעל לחומה\"\u0004 (נחמיה יב, לא), ונברר:","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"גדולת\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ממין גדול ממש,\u0004 שהביא תודות מן המין הגדול ביותר (שכן לקרבן תודה אפשר להביא גם מן הצאן ומן הבקר) — \u0003נימא\u0004 \u0005[נאמר]\u0006 שהיו אלה \u0003פרים! אלא\u0004 נאמר כי הכוונה ל\u0003גדולות במינן,\u0004 שהיו משובחות בטיבן — על כך יש לתמוה:","\u0003מי איכא חשיבותא קמי שמיא\u0004 \u0005[האם יש חשיבות לפני השמים]\u0006 מה גודל הקרבן? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 משנה\u0005]:\u0006 \u0003נאמר בעולת בהמה \"אשה ריח ניחוח\"\u0004 (ויקרא א, ט), \u0003בעולת העוף\u0004 נאמר גם כן \u0003\"אשה ריח ניחח\"\u0004 (ויקרא א יז), וגם \u0003במנחה\u0004 נאמר \u0003\"אשה ריח ניחח\"\u0004 (ויקרא ב, ב), ואף על פי שהקרבנות שונים זה מזה בערכם, \u0003מלמד\u0004 הדבר \u0003שאחד המרבה\u0004 \u0003ואחד הממעיט\u0004 הרי זה לריח ניחוח, \u0003ובלבד שיכוין את לבו לאביו שבשמים!\u0004","\u0003אלא\u0004 צריכים לומר כי הכוונה ב\"תודות גדולות\" ל\u0003גדולה שבתודה,\u0004 לגדול בלחמי התודה, \u0003ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 חלק ה\u0003חמץ\u0004 שבה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003התודה\u0004 (חלק המנחה שבה) \u0003היתה באה מן חמש סאין ירושלמיות\u0004 (המידה שנהגה בירושלים) של קמח, \u0003שהן שש\u0004 סאים \u0003מדבריות\u0004 (המידה הקטנה יותר, שנהגה במדבר, בזמן התורה), \u0003שהן שתי איפות, והאיפה שלש סאין\u0004 של מדבריות. ובאותן שתי איפות יש \u0003עשרים עשרון\u0004 (עשירית האיפה), \u0003עשרה\u0004 עשרונים עושים \u0003לחמץ ועשרה למצה. ובמצה\u0004 יש \u0003שלשה מינין: חלות, רקיקין, ורבוכה.\u0004 ואם כן נמצא שחלות החמץ הן החלות הגדולות שבתודה, שגדולות פי שלוש מלחמי המצה, ובהן היו מקדשים את תוספת העיר.","\u0003אמר רמי בר חמא:\u0004 מברייתא זאת למדנו כי \u0003אין העזרה מתקדשת אלא בשירי מנחה\u0004 כלומר, בחלק המנחה שאוכלים הכהנים, ולא בלחמי תודה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 כמו האופן בו מתקדשת \u0003ירושלים, מה ירושלים\u0004 — \u0003דבר הנאכל בה\u0004 (לחם תודה, הנאכל בכל העיר) הוא ה\u0003מקדשה, אף עזרה\u0004 — \u0003דבר הנאכל בה מקדשה.\u0004","ושואלים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003לחמי תודה בעזרה מי לא מתאכלי\u0004 \u0005[האם אינם נאכלים]?\u0006 \u0003אלא\u0004 יש להגדיר את ההשוואה ולומר כך: \u0003כירושלים, מה ירושלים\u0004 מתקדשת בלחמי תודה, \u0003דבר הנאכל בה ו\u0004שאם הוא \u0003יוצא ממנה\u0004 — \u0003נפסל, אף עזרה\u0004 מתקדשת ב\u0003דבר הנאכל בה ו\u0004שאם היה \u0003יוצא ממנה\u0004 — \u0003נפסל,\u0004 והוא שיירי מנחה, שמנחה אינה מותרת באכילה לכהנים אלא בתוך העזרה.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 אתה למד מחנוכת ירושלים לחנוכת העזרה, יש גם לומר כך: \u0003מה להלן\u0004 בקידוש תוספת ירושלים, מדובר בחלה של \u0003חמץ, אף כאן\u0004 בקידוש תוספת העזרה יאכל שיירי מנחה של \u0003חמץ!\u0004 ותוהים: \u0003ותסברא\u0004 \u0005[ויכול אתה לסבור כן]?\u0006 \u0003מנחת חמץ מי איכא\u0004 \u0005[האם יש]?\u0006 הרי מנחה היא תמיד מצה!"],["\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003מחמיץ להו\u0004 \u0005[אותם]\u0006 את ה\u0003שירים\u0004 שאוכלים הכהנים \u0003ומקדש בהו\u0004 \u0005[בהם]\u0006 את העזרה, \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"לא תאפה חמץ חלקם\"\u0004 (ויקרא ו, י), \u0003ואמר ריש לקיש\u0004 בפירוש הכתוב: \u0003אפילו חלקם לא תאפה חמץ,\u0004 שיש איסור אפילו באפיית חלק מן המנחה חמץ.","ושואלים: ועדיין \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 ניתן לקדש את העזרה במנחה של חמץ? והרי \u0003אפשר\u0004 ש\u0003מקדש בשתי הלחם בעצרת\u0004 (בחג השבועות) שהם מנחות והם חמץ! ומשיבים: \u0003משום\u0004 ש\u0003לא אפשר\u0004 לעשות זאת, שכן","\u0003היכי ניעביד\u0004 \u0005[כיצד נעשה]?\u0006 \u0003נבנייה\u0004 \u0005[נבנה אותו]\u0006 את חלק העזרה הנוסף \u0003מאתמול\u0004 (מערב חג השבועות) \u0003וניקדשיה\u0004 \u0005[ונקדש אותו]\u0006 \u0003מאתמול\u0004 לפני החג — זה אינו אפשרי, משום ש\u0003שתי הלחם בשחיטת כבשים\u0004 שבאים עימם \u0003הוא דקדשי\u0004 \u0005[הן שמתקדשות],\u0006 בתוך החג עצמו ולא קודם לכן!","\u0003נבנייה\u0004 \u0005[נבנה אותו]\u0006 \u0003מאתמול וניקדשיה האידנא\u0004 \u0005[ונקדש אותו היום\u0006 בעצרת\u0005]\u0006 — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003קידוש בשעת הבנין!\u0004","ואם תאמר: \u0003נבנייה\u0004 \u0005[נבנה אותו]\u0006 \u0003ביום טוב ונקדשיה\u0004 \u0005[ונקדש אותו]\u0006 \u0003ביום טוב\u0004 — \u0003אין בנין מקדש דוחה יום טוב!\u0004","ואם תאמר: \u0003נשבקה לבתר הכי\u0004 \u0005[נשאיר\u0006 את שתי הלחם \u0005לאחר מכן]\u0006 עד לאחר החג, \u0003ונבנייה\u0004 \u0005[ונבנה אותו]\u0006 את תוספת המקדש ביום שלאחר החג, \u0003וניקדשיה\u0004 \u0005[ונקדש אותו]\u0006 באכילתן למחר — הרי כבר \u0003איפסילא ליה\u0004 \u0005[נפסלה לו]\u0006 \u0003בלינה\u0004 של מוצאי החג!","ואם תאמר: \u0003נבנייה ממעלי יומא\u0004 \u0005[נבנה אותו בערב\u0006 החג\u0005]\u0006 \u0003ונשייר ביה פורתא\u0004 \u0005[בו מעט],\u0006 שאינו בנוי עד שיצא החג, ש\u0003עד קדיש יומא\u0004 \u0005[שיתקדש היום]\u0006 כלומר, בזמן שהחג יוצא, \u0003לאלתר נגמריה וניקדשיה\u0004 \u0005[מיד נגמור אותו ונקדש אותו]\u0006 קודם שייפסלו שתי הלחם בלינה — דבר זה גם כן אי אפשר, לפי ש\u0003אין בנין בית המקדש\u0004 נעשה \u0003בלילה.\u0004 וכפי ש\u0003אמר אביי: מנין שאין בנין בית המקדש בלילה? שנאמר: \"וביום הקים את המשכן\"\u0004 (במדבר ט, טו), \u0003ביום\u0004 אתה \u0003מקימו, בלילה אין\u0004 אתה \u0003מקימו. הלכך\u0004 (על כן) \u0003לא אפשר\u0004 בשתי הלחם, ולכן עושים זאת דווקא בשיירי מנחה של מצה.","שנינו במשנה שקידוש העיר והעזרה נעשה בתהלוכה \u0003ובשיר.\u0004 ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 כך היה הסדר, אומרים \u0003שיר של תודה\u0004 (\"מזמור לתודה\", תהלים ק) \u0003בכנורות ובנבלים ובצלצלים על כל פינה ופינה ועל כל אבן גדולה שבירושלים, ואומר\u0004 גם את המזמור: \u0003\"ארוממך ה' כי דליתני\"\u0004 (\"מזמור שיר חנוכת הבית\", תהלים ל), \u0003ו\u0004אומר \u0003שיר של פגעים\u0004 (תהלים צא, \"יושב בסתר עליון\"), \u0003ויש אומרין\u0004 שכינויו של מזמור זה הוא \u0003שיר של נגעים.\u0004","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהוא נקרא שיר של \u0003נגעים,\u0004 משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"ונגע לא יקרב באהלך\"\u0004 (תהילים צא י), \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שקוראים לו שיר של \u0003פגעים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]:\u0006 \u0003\"יפל מצדך אלף\u0004 ורבבה מימינך אליך לא יגש\" (תהילים צא ז).","\u0003ואומר\u0004 מן הפסוק \u0003\"ישב בסתר עליון בצל שדי יתלונן\"\u0004 (תהילים צא א) \u0003עד\u0004 שמסיים בפסוק \u0003\"כי אתה ה' מחסי עליון שמת מעונך\"\u0004 (תהילים צא ט), \u0003וחוזר ואומר: \"מזמור לדוד בברחו מפני אבשלום בנו ה' מה רבו צרי\"\u0004 (תהילים ג א) \u0003עד \"לה' הישועה על עמך ברכתך סלה\"\u0004 (תהילים ג ט) שהוא סוף המזמור.","מסופר, \u0003ר' יהושע בן לוי אמר להו להני קראי, וגאני\u0004 \u0005[היה אומר את המקראות האלה, והיה ישן\u0006 מתוך קריאתם\u0005].\u0006 ושואלים: \u0003היכי עביד הכי\u0004 \u0005[כיצד עשה כן]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יהושע בן לוי\u0004 עצמו: \u0003אסור להתרפאות בדברי תורה!\u0004 ומשיבים: \u0003להגן שאני\u0004 \u0005[שונה\u0006 הדבר\u0005]\u0006 שהוא רק מגן על עצמו באמירת מקראות אלה מפני נגעים ופגעים, ואינו מתרפא בהם.","ושואלים: \u0003ואלא כי\u0004 \u0005[כאשר]\u0006 ר' יהושע בן לוי \u0003אמר\u0004 שהדבר \u0003אסור\u0004 — הרי זה במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003מכה\u0004 (פצע) והוא אומר פסוקים כדי להתרפא ממנה; אולם \u0003אי דאיכא\u0004 \u0005[אם\u0006 במקרה \u0005שיש]\u0006 \u0003מכה\u0004 והוא אומר עליה פסוקים, האם זה רק \u0003אסור ותו לא\u0004 \u0005[ולא עוד]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הלוחש על המכה אין לו חלק לעולם הבא!\u0004 ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 שלא מדובר במשנה זו בלוחש סתם, אלא \u0003אמר ר' יוחנן: ברוקק\u0004 ואחר כך לוחש אותם פסוקים \u0003שנו,\u0004 וטעם הדבר — \u0003לפי שאין מזכירין שם שמים על הרקיקה.\u0004","שנינו במשנה שבסדר ההוספה על העיר והעזרה \u0003בית דין מהלכין ושתי תודות אחריהן\u0004 וכל ישראל אחריהם. ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003בית דין קמי\u0004 \u0005[לפני]\u0006 ה\u0003תודה אזלי\u0004 \u0005[הולכים\u0006 הם\u0005]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בכתוב שממנו למדנו סדר הקידוש: \"ואעמידה שתי תודות... \u0003וילך אחריהם הושעיה וחצי שרי יהודה\"\u0004 (נחמיה יב, לא— לב)! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]\u0006 במשנה, כך יש להבין: \u0003בית דין מהלכין, ו\u0004כיצד נעשה הדבר? \u0003שתי תודות מהלכות ובית דין אחריהם.\u0004","ומבררים: \u0003כיצד\u0004 בדיוק, באיזה אופן \u0003מהלכות\u0004 התודות? \u0003ר' חייא ור' שמעון ברבי\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: זו כנגד\u0004 (ליד) \u0003זו, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: זו אחר זו. מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003זו כנגד זו,\u0004 לשיטתו, התודה הנקראת במשנה \u0003הפנימית\u0004 היא \u0003הך דמקרבא\u0004 \u0005[זו\u0006 מבין השתיים \u0005שקרובה]\u0006 \u0003לחומה. מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003זו אחר זו, הפנימית\u0004 היא \u0003הך דמקרבא\u0004 \u0005[זו שקרובה]\u0006 \u0003לבית דין\u0004 כלומר, האחרונה מבין שתיהן, שהרי בית דין הולכים אחר התודות.","ומנסים להביא ראיה בענין זה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003הפנימית נאכלת והחיצונה נשרפת. בשלמא למאן דאמר\u0004 \u0005[נניח\u0006 לדעת \u0005מי שאומר]\u0006 \u0003זו אחר זו,\u0004 וה\"פנימית\" היא האחרונה מבין שתיהן, \u0003אמטו להכי\u0004 \u0005[משום כך]\u0006 \u0003פנימית נאכלת\u0004 — \u0003משום דאתיא\u0004 \u0005[שבאה]\u0006 \u0003חיצונה קמה\u0004 \u0005[קודם לה]\u0006 \u0003וקדשה לה\u0004 \u0005[ומקדשת אותה]\u0006 את התוספת, ומעתה הוא מקום קדוש שהתודה ראויה להיאכל בו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003זו כנגד זו,\u0004 הלוא \u0003תרוייהו בהדי הדדי קא מיקדשי\u0004 \u0005[שתיהן זו יחד עם זו\u0006 הן \u0005מקדשות]!\u0006 ומדוע הפנימית נאכלת והחיצונה נשרפת?","ושואלים: \u0003וליטעמיך\u0004 \u0005[ולשיטתך],\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003זו אחר זו, חדא מי מיקדשא\u0004 \u0005[אחת מהן\u0006 בלבד האם היא \u0005מקדשת]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"כל שלא נעשית בכל אלו\" תנן\u0004 \u0005[שנינו]\u0006 שאינה מתקדשת! \u0003ואפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי הכוונה היא \u0003באחת מכל אלו,\u0004 ולא בכל הדברים, הרי \u0003הני תרוייהו\u0004 \u0005[אלה\u0006 התודות \u0005שתיהן]\u0006 \u0003חדא מצוה\u0004 \u0005[מצוה אחת]\u0006 \u0003היא!\u0004","\u0003אלא אמר ר' יוחנן:\u0004"],["\u0003על פי נביא נאכלת ועל פי נביא נשרפת,\u0004 שהנביאים שהיו בזמן הקמת הבית השני הם שאמרו כיצד לעשות, ואין טעם בדבר.","שנינו במשנה: \u0003כל\u0004 תוספת \u0003שלא נעשית בכל אלו\u0004 אין הנכנס לשם כשהוא טמא חייב עליה, שאין קדושתה קדושה גמורה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בדבר, \u0003רב הונא אמר: \"בכל אלו\" תנן\u0004 \u0005[שנינו],\u0006 שאם לא נעשה אחד מכל אלה אין זה מועיל לקדש, עד שייעשו כולם. \u0003רב נחמן אמר: \"באחת מכל אלו\" תנן\u0004 \u0005[שנינו],\u0006 שדי באחד מן הדברים כדי לקדש קידוש גמור. ומפרטים את השיטות.","\u0003רב הונא אמר: \"בכל אלו\" תנן\u0004 \u0005[שנינו],\u0006 \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003קדושה ראשונה\u0004 של המקדש בימי דוד ושלמה \u0003קידשה לשעתה וקידשה לעתיד לבא,\u0004 וממילא היה מקום המקדש מקודש גם בימי בית שני, \u0003ועזרא\u0004 שקידש שוב את העיר — \u0003זכר\u0004 לקידוש ראשון \u0003בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא דעבד\u0004 \u0005[שעשה].\u0006 ולכן אף שלא היו שם אורים ותומים ומלך, מכל מקום השטח כולו קדוש בשלימות. אבל בזמן שרוצים להוסיף שטח חדש שלא היה קדוש מקדושה ראשונה מתחילה — יש צורך בכל אלו ואין להחסיר אחד מהם.","ואילו \u0003רב נחמן אמר: \"באחת מכל אלו\" תנן\u0004 \u0005[שנינו],\u0006 \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003קדושה ראשונה קידשה לשעתה ולא קידשה לעתיד לבא, ועזרא קדושי קדיש\u0004 \u0005[קידש]\u0006 את המקדש והעזרות \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא הוו\u0004 \u0005[היו]\u0006 \u0003אורים ותומים.\u0004 ומכאן, שאן צורך בכל הדברים כדי לקדש.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן,\u0004 הרי שנינו במשנתנו במפורש: \u0003\"כל שלא נעשית בכל אלו\".\u0004 אמר לו, \u0003תני\u0004 \u0005[שנה]\u0006 ותקן: \u0003\"באחת מכל אלו\".\u0004","ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003אבא שאול אומר: שני ביצעין\u0004 (ביצות) \u0003היו בהר המשחה\u0004 (הר הזיתים), \u0003תחתונה ועליונה, תחתונה נתקדשה בכל אלו\u0004 האמורים במשנתנו, בימי הבית הראשון, ויש בה קדושת ירושלים לכל דבר. \u0003עליונה לא נתקדשה בכל אלו, אלא בעולי גולה\u0004 (בבל), \u0003שלא במלך ושלא באורים ותומים.\u0004","\u0003תחתונה שהיתה קדושתה גמורה\u0004 — \u0003עמי הארץ נכנסין לשם, ואוכלין שם קדשים קלים\u0004 שנאכלים בכל ירושלים, \u0003אבל לא\u0004 היו אוכלים שם \u0003מעשר שני,\u0004 שהיו נוהגים חומרה בדבר זה. \u0003וחברים\u0004 (תלמידי חכמים) \u0003אוכלים שם\u0004 גם \u0003קדשים קלים ו\u0004גם \u0003מעשר שני.\u0004","\u0003עליונה שלא היתה קדושתה גמורה\u0004 — \u0003עמי הארץ היו נכנסין שם, ואוכלין שם קדשים קלים אבל לא מעשר שני, וחברים אין אוכלין שם לא קדשים קלים ולא מעשר שני. ומפני מה לא קידשוה,\u0004 את הביצה העליונה? \u0003שאין מוסיפין על העיר ועל העזרות אלא במלך ונביא, ואורים ותומים, ובסנהדרין של שבעים ואחד, ובשתי תודות ובשיר.\u0004","ושואלים: כיון שלא יכלו לעשות הכל כראוי \u0003ולמה קידשוה?\u0004 ותוהים על השאלה: \u0003למה קידשוה?! הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 ש\u0003לא קידשוה! אלא\u0004 כך יש לשאול: \u0003למה הכניסוה\u0004 לתוך החומה של העיר? ומשיבים: \u0003מפני ש\u0004מקום \u0003תורפה\u0004 (חולשה) \u0003של ירושלים היתה\u0004 הפינה הזו, \u0003ונוחה היא ליכבש משם,\u0004 ולכן היו צריכים להקיפה בחומה. והרי מכאן מוכח בפירוש שלא כדברי רב נחמן, שאמר שדי באחת מכל אלו כדי לקדש!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה האם קדושה ראשונה של ירושלים והמקדש קיימת לדורות, ואבא שאול סבור שבטלה הקדושה, וממילא היה צורך בכל אלו. ומה היא אותה מחלוקת? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אליעזר: שמעתי\u0004 במסורת, \u0003כשהיו בונין בהיכל\u0004 בימי עזרא, \u0003עשו\u0004 תחילה \u0003קלעים\u0004 (יריעות) כמחיצות \u0003להיכל,\u0004 קודם שבנו שם את הבנין מאבנים, \u0003ו\u0004גם עשו \u0003קלעים לעזרות, אלא שבהיכל\u0004 היו \u0003בונין מבחוץ\u0004 מחוץ לקלעים, \u0003ובעזרות\u0004 היו \u0003בונין מבפנים\u0004 לקלעים.","\u0003אמר ר' יהושע: שמעתי, שמקריבין\u0004 על המזבח \u0003אף על פי שאין בית\u0004 בנוי, ו\u0003אוכלין קדשי קדשים אף על פי שאין קלעים\u0004 לעזרה, וכן אוכלים \u0003קדשים קלים ומעשר שני\u0004 בירושלים \u0003אף על פי שאין חומה,\u0004 והטעם: \u0003מפני שקדושה ראשונה קידשה לשעתה וקידשה לעתיד לבא.\u0004 ונדייק מכאן: \u0003לאו\u0004 \u0005[האם אין]\u0006 ללמוד אתה \u0003מכלל\u0004 הדברים ש\u0003ר' אליעזר\u0004 שאמר שהיו שם קלעים \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003לא קידשה לעתיד לבא?\u0004 ואם כן מחלוקת תנאים היא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח זאת? \u0003דלמא דכולי עלמא\u0004 \u0005[שמא לדעת הכל]\u0006 \u0003קדושה ראשונה קידשה לשעתה וקידשה לעתיד לבא,\u0004 וגם ר' אליעזר סבור כך, \u0003ו\u0004אולם \u0003מר מאי דשמיע ליה קאמר\u0004 \u0005[חכם זה מה ששמע\u0006 במסורת \u0005אמר],\u0006 \u0003ומר מאי דשמיע ליה קאמר\u0004 \u0005[וחכם זה מה ששמע אמר]!\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003קלעים לר' אליעזר למה לי,\u0004 אם קדושה ראשונה נתקדשה גם לעתיד? \u0003לצניעותא בעלמא\u0004 \u0005[לצניעות בלבד]\u0006 שאין זה נאה שמקום ההיכל והעזרות יהיו בלא מחיצות!","\u0003אלא\u0004 יש לומר שנחלקו בענין זה של קדושה ראשונה \u0003הני תנאי\u0004 \u0005[תנאים אלה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 בענין הערים המוקפות חומה, שנימנו במשנה במסכת ערכין (לב,א), \u0003אמר ר' ישמעאל בר' יוסי: למה מנו חכמים\u0004 דווקא \u0003את אלו\u0004 במשנה? \u0003שכשעלו בני הגולה\u0004 בימי עזרא \u0003מצאו\u0004 את \u0003אלו וקידשום, אבל ראשונות בטלו\u0004 מקדושתם \u0003משבטלה הארץ\u0004 בחורבן הבית ובגלות; \u0003אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]\u0006 ש\u0003קדושה ראשונה קידשה לשעתה ולא קידשה לעתיד לבא.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא, \u0003אמר ר' ישמעאל בר' יוסי: וכי אלו\u0004 שנמנו במשנה \u0003בלבד היו? והלא כבר נאמר: \"ששים עיר כל חבל ארגב ממלכת עוג בבשן כל אלה ערים בצרות חומה גבהה\"\u0004 (דברים ג, ד— ה), משמע שהיו הרבה ערים מוקפות חומה בימי יהושע! \u0003אלא למה מנו חכמים את אלו? שכשעלו בני הגולה, מצאו אלו וקידשום.\u0004","ותוהים: \u0003קידשום השתא\u0004 \u0005[עכשיו]?\u0006 \u0003הא אמרינן לקמן דלא צריכא לקדושי\u0004 \u0005[הרי אומרים אנו בהמשך\u0006 הברייתא \u0005שאין צריך לקדש]!\u0006 \u0003אלא,\u0004 צריך לתקן: \u0003מצאו אלו ומנאום.\u0004","וממשיכה הברייתא: \u0003ולא אלו בלבד, אלא כל\u0004 עיר \u0003שתעלה בידך מסורת מאבותיך ש\u0004היתה \u0003מוקפת חומה מימות יהושע בן נון\u0004 — \u0003כל מצו‍ת אלו\u0004 של ערי חומה \u0003נוהגות בה, מפני שקדושה ראשונה קידשה לשעתה וקידשה לעתיד לבא.\u0004 ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' ישמעאל בר יוסי\u0004 על דברי \u0003ר' ישמעאל בר יוסי,\u0004 שדבריו בשתי הברייתות סותרים אלה את אלה!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003תרי תנאי אליבא\u0004 \u0005[שני תנאים\u0006 שנחלקו \u0005לפי שיטתו]\u0006 של \u0003ר' ישמעאל בר יוסי. איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר: \u0003חדא מינייהו\u0004 \u0005[\u0006ברייתא \u0005אחת מהן]\u0006 \u0003ר' אלעזר בר יוסי אמרה,\u0004 ולא ר' ישמעאל אחיו. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר בר יוסי אומר:\u0004 הכתוב בענין בתי ערי חומה \u0003\"אשר לוא חמה\"\u0004 (ויקרא כה, ל), שכתוב בו \"לא\" בא', וקוראים \"לו\" בו', בא ללמד: \u0003אף על פי שאין לו עכשיו\u0004 חומה \u0003והיה לו קודם לכן,\u0004 שלדעתו אף על פי שאין חומה עכשיו קדושה ראשונה לא בטלה. ומסתבר שהברייתא האחרונה — כשיטתו היא."],["שנינו במשנה: \u0003נטמא בעזרה ונעלמה ממנו טומאה וכו'.\u0004 ושואלים: \u0003טומאה בעזרה, מנלן\u0004 \u0005[מנין לנו]?\u0006 מנין שמתחייב גם על טומאה שכזו אם אינו יוצא מהעזרה, ולא רק כאשר נכנס לעזרה כשהוא כבר טמא? \u0003אמר ר' אלעזר, כתוב אחד אומר: \"את משכן ה' טמא\"\u0004 (במדבר יט, יג), \u0003וכתוב אחד\u0004 באותה פרשה עצמה \u0003אומר: \"כי את מקדש ה' טמא\"\u0004 (במדבר יט כ), והפסוק השני, \u0003אם אינו ענין לטומאה\u0004 (למי שנטמא) \u0003שבחוץ\u0004 לפני שנכנס למקדש, שזו כבר נאמרה בפסוק הקודם, \u0003תנהו ענין לטומאה ש\u0004נטמא בהיותו \u0003בפנים.\u0004","ושואלים: \u0003וקראי מיתרי\u0004 \u0005[ו\u0006כי \u0005הפסוקים\u0006 הללו \u0005מיותרים]\u0006 ודי היה באחד מהם? \u0003הא מיצרך צריכי\u0004 \u0005[הרי נחוצים\u0006 הם\u0005]!\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: אם נאמר \"משכן\" למה נאמר \"מקדש\"? ואם נאמר \"מקדש\" למה נאמר \"משכן\"?\u0004 ומשיב: \u0003אילו נאמר \"משכן\" ולא נאמר \"מקדש\", הייתי אומר: על\u0004 טומאת \u0003משכן יהא חייב,\u0004 \u0003שהרי\u0004 המשכן מקודש בעצמו שהוא \u0003משוח בשמן המשחה, ועל מקדש\u0004 שלא נמשח בשמן המשחה \u0003לא יהא חייב. ואם נאמר \"מקדש\" ולא נאמר \"משכן\", הייתי אומר: על מקדש יהא\u0004 אדם הנכנס בטומאה \u0003חייב, שהרי קדושתו קדושת עולם, ועל משכן לא יהא חייב\u0004 על כך לפי שקדושתו לא היתה אלא לזמנו, \u0003לכך\u0004 \u0003נאמר \"משכן\", לכך נאמר \"מקדש\"!\u0004","ומשיבים: \u0003ר' אלעזר\u0004 לא מייתור הפסוקים למד, אלא משינוי הלשון, \u0003הכי קא קשיא ליה\u0004 \u0005[\u0006ו\u0005כך היה קשה לו]:\u0006 \u0003מכדי\u0004 \u0005[הואיל]\u0006 ו\u0003משכן איקרי\u0004 \u0005[נקרא]\u0006 \u0003\"מקדש\", ו\u0004גם \u0003מקדש איקרי\u0004 \u0005[נקרא]\u0006 \u0003\"משכן\",\u0004 אם כן \u0003נכתוב\u0004 \u0005[שיכתוב]\u0006 \u0003או אידי ואידי\u0004 \u0005[זה וזה]\u0006 בשני המקראות הללו \u0003\"מקדש\" או אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003\"משכן\", \"משכן\" ו\"מקדש\"\u0004 בשינוי הלשון \u0003למה לי? שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005]\u0006 הן שגם על טומאה שנטמא בפנים מתחייב, והן שהדבר מתייחס גם למשכן וגם למקדש.","ומתקשים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003מקדש איקרי\u0004 \u0005[נקרא]\u0006 \u0003\"משכן\", דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונתתי משכני בתוככם\"\u0004 (ויקרא כו, יא), \u0003אלא משכן דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003\"מקדש\" מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אילימא מדכתיב\u0004 \u0005[אם תאמר ממה שנאמר]:\u0006 \u0003\"ונסעו הקהתים נשאי המקדש\"\u0004 (במדבר י, כא), ושם הרי מדובר על המשכן — אולם הפסוק \u0003ההוא בארון כתיב\u0004 \u0005[נאמר],\u0006 ו\"המקדש\" שם אין כוונתו למשכן אלא לדבר המקודש, שהוא ארון הקודש! \u0003אלא מהכא\u0004 \u0005[מכאן\u0006 מפסוק זה\u0005],\u0006 שנאמר: \u0003\"ועשו לי מקדש ושכנתי בתוכם\"\u0004 (שמות כה, ח), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך: \u0003\"ככל אשר אני מראה אותך את תבנית המשכן\"\u0004 (במדבר י ט).","שנינו במשנה: \u0003והשתחוה או ששהה כדי השתחואה. אמר רבא: לא שנו אלא שהשתחוה\u0004 בהיותו במקדש \u0003כלפי פנים\u0004 המקדש, שזו אכן נקראת השתחואה, שהרי משתחוה בדרך הנכונה, \u0003אבל\u0004 אם \u0003השתחוה כלפי חוץ,\u0004 אין זו עצמה נקראת השתחואה, ואז אם \u0003שהה\u0004 במקדש משך זמן השתחואה — \u0003אין\u0004 \u0005[כן],\u0006 חייב, \u0003לא שהה\u0004 — \u0003לא.\u0004","\u0003איכא דמתני לה אסיפא\u0004 \u0005[יש ששונים\u0006 את דברי רבא \u0005על סופה\u0006 של המשנה\u0005]:\u0006 \u0003או ששהה בכדי השתחואה,\u0004 ויש לדייק: \u0003מכלל\u0004 ש\u0003השתחואה גופה בעיא\u0004 \u0005[עצמה צריכה]\u0006 \u0003שהייה,\u0004 ולא די בעצם המעשה. ועל כך \u0003אמר רבא: לא שנו אלא שהשתחוה כלפי חוץ,\u0004 אז מתחייב אם שהה כשיעור השתחואה, \u0003אבל כלפי פנים\u0004 — \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא שהה\u0004 — מתחייב, \u0003והכי קאמר\u0004 \u0005[וכך הוא אומר]:\u0006 \u0003השתחוה כלפי פנים, או ששהה כדי השתחואה בהך\u0004 \u0005[בזו]\u0006 ה\u0003השתחואה\u0004 ש\u0003כלפי חוץ\u0004 — \u0003חייב.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היא\u0006 בדיוק\u0005]\u0006 \u0003השתחואה דאית\u0004 \u0005[שיש]\u0006 \u0003בה שהייה, והיכי דמי\u0004 \u0005[וכיצד היא]\u0006 \u0003השתחואה דלית\u0004 \u0005[שאין]\u0006 \u0003בה שהייה?\u0004 ומשיבים: \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה שהייה —\u0004 \u0003זו כריעה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003היא,\u0004 שמכופף את חלק גופו העליון. \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה שהייה\u0004 — היא השתחואה שיש עימה \u0003פישוט ידים ורגלים\u0004 על הארץ.","ושואלים: \u0003וכמה\u0004 הוא \u0003שיעור\u0004 אותה \u0003שהייה? פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה ר' יצחק בר נחמני וחד דעימיה\u0004 \u0005[ו\u0006חכם \u0005אחד שעימו],\u0006 \u0003ומנו\u0004 \u0005[ומי הוא\u0006 זה\u0005]?\u0006 \u0003ר' שמעון בן פזי; ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 את המסורת באופן זה: \u0003ר' שמעון בן פזי וחד דעימיה\u0004 \u0005[ואחד שעימו]\u0006 שנחלק איתו, \u0003ומנו\u0004 \u0005[ומי הוא]?\u0006 \u0003ר' יצחק בר נחמני; ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה האיש השני \u0003ר' שמעון בר נחמני; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כמימריה דהאי פסוקא\u0004 \u0005[כ\u0006משך זמן \u0005אמירתו של פסוק זה],\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כ\u0004זמן שאומרים \u0003מ\"ויכרעו\"\u0004 שבאמצע אותו פסוק \u0003לסיפא\u0004 \u0005[לסופו].\u0006 ומהו הפסוק? \u0003\"וכל בני ישראל ראים ברדת האש וכבוד ה' על הבית, ויכרעו אפים ארצה על הרצפה וישתחוו והודות לה' כי טוב כי לעולם חסדו\"\u0004 (דברי הימים ב ז, ג).","ובענין זה מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קידה\u0004 האמורה בכל מקום היא \u0003על אפים\u0004 כלומר, שמכופף את קומתו עד שנוגע בפניו בארץ, \u0003וכן הוא אומר: \"ותקד בת שבע אפים ארץ\"\u0004 (מלכים א א, לא). \u0003כריעה\u0004 היא \u0003על ברכים, וכן הוא אומר: \"מכרע על ברכיו\"\u0004 (מלכים א ח, נד). \u0003השתחואה\u0004 — \u0003זו פישוט ידים ורגלים\u0004 על הארץ, \u0003וכן אומר: \"הבוא נבוא אני ואמך ואחיך להשתחות לך ארצה\"\u0004 (בראשית לז, י) כלומר, שהשתחוואה היא כשנמצא כל כולו שטוח על הארץ.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 האם \u0003צריך שהייה למלקות\u0004 שאם התרו בו שלא יישאר בעזרה, האם רק אם נשאר שם כדי השתחויה הריהו מתחייב במלקות, \u0003או אין צריך שהייה למלקות,\u0004 והריהו מתחייב מיד במלקות? וצדדי השאלה: \u0003לקרבן גמירי\u0004 \u0005[למדנו]\u0006 שצריך \u0003שהייה, למלקות לא גמירי\u0004 \u0005[למדנו]\u0006 שצריך \u0003שהייה\u0004"],["\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003ב\u0004כל טומאת \u0003פנים גמירי\u0004 \u0005[למודים\u0006 אנו במסורת\u0005]\u0006 דין \u0003שהייה, לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003ל\u0004ענין \u0003קרבן ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003ל\u0004ענין \u0003מלקות?\u0004 שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 טמא ש\u0003תלה עצמו באויר עזרה\u0004 כשיעור השתחוואה, \u0003מהו\u0004 דינו? וצדדי השאלה: \u0003כי גמירי\u0004 \u0005[כאשר למדו,\u0006 קיבלו במסורת\u0005]\u0006 דין \u0003שהייה\u0004 הרי זה באשר ל\u0003שהייה\u0004 שהיא \u0003בת השתחואה\u0004 שאפשר לו להשתחוות, אבל זו \u0003דלאו\u0004 \u0005[שאינה]\u0006 \u0003בת השתחואה,\u0004 שהרי אינו יכול להשתחוות בעודו תלוי באוויר — \u0003לא גמירי\u0004 \u0005[למדו]\u0006 חיוב על כך. \u0003או דלמא\u0004 \u0005[שמא]\u0006 לגבי טומאה \u0003בפנים שהייה גמירי\u0004 \u0005[למדו],\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 שהייה \u0003בת השתחואה ולא שנא דלאו\u0004 \u0005[ואינו שונה\u0006 זו \u0005שאינה]\u0006 \u0003בת השתחואה?\u0004 אף שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ועוד בעניינים אלו \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: טימא עצמו במזיד, מהו\u0004 הדין לענין שהייה במקדש? וצדדי השאלה: האם דווקא לגבי מי שנטמא \u0003באונס גמירי\u0004 \u0005[למדו,\u0006 קיבלו במסורת\u0005]\u0006 דין \u0003שהייה,\u0004 ואולם לענין מי שנטמא \u0003במזיד לא גמירי\u0004 \u0005[למדו]\u0006 דין \u0003שהייה. או דלמא\u0004 \u0005[שמא]\u0006 \u0003ב\u0004כל טומאת \u0003פנים גמירי\u0004 \u0005[למדו]\u0006 \u0003שהייה, לא שנא\u0004 \u0005[אינו שונה]\u0006 היה זה \u0003באונס ולא שנא\u0004 \u0005[ואינו שונה]\u0006 היה זה \u0003במזיד?\u0004 אף שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד].\u0006","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: נזיר\u0004 השוהה \u0003בקבר\u0004 (בית הקברות), שאסור לנזיר להיטמא בטומאת המת, האם \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003שהייה\u0004 כדי \u0003ל\u0004התחייב \u0003מלקות\u0004 על האיסור שעובר בו, \u0003או אינו צריך?\u0004 וצדדי השאלה: האם נאמר כי \u0003בפנים\u0004 בבית המקדש \u0003גמירי\u0004 \u0005[למודים\u0006 אנו\u0005]\u0006 דין \u0003שהייה, בחוץ לא גמירי\u0004 \u0005[אין למודים]\u0006 דין \u0003שהייה,\u0004 ומיד מתחייב. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003ב\u0004דבר טומאה שבא ב\u0003אונס גמירי\u0004 \u0005[למודים\u0006 אנו\u0005]\u0006 דין \u0003שהייה, לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003בפנים ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003בחוץ?\u0004 שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה: \u0003בא לו בארוכה\u0004 — \u0003חייב, בקצרה\u0004 — \u0003פטור וכו'. אמר רבא: קצרה שאמרו\u0004 שפטור עליה, לאו דווקא שיוצא מיד, אלא \u0003אפילו\u0004 הולך בה \u0003עקב בצד גודל\u0004 (בפסיעות קטנות ביותר), \u0003ואפילו\u0004 הולך שם \u0003כל היום כולו.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: שהיות\u0004 שלא שהה כשיעור השתחוואה, אלא שהה פחות מזה, ושוב חזר ושהה מעט, \u0003מהו שיצטרפו?\u0004 ושואלים: \u0003ותיפשוט ליה מדידיה\u0004 \u0005[ותפתור לו\u0006 את הבעיה הזו \u0005משלו]\u0006 ממי שהלך לאט, שהרי אדם זה שוהה בתוך כדי הליכה כזו! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003ב\u0004ש\u0003לא שהה\u0004 כלל, אלא כל הזמן הוא הולך, ואילו רבא שואל במי שמפסיק בהליכתו ושוהה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003אביי מרבה\u0004 שאלה הפוכה מזו של רבא: אם \u0003בא לו בארוכה,\u0004 אבל שהה בדרכו רק \u0003שיעור\u0004 יציאה \u0003קצרה,\u0004 \u0003מהו?\u0004 האם \u0003שיעור\u0004 זמן מסויים \u0003גמירי\u0004 \u0005[למודים\u0006 אנו במסורת\u0005],\u0006 \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003בא לו בארוכה שיעור קצרה\u0004 — \u0003פטור. או דלמא\u0004 \u0005[שמא]\u0006 \u0003דוקא גמירי\u0004 \u0005[למודים\u0006 אנו\u0005]:\u0006 \u0003בארוכה\u0004 — \u0003חייב, בקצרה\u0004 — \u0003פטור? אמר ליה\u0004 \u0005[לו]:\u0006 במקרה זה \u0003לא נתנה ארוכה להדחות אצלו,\u0004 ובכל אופן שילך בה, ואפילו עשה אותה בריצה, חייב.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: אלא\u0004 הלכה זו \u0003דקיימא לן\u0004 \u0005[שמוחזקת בידינו]\u0006 ש\u0003טמא ששימש\u0004 שעבד במקדש, שדינו \u0003במיתה\u0004 בידי שמים, \u0003היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה]?\u0006 \u0003אי דלא\u0004 \u0005[אם שלא]\u0006 \u0003שהה\u0004 שם כדי השתחוויה — \u0003היכי עביד\u0004 \u0005[כיצד עשה]\u0006 \u0003עבודה\u0004 בפרק זמן קצר כל כך? \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003שהה\u0004 שם — \u0003בר\u0004 \u0005[בן]\u0006 \u0003כרת הוא,\u0004 ודינו חמור ממיתה בידי שמים!","\u0003אי אמרת בשלמא שיעורא גמירי\u0004 \u0005[נניח\u0006 \u0005אם אתה אומר\u0006 ש\u0005שיעור\u0006 זמן \u0005למדו\u0006 במסורת\u0005],\u0006 ואם לא שהה כדי השתחוואה והליכה בדרך הקצרה — פטור, \u0003משכחת לה\u0004 \u0005[מוצא אתה אותו]\u0006 מקרה שמשמש בטומאה בלא לעבור על כרת — \u0003דאניס נפשיה\u0004 \u0005[\u0006במקרה \u0005שדוחק עצמו]\u0006 ועובר במרוצה \u0003ב\u0004דרך ה\u0003קצרה ועבד\u0004 \u0005[ועושה]\u0006 \u0003עבודה,\u0004 ששיעור הזמן שהיה במקדש היה רק כשיעור הדרך הקצרה, שאינו חייב עליו כרת, ולכן נידון רק על מה שעבד עבודה בטומאה."],["\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 ש\u0003דוקא גמירי\u0004 \u0005[בדקדוק למדו\u0006 במסורת\u0005]\u0006 וכל ההולך בקצרה ושוהה כדי השתחוואה חייב, גם אם לא חרג מזמן ההליכה של הדרך הקצרה, \u0003היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה]\u0006 אפשרות זו?","\u0003אמר אביי: מאי קושיא\u0004 \u0005[מה הקושיה\u0006 בדבר\u0005]?\u0006 \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003כגון שבא\u0004 יצא מן המקדש \u0003בקצרה\u0004 אבל תוך כדי יציאתו \u0003הפך בצינורא\u0004 (כעין מזלג) את אחד מאברי הקרבן על המזבח. \u0003וכ\u0004דברי \u0003רב הונא,\u0004 ש\u0003אמר רב הונא: זר\u0004 (שאינו כהן) \u0003שהפך בצינורא\u0004 את אברי הקרבנות שעל המזבח — \u0003חייב מיתה\u0004 משום שהוא כמקטיר את הקרבנות, שהיא עבודת כהן.","ומבררים: ל\u0003גופא\u0004 \u0005[גופה]\u0006 של הלכה זו ש\u0003אמר רב הונא\u0004 ש\u0003זר שהפך בצינורא חייב מיתה, היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דלא הפך לה לא מיעכלי\u0004 \u0005[אם\u0006 במקרה \u0005שלולא היה הופך אותה לא היו מתעכלים\u0006 האיברים\u0005]\u0006 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שחייב על כך, שהרי מה שעשה היא עבודה של הקטרה! \u0003ואי דלא הפך בהו נמי מיעכלי\u0004 \u0005[ואם\u0006 במקרה \u0005ש\u0006גם אם \u0005לא היה הופך אותם גם כן היו מתעכלים\u0006 האיברים\u0005]\u0006 — \u0003מאי קא עביד\u0004 \u0005[מה הוא פועל\u0006 במה שעשה\u0005],\u0006 שהרי גם ללא מעשהו היו מתעכלים האיברים?","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקרה \u0003דאי לא הפך בהו מיעכלי בתרתי שעי\u0004 \u0005[שאם לא היה הופך בהם היו מתעכלים בשתי שעות],\u0006 \u0003והשתא מיעכלי בחד שעתא\u0004 \u0005[ועכשיו\u0006 על ידי מעשהו הם \u0005מתעכלים בשעה אחת\u0006 בלבד\u0005],\u0006 \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה משמיע לנו],\u0006 ש\u0003כל קרובי\u0004 \u0005[קירוב]\u0006 \u0003עבודה,\u0004 שגורם לה שתיעשה מהר יותר, אף היא \u0003עבודה היא.\u0004","ושבים אל הענין הכללי של הטמא שנכנס למקדש, ומביאים מה ש\u0003אמר ר' אושעיא: בעינא דאימא מילתא, ומסתפינא מחבריא\u0004 \u0005[רוצה אני לומר דבר, וחושש אני מן החברים\u0006 שיקשו עלי\u0005].\u0006 ומהו אותו שרצה להשמיעו? \u0003הנכנס לבית המנוגע\u0004 בנגע צרעת, שנאמר בתורה שהוא טמא, אם נכנס \u0003דרך אחוריו,\u0004 כאשר גבו נכנס תחילה לבית, \u0003ואפילו\u0004 נכנס כל הגוף \u0003כולו\u0004 בדרך זו \u0003חוץ מחוטמו\u0004 שנשאר מחוץ לבית — הרי הוא \u0003טהור, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והבא אל הבית...\u0004 יטמא עד הערב\" (ויקרא יד, מו), לומר \u0003דרך ביאה אסרה\u0004 (כלומר, טימאה) \u0003תורה.\u0004","\u0003ומסתפינא מחבריא\u0004 \u0005[וחושש אני מן החברים],\u0006 שיכולים להקשות עליה כך: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהדבר תלוי בדרך הביאה, אם נכנס \u0003כולו נמי\u0004 \u0005[גם כן]\u0006 היה צריך להיות טהור! \u0003אמר רבא:\u0004 יש להשיב על קושיה זו ולומר שאם היה נכנס לשם \u0003כולו\u0004 באופן זה, הריהו נטמא משום שהוא \u0003לא גרע\u0004 \u0005[אינו פחות]\u0006 \u0003מכלים שבבית\u0004 המנוגעים שהם טמאים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ופינו את הבית... \u0003ולא יטמא כל אשר בבית\"\u0004 (ויקרא יד לו).","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כשיטתו של ר' אושעיא, שבמקום בו נזכרת ביאה, מדובר דווקא בדרך ביאה: \u0003גגין הללו\u0004 שהיו בעזרה על גבי הלשכות — \u0003אין אוכלין שם קדשי קדשים, ואין שוחטין שם קדשים קלים,\u0004 לפי שאין בגגות הללו קדושת עזרה. \u0003וטמא שנכנס דרך גגין להיכל\u0004 — \u0003פטור,\u0004 \u0003שנאמר\u0004 באשה שנטמאה: \u0003\"ואל המקדש לא תבא\"\u0004 (ויקרא יב, ד), לומר: \u0003דרך ביאה\u0004 בדרך הרגילה שבאים למקדש \u0003אסרה תורה,\u0004 ולפיכך הנכנס למקדש בטומאה שלא כדרך שרגילים לבוא — אינו חייב. ומכאן יש ללמוד גם לענין בית המנוגע, שנאמרה בו ביאה — שרק הנכנס אל הבית דרך ביאה נטמא, וכדברי רב אושעיא.","שנינו במשנה: \u0003זו היא מצות עשה שבמקדש שאין חייבין עליה וכו'.\u0004 ושואלים: \u0003היכא קאי\u0004 \u0005[היכן הוא עומד]\u0006 כלומר, לאיזה ענין מתייחס התנא בדבריו \u0003דקאמר\u0004 \u0005[שהוא אומר]\u0006 \u0003\"זו היא\"\u0004 ובשונה מהלכה אחרת שאינה כן? שהרי לא הזכיר כלל ענין חיוב נוסף בזה! ומשיבים: \u0003התם קאי\u0004 \u0005[שם\u0006 הוא \u0005עומד],\u0006 במה ששנינו במסכת הוריות: \u0003אין חייבין\u0004 בית דין הגדול להביא פר חטאת על שגגתם, אם הורו בית דין הגדול בטעות \u0003על עשה ועל לא תעשה שב\u0004טומאת \u0003מקדש, ו\u0004כן","\u0003אין\u0004 אנשים שיש להם ספק אם חטאו בשגגה \u0003מביאין אשם תלוי על עשה ועל לא תעשה שבמקדש,\u0004 משום שאין דינים אלה שייכים אלא בעבירה שמביאים על שגגתה קרבן חטאת קבוע, ולא קרבן עולה ויורד כמו שהוא בעבירות אלו.","\u0003אבל חייבין\u0004 הציבור להביא פר חטאת אם שגגו בית הדין הגדול בהוראה \u0003על עשה ועל לא תעשה שבנדה, ומביאין\u0004 אנשים שיש להם ספק \u0003אשם תלוי על עשה ועל לא תעשה שבנדה.\u0004","\u0003וקאמר\u0004 \u0005[ו\u0006על כך \u0005הוא אומר]\u0006 במשנתנו: המצוה על הטמא לצאת מן המקדש \u0003זו היא מצות עשה שבמקדש שאין חייבין עליה,\u0004 אם הורו בית הדין שאין צורך לצאת מיד. \u0003ואיזו היא מצות עשה שבנדה\u0004 שדומה לזו שבמקדש, \u0003שחייבין עליה?\u0004 הרי זה במקרה ש\u0003היה משמש עם הטהורה, ואמרה לו \"נטמאתי\" ופירש מיד\u0004 — ש\u0003חייב, מפני שיציאתו\u0004 היא \u0003הנאה לו כביאתו.\u0004","ובבירור פרטי ענין זה של פרישה מאשה שנטמאה \u0003איתמר\u0004 \u0005[נאמר]\u0006 שדנו אמוראים, \u0003אביי אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' חייא בר רב: חייב שתים\u0004 (שתי חטאות) על שגגה זו. \u0003וכן אמר רבא אמר רב שמואל בר שבא אמר רב הונא: חייב שתים, חדא\u0004 \u0005[אחת]\u0006 חייב על ה\u0003כניסה\u0004 (שבא עליה מתחילה) \u0003וחדא\u0004 \u0005[ואחת]\u0006 על ה\u0003פרישה\u0004 שפרש מיד.","\u0003הוי\u0004 \u0005[היה\u0006 עוסק, מתקשה\u0005]\u0006 \u0003בה רבה: במאי\u0004 \u0005[במה]\u0006 מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה זה \u0003סמוך לוסתה\u0004 לזמן שבו היא עתידה לראות דם נידה, ובכל זאת בא עליה, \u0003ובמאן\u0004 \u0005[ובמי]\u0006 מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בתלמיד חכם,\u0004 הרי \u0003בשלמא\u0004 \u0005[נניח]\u0006 על ה\u0003כניסה ליחייב\u0004 \u0005[שיהיה חייב]\u0006 קרבן חטאת משום שהיה זה בשוגג, \u0003קסבר\u0004 \u0005[סבור היה]:\u0006 \u0003יכולני לבעול\u0004 לפני שתתחיל הוסת, \u0003אלא\u0004 על ה\u0003פרישה אמאי ליחייב\u0004 \u0005[מדוע\u0006 הוא \u0005חייב]\u0006 בחטאת? הרי \u0003מזיד הוא\u0004 כיון שהוא תלמיד חכם, ויודע שבמקרה שכזה אסור לו לפרוש מיד, ואין חטאת באה על המזיד!"],["\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003בעם הארץ\u0004 מדובר, שאינו יודע שאסור לבוא על אשתו סמוך לזמן וסתה, וגם אינו יודע שאסור לו לפרוש מיד במקרה שנטמאה בזמן תשמיש, אם כן \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 כניסתו ויציאתו נחשבות שגגה אחת, כיון שלא נודע לו שעבר עבירה קודם שעבר את העבירה השניה, והרי זה כמי ש\u0003אכל שני זיתי חלב בהעלם\u0004 (חוסר ידיעה) \u0003אחד הוא,\u0004 שאינו חייב אלא קרבן חטאת אחד. שהרי אף כאן, הגם שהיו שני מעשים המחייבים חטאת (כניסה ויציאה), הלוא היה זה רק העלם אחד של איסור נדה!","\u0003ואלא\u0004 צריך לומר שמדובר \u0003בשאין סמוך לוסתה,\u0004 ולא היה כלל לבועל לחשוש שמא תראה דם, \u0003ובמאן\u0004 \u0005[ובמי]\u0006 מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בתלמיד חכם\u0004 — \u0003ולא\u0004 על \u0003חדא\u0004 \u0005[אחת]\u0006 מהן \u0003לא מיחייב\u0004 \u0005[מתחייב]\u0006 חטאת, שכן על ה\u0003כניסה\u0004 (הביאה) עצמה — \u0003אנוס\u0004 הוא, על ה\u0003פרישה\u0004 לאחר שנודע לו — \u0003מזיד\u0004 הוא! \u0003אי\u0004 \u0005[אם]\u0006 \u0003בעם הארץ, חדא\u0004 \u0005[אחת]\u0006 \u0003הוא דמיחייב\u0004 \u0005[שמתחייב]\u0006 בשגגה, על ה\u0003פרישה!\u0004","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא: לעולם\u0004 מדובר שהיתה הביאה \u0003בסמוך לוסתה, ובתלמיד חכם,\u0004 אלא שהוא \u0003תלמיד חכם ל\u0004ענין הלכה \u0003זו\u0004 שיודע שאסור לבוא אל אשה סמוך לוסתה, אלא ששגג במה שחשב שיספיק לבעול קודם לכן, ומשנודע לו שנטמאה — מתחייב קרבן על שגגתו בכניסה, \u0003ואין תלמיד חכם לזו,\u0004 שאינו יודע שאסור לו לפרוש מיד מאשה שנטמאה בשעת תשמיש. והואיל ונודע לו קודם לפרישתו שעבר עבירה בכניסתו — אין זה העלם אחד, והרי הוא מתחייב בנפרד על שגגתו השניה.","\u0003אמר רבא: ותרוייהו תנינהו\u0004 \u0005[ושני\u0006 הדברים \u0005שנינו אותם]\u0006 שחייב עליהם חטאת, לענין \u0003כניסה תנינא\u0004 \u0005[שנינו],\u0006 ולענין \u0003פרישה תנינא\u0004 \u0005[שנינו].\u0006 והוא מפרט: \u0003פרישה תנינא\u0004 \u0005[שנינו],\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 במשנתנו: \u0003היה משמש עם הטהורה, ואמרה לו\u0004 תוך כדי תשמיש \u0003\"נטמאתי\" ופירש מיד\u0004 — \u0003חייב;\u0004","\u0003כניסה תנינא\u0004 \u0005[שנינו]\u0006 במסכת נדה: \u0003נמצא\u0004 כתם דם \u0003על שלו\u0004 על מטלית שהוא מקנח בה לאחר תשמיש, הרי זה ברור שדם זה בא מן האשה בשעה ששימש עימה, ולכן שניהם \u0003טמאין וחייבין בקרבן. מאי לאו\u0004 \u0005[האם אין]\u0006 מדובר פה שבא עליה \u0003בסמוך לוסתה, ו\u0004חייב חטאת על ה\u0003כניסה\u0004 על הביאה סמוך לוסתה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנא לרבא: לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 שמדובר \u0003בשלא סמוך לווסתה, ו\u0004חייב חטאת על ה\u0003פרישה,\u0004 שאמרה לו בשעת תשמיש שנטמאה, ופרש ממנה מיד, ולא המתין. \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003פרישה למה לי\u0004 לחזור ולשנות? \u0003הא תנא ליה\u0004 \u0005[הרי\u0006 כבר \u0005שנה אותה]\u0006 במשנתנו! יש להסביר: \u0003הא איצטריך לאשמועינן\u0004 \u0005[\u0006דבר \u0005זה הוצרך להשמיענו]\u0006 את המשכה של אותה משנה, שאם \u0003נמצא\u0004 כתם הדם \u0003על\u0004 המטלית \u0003שלה\u0004 — \u0003טמאים\u0004 הם רק \u0003בספק,\u0004 שמא בא הדם רק לאחר הביאה, \u0003ופטורין מן הקרבן. ואיידי דבעי מיתנא\u0004 \u0005[ומתוך שהיה צריך לשנות]\u0006 את המקרה ש\u0003נמצא על שלה, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003נמצא על שלו,\u0004 למרות שאין בו חידוש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אדא: מי מצית לאוקמה\u0004 \u0005[האם יכול אתה להעמיד אותה]\u0006 את המשנה \u0003ההיא בשלא סמוך לוסתה ו\u0004חייב על \u0003הפרישה? והא\u0004 \u0005[והרי]\u0006 \u0003\"נמצא\" קתני\u0004 \u0005[הוא שונה],\u0006 \u0003ו\"נמצא\" לבתר הכי\u0004 \u0005[לאחר מכן]\u0006 \u0003משמע,\u0004 שלאחר שפרש מן האשה נתברר לו שהיתה נדה, \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר שחייב על ה\u0003פרישה,\u0004 הלוא \u0003מעיקרא כי פריש ליה\u0004 \u0005[מתחילה כאשר פרש לו],\u0006 \u0003מעיקרא הויא\u0004 \u0005[\u0006עוד \u0005קודם לכן היתה\u0006 לו\u0005]\u0006 \u0003ידיעה,\u0004 שהרי בפירוש אמרה לו שנטמאה, ומה שייך כאן ענין מציאת הדם על המטלית?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב אדא: \u0003ציית מאי דקאמר\u0004 \u0005[הקשב\u0006 ל\u0005מה שאומר]\u0006 \u0003רבך\u0004 (רבינא) שיפה הוכיח לך. אמר לו: \u0003היכי מצית\u0004 \u0005[כיצד יכול אני להקשיב]\u0006 ולקבל את הסברו? \u0003דתניא עלה\u0004 \u0005[ששנויה\u0006 ברייתא \u0005עליה]\u0006 על משנה זו בענין \"נמצא על שלו\": \u0003זו היא מצות עשה שבנדה שחייבין עליה; ואם איתא\u0004 \u0005[יש,\u0006 נכון כדבריך\u0005]\u0006 שמדובר במשנה זו על כניסה, הרי \u0003מצות לא תעשה היא\u0004 שלא לבוא אל אשה בנידתה!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי תניתא\u0004 \u0005[אם שנית]\u0006 ברייתא זו אין לשונה מדוייקת, לפי ש\u0003חסר\u0004 בה הדבר, \u0003ותני הכי\u0004 \u0005[ושנה כך]:\u0006 כאשר נמצא על שלו \u0003זו היא מצות לא תעשה שבנדה שחייבין עליה.\u0004 ויש מקרה נוסף: \u0003היה משמש עם הטהורה ואמרה לו \"נטמאתי\", ופירש מיד —\u0004 \u0003חייב, זו היא מצות עשה שבנדה כו'.\u0004","ושבים לדון בדברי המשנה. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003פירש מיד\u0004 מן האשה שנטמאה — \u0003חייב.\u0004 ושואלים: אם כן \u0003היכי עביד\u0004 \u0005[כיצד יעשה\u0006 למעשה\u0005]?\u0006 \u0003אמר רב הונא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: נועץ עשר צפרניו בקרקע\u0004 כלומר, מתאפק ביותר ואינו עושה דבר \u0003עד שימות\u0004 האבר, כלומר, עד שלא יהיה קשה יותר, ורק אז פורש ממנה, \u0003וטוביה\u0004 \u0005[וטוב לו]\u0006 שיעשה כך.","\u0003אמר רבא: זאת אומרת\u0004 מדברים אלו יש ללמוד ש\u0003המשמש\u0004 באבר \u0003מת ב\u0004איסורי \u0003עריות —\u0004 \u0003פטור, דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003חייב, הכא מאי טעמא\u0004 \u0005[כאן,\u0006 במשנתנו, \u0005מה טעם]\u0006 \u0003פטור\u0004 אם ימתין ורק אז יפרוש — \u0003משום\u0004 ש\u0003אנוס הוא,\u0004 במה שהאשה נטמאה, ולא משום שהוא פורש באבר מת (שהרי המשמש מת מתחייב). ואולם \u0003אי\u0004 \u0005[אם]\u0006 \u0003אנוס הוא, כי\u0004 \u0005[כאשר]\u0006 \u0003פירש מיד\u0004 ובאיבר קשה \u0003נמי ניפטר\u0004 \u0005[גם כן שייפטר]\u0006 מאותה סיבה, הלוא \u0003אנוס הוא!\u0004","ודוחים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לעולם אימא\u0004 \u0005[אומר ]\u0006 \u0003לך\u0004 כי \u0003המשמש מת בעריות חייב, והכא מאי טעמא\u0004 \u0005[וכאן מה הטעם]\u0006 \u0003פטור —\u0004 \u0003משום\u0004 ש\u0003אנוס הוא. והא\u0004 \u0005[וזה]\u0006 ש\u0003אמרת\u0004 והקשית: \u0003כי פריש\u0004 \u0005[כאשר\u0006 הוא \u0005פורש]\u0006 \u0003מיד אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב?\u0004 משום \u0003שהיה לו לפרוש בהנאה מועטת\u0004 באבר מת, \u0003ופירש בהנאה מרובה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר חנן לאביי: אם כן\u0004 לשיטתך, \u0003מצינו\u0004 (מצאנו) הפרש בהלכה בין דרך \u0003ארוכה וקצרה בנדה,\u0004 שיציאתו באופן אחד (במהירות) עבירה היא, ויציאתו באופן אחר אינה עבירה,"],["\u0003ואנן\u0004 \u0005[ואנו]\u0006 דין זה דווקא \u0003במקדש תנן\u0004 \u0005[שנינו\u0006 אותו\u0005],\u0006 ואם היה גם בנדה, מן הראוי היה לכתוב גם בעניינה דבר זה! \u0003אלא\u0004 צריך לומר כך: \u0003משום דלא דמי\u0004 \u0005[שאינו דומה]\u0006 בפרטיו, שכן \u0003ארוכה דהכא\u0004 \u0005[של כאן\u0006 בנדה\u0005],\u0006 שצריך לשהות, דינה כמו \u0003קצרה דהתם\u0004 \u0005[של שם,\u0006 במקדש\u0005],\u0006 שההולך בדרך המהירה ביותר הוא העושה כראוי, \u0003ו\u0004דרך \u0003ארוכה דהתם\u0004 \u0005[של שם\u0006 במקדש\u0005],\u0006 דינה כמו \u0003קצרה דהכא\u0004 \u0005[של כאן\u0006 בנדה\u0005],\u0006 שחייב.","ועוד \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על דברי אביי בענין זה \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן: מי\u0004 \u0005[האם]\u0006 \u0003אמר אביי\u0004 בדין משנתנו \u0003אנוס הוא? אלמא\u0004 \u0005[מכאן]\u0006 שלדעתו במי שבא על אשתו \u0003בשלא סמוך לוסתה קאמרינן\u0004 \u0005[אומרים אנו]\u0006 מדובר, ולכן אנוס הוא. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אביי\u0004 הוא ש\u0003אמר\u0004 לעיל: \u0003חייב שתים,\u0004 על הכניסה ועל הפרישה, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003בסמוך לוסתה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ולכן אדם זה שוגג ומביא קרבן, ולא אנוס. ונמצאים דבריו סותרים זה את זה!","ומשיבים: \u0003כי איתמר\u0004 \u0005[כאשר נאמרו]\u0006 דברי \u0003אביי\u0004 לענין מי שחייב שתים, \u0003בעלמא איתמר\u0004 \u0005[בכלל נאמרו]\u0006 לגבי הבא על אשה סמוך לווסתה, ולאו במקרה של משנתנו, עליו אמר שאנוס הוא.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' יונתן בן יוסי בן לקוניא מר' שמעון בן יוסי בן לקוניא: אזהרה לבועל נדה מנין מן התורה? שקל קלא פתק ביה\u0004 \u0005[לקח רגב\u0006 אדמה, \u0005השליך עליו]\u0006 כבדרך גערה ואמר לו: וכי צריך לחפש מקור בתורה ל\u0003אזהרה לבועל נדה?\u0004 והרי בפירוש נאמר: \u0003\"ואל אשה בנדת טמאתה לא תקרב\"\u0004 (ויקרא יח, יט)!","ומסבירים את כוונת השאלה: \u0003אלא, אזהרה\u0004 למקרה המובא במשנתנו, \u0003למשמש עם הטהורה ואמרה לו \"נטמאתי\"\u0004 ש\u0003לא ניפריש\u0004 \u0005[יפרוש]\u0006 \u0003מיד, מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אמר חזקיה\u0004 בתשובה לשאלה זו, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ואם שכב ישכב איש אותה \u0003ותהי נדתה עליו\"\u0004 (ויקרא טו, כד), לומר: \u0003אפילו בשעת נדתה\u0004 כשהיא נהיית נדה \u0003תהא עליו\u0004 באיסור נדה, שלא יפרוש ממנה מיד.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא שיש מצות \u0003עשה\u0004 בדרך הפרישה מנדה בשעת תשמיש, \u0003לא תעשה מנלן\u0004 \u0005[מנין לנו]\u0006 שיש בכך? \u0003אמר רב פפא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ואל אשה בנדת טומאתה \u0003לא תקרב\"\u0004 (ויקרא יח, יט), ומסביר: \u0003\"לא תקרב\" נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תפרוש הוא,\u0004 שפעמים פירוש המלה \"קרב\" הוא הפוך, ענין של פרישה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"האמרים קרב אליך אל תגש בי כי קדשתיך\"\u0004 (ישעיהו סה, ה), הרי ש\"קרב אליך\" משמעו — התרחק ממנו.","כיון שהוזכר כאן שיש איסור לבוא על אשה סמוך לווסתה, מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר בפרשת הנדה: \u0003\"והזרתם את בני ישראל מטמאתם\"\u0004 (ויקרא טו, לא), \u0003אמר ר' יאשיה: מיכן\u0004 (מכאן) \u0003אזהרה לבני ישראל שיפרשו מנשותיהן סמוך לוסתן. וכמה\u0004 הוא \"סמוך\"? \u0003אמר רבה: עונה\u0004 כלומר, שיעור של יום או לילה.","\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחאי:\u0004 \u0003כל שאינו פורש מאשתו סמוך לוסתה, אפילו הויין\u0004 \u0005[היו]\u0006 \u0003לו בנים\u0004 הראויים להיות גדולים וקדושים \u0003כבני אהרן\u0004 — \u0003מתים\u0004 בעוון זה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והזרתם את בני ישראל מטמאתם... והדוה בנדתה\"\u0004 (ויקרא יח, לא— לג), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הכתוב: \u0003\"אחרי מות\u0004 שני בני אהרן\" (ויקרא טז, א).","וכן \u0003אמר ר' חייא בר אבא אמר ר' יוחנן\u0004 בענין זה: \u0003כל הפורש מאשתו סמוך לוסתה\u0004 — \u0003הויין\u0004 \u0005[יהיו]\u0006 \u0003לו בנים זכרים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"להבדיל בין הטמא ובין הטהר\"\u0004 (ויקרא יא, מז), \u0003ו\u0004נאמר \u0003סמיך ליה\u0004 \u0005[סמוך לו]:\u0006 \u0003\"אשה כי תזריע וילדה זכר\"\u0004 (ויקרא יב, ב). הרי שמי שנבדל מן הטומאה, כגון זה הפורש מאשתו סמוך לזמן טומאתה — זוכה לבנים זכרים. \u0003ר' יהושע בן לוי אמר: הויין\u0004 \u0005[יהיו]\u0006 \u0003לו בנים ראויין ל\u0004הורות \u0003הוראה\u0004 (הלכה), \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"להבדיל...\u0004 בין הטמא ובין הטהור \u0003ולהורות\u0004 את בני ישראל את כל החוקים\" (ויקרא י, י— יא). ואגב פרשה זו מביאים דרשה דומה של אותם כתובים.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: כל המבדיל על היין\u0004 (ולא על משקה אחר) \u0003במוצאי שבתות\u0004 — \u0003הויין\u0004 \u0005[יהיו]\u0006 \u0003לו בנים זכרים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"להבדיל בין הקדש ובין החול\u0004 ובין הטמא ובין הטהור\" (ויקרא י, י), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 שוב: \u0003\"להבדיל בין הטמא ובין הטהור\"\u0004 (ויקרא יא, מז), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]:\u0006 \u0003\"אשה כי תזריע\"\u0004 (ויקרא יב, ב). \u0003ר' יהושע בן לוי אמר:\u0004 כל המבדיל על היין במוצאי שבתות — יהיו לו \u0003בנים\u0004 ה\u0003ראוין להוראה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"להבדיל\u0004 בין הקדש ובין החול... \u0003ולהורות\"\u0004 (ויקרא י, י— יא).","ועוד בענין זכייה בבנים זכרים, \u0003אמר ר' בנימין בר יפת אמר ר' אלעזר: כל המקדש את עצמו\u0004 ונוהג בצניעות \u0003בשעת תשמיש\u0004 המטה — \u0003הויין\u0004 \u0005[יהיו]\u0006 \u0003לו בנים זכרים, שנאמר: \"והתקדשתם והייתם קדשים\"\u0004 (ויקרא יא, מד), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]:\u0006 \u0003\"אשה כי תזריע\"\u0004 (ויקרא יב, ב).","נאמר במשנה, \u0003ר' אליעזר אומר: השרץ ונעלם ממנו כו',\u0004 שסמיכות המלה \"ונעלם\" ל\"שרץ\" (ויקרא ה, ב), באה לומר שחייב רק על העלם שרץ ולא על העלם מקדש. ור' עקיבא אמר שלמדים ממה שנאמר \"ונעלם ממנו והוא טמא\" (ויקרא ה, ב) שחייב על העלם טומאה ולא על העלם מקדש. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]?\u0006 שהרי שניהם מסכימים להלכה אחת!","\u0003אמר חזקיה: שרץ ונבלה איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שיודע מתחילה שנטמא ואינו יודע אם בשרץ או נבלה. \u0003ר' אליעזר\u0004 שלמד מ\"השרץ ונעלם\", \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003עד\u0004 ש\u0003ידע\u0004 תחילה \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשרץ איטמי\u0004 \u0005[נטמא]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בנבלה איטמי\u0004 \u0005[נטמא],\u0006 ואם אינו יודע — אינו מביא קרבן זה. \u0003ור' עקיבא סבר: לא בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003עד\u0004 ש\u0003ידע\u0004 פרט זה, ש\u0003כיון\u0004 ש\u0003ידע דאיטמא בעולם\u0004 \u0005[שנטמא בכלל],\u0006 \u0003לא צריך\u0004 לדעת \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשרץ איטמי\u0004 \u0005[נטמא]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בנבלה איטמי\u0004 \u0005[נטמא].\u0006","\u0003וכן אמר עולא: שרץ ונבלה איכא בינייהו\u0004 \u0005[יש ביניהם].\u0006 ודברים אלה לא אמר עולא במפורש, אלא ש\u0003עולא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין דברי \u0003ר' אליעזר\u0004 כאן לדברי \u0003ר' אליעזר\u0004 במקום אחר, \u0003ומשני\u0004 \u0005[ומתרץ].\u0006 וכך הקשה: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' אליעזר: בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003עד\u0004 ש\u0003ידע אי\u0004 \u0005[אם]\u0006 \u0003בשרץ איטמי\u0004 \u0005[נטמא]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בנבלה איטמי\u0004 \u0005[נטמא]?\u0006","\u0003ורמינהי\u0004 \u0005[והשליך\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא בענין מי שאכל חתיכה של איסור אבל אינו יודע אם היה זה חלב או נותר, וכן שעשה מלאכה ביום אסור במלאכה ואינו יודע אם היה זה בשבת או ביום הכיפורים. וכיוצא בזה הבא על אשה באיסור ואינו יודע אם היתה זו אשתו הנדה או אחותו, שר' אליעזר מחייב חטאת ור' יהושע פוטר. \u0003אמר ר' אליעזר: מה נפשך\u0004 (רצונך)? הרי אם \u0003חלב אכל\u0004 — \u0003חייב\u0004 חטאת, אם \u0003נותר אכל\u0004 — \u0003חייב\u0004 חטאת! וכן אם \u0003שבת חילל\u0004 — \u0003חייב,\u0004 אם \u0003יום הכפורים חילל\u0004 — \u0003חייב!\u0004 וכיוצא בזה, אם \u0003אשתו נדה בעל\u0004 — \u0003חייב, אחותו בעל\u0004 — \u0003חייב.\u0004 ואף שאינו יודע איזה איסור בדיוק עשה, הרי יודע שעבר עבירה שיש בה איסור כרת, וחייב קרבן חטאת!","\u0003אמר לו ר' יהושע, הרי הוא אומר\u0004 בקרבן חטאת: \u0003\"או הודע אליו חטאתו אשר חטא בה\"\u0004 (ויקרא ד, כג), \u0003עד שיודע לך במה חטא.\u0004 הרי ר' אליעזר עצמו סבור שאין חשוב לדעת מה בדיוק הוא האיסור!","\u0003ומשני\u0004 \u0005[ומתרץ]\u0006 עולא: \u0003התם\u0004 \u0005[שם\u0006 בחיוב חטאת\u0005]\u0006 \u0003\"אשר חטא והביא\"\u0004 (ויקרא ד, כג) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ודי שנודע לו שחטא ב\u0003חטא כל שהוא. הכא\u0004 \u0005[כאן]\u0006 במטמא מקדש, \u0003מכדי כתיב\u0004 \u0005[הואיל ונאמר]\u0006 בתחילה \"אשר תגע \u0003בכל דבר טמא\"\u0004 (ויקרא ה, ד), אם כן מה שנאמר מיד אחר כך \u0003\"או בנבלת שרץ טמא\"\u0004 (ויקרא ה, ד) \u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003עד\u0004 ש\u0003ידע אי\u0004 \u0005[אם]\u0006 \u0003בשרץ איטמי\u0004 \u0005[נטמא],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בנבלה איטמי\u0004 \u0005[נטמא].\u0006","ושואלים: \u0003ור' עקיבא,\u0004 שאינו דורש כן, מה משיב הוא על כך? מדוע אינו דורש כן יתור זה? ומשיבים: הוא סבור כי \u0003איידי\u0004 \u0005[מתוך]\u0006"],["\u0003דבעי למיכתב\u0004 \u0005[שצריך לכתוב]\u0006 ולפרט טומאת ה\u0003בהמה וחיה,\u0004 ודבר זה נחוץ לנו ללמוד ממנו \u0003ל\u0004מה שאמר \u0003רבי\u0004 (לעיל שבועות ז,א), \u0003כתיב נמי\u0004 \u0005[נאמר גם כן]\u0006 \u0003שרץ,\u0004 אף שאין בכך חידוש ולימוד. ודבר זה הוא \u0003כדתנא דבי\u0004 \u0005[כ\u0006שיטת \u0005התנא בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 שאומר: \u0003כל פרשה שנאמרה\u0004 בתורה וחזרה \u0003ונשנית\u0004 פעם נוספת, \u0003לא נשנית אלא בשביל דבר\u0004 אחד \u0003שנתחדש בה,\u0004 אף על פי שאין כולה חידוש.","ושואלים: \u0003ור' אליעזר\u0004 הסבור כי בשאר חטאות אינו צריך לדעת במה בדיוק חטא, \u0003האי\u0004 \u0005[\u0006המילה \u0005הזו]\u0006 \u0003\"בה\"\u0004 שנזכרה בכתוב, שממנה למד ר' יהושע, \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בה]?\u0006 מה הוא למד ממנה? ומשיבים: לדעתו הרי זה להדגיש שחייב רק על מעשה שנתכוון לעשותו, \u0003פרט למתעסק,\u0004 שלא היה מודע לכך שהוא עושה מעשה זה. כמי שהיה מתעסק בדבר אחר, ותוך כדי כך עשה עבירה, שאין זה נחשב כשוגג החייב בקרבן. עד כאן דנו בהסברו של חזקיה למחלוקת ר' אליעזר ור' עקיבא במשנתנו.","\u0003ור' יוחנן אמר:\u0004 אין בין ר' אליעזר ור' עקיבא הבדל בהלכה כלל, אלא \u0003משמעות דורשין\u0004 בלבד \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שהם חולקים רק בדבר המקור בתורה להלכה זו. \u0003וכן אמר רב ששת: משמעות דורשין איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שכן \u0003רב ששת\u0004 היה \u0003מחליף\u0004 את שיטת \u0003ר' אליעזר לר' עקיבא ו\u0004של \u0003ר' עקיבא לר' אליעזר\u0004 ולא הקפיד בדיוק הדברים, משום שסבר שאין ביניהם הבדל להלכה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004 לדעת ר' אליעזר ור' עקיבא, אם היה \u0003העלם זה וזה בידו,\u0004 שנעלמו ממנו גם הטומאה וגם המקדש, \u0003מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הרי העלם טומאה בידו, ו\u0004לכן \u0003חייב\u0004 על כך. ודוחים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003הרי העלם מקדש בידו, ו\u0004לכן \u0003פטור!\u0004","\u0003אמר רב אשי: חזינן\u0004 \u0005[רואים אנו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004שום ה\u0003טומאה קא פריש\u0004 \u0005[הוא פורש]\u0006 כשנודע לו — \u0003הרי\u0004 נמצא ש\u0003העלם טומאה\u0004 היה \u0003בידו וחייב, אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004שום ה\u0003מקדש קא פריש\u0004 \u0005[הוא פורש]\u0006 כשנודע לו — \u0003הרי העלם מקדש בידו ופטור. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 זו אינה ראיה, \u0003כלום פריש\u0004 \u0005[פורש]\u0006 הוא \u0003ממקדש אלא משום\u0004 שנודע לו גם על ה\u0003טומאה,\u0004 שאם לא כן מדוע יפרוש מן המקדש? ולהיפך, \u0003כלום פריש\u0004 \u0005[פורש]\u0006 הוא \u0003מ\u0004פני ה\u0003טומאה אלא משום\u0004 שנכנס ל\u0003מקדש! אלא לא שנא\u0004 \u0005[אין\u0006 זה \u0005שונה],\u0006 ובאופן כזה אין להוכיח.","ועוד נושא אחד הקשור לידיעות הטומאה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 היו \u0003שני שבילין\u0004 במקום מסויים, \u0003אחד\u0004 מהם היה \u0003טמא,\u0004 כגון שהיה מת קבור בו, \u0003ואחד\u0004 היה \u0003טהור,\u0004 ולא היה ברור איזה מהשבילים הטמא, \u0003והלך\u0004 אדם בשביל ה\u0003ראשון ולא נכנס\u0004 למקדש, ואחר כך הלך \u0003ב\u0004שביל ה\u0003שני,\u0004 ושכח שהוא טמא \u0003ונכנס\u0004 למקדש \u0003—\u0004 הרי זה \u0003חייב\u0004 קרבן, שוודאי נטמא באחד השבילים, ונכנס למקדש בטומאה.","ומקרה אחר: \u0003הלך ב\u0004שביל \u0003ראשון ונכנס\u0004 למקדש, ואחר כך \u0003הזה\u0004 מי חטאת להיטהר מספק טומאת המת, \u0003ו\u0004לאחר שבעה ימים \u0003שנה\u0004 והיזה, כדין המיטהר, \u0003וטבל. ואחר כך הלך בשני ונכנס\u0004 למקדש — הרי זה \u0003חייב\u0004 קרבן משום כניסה למקדש בטומאה, שהרי אחד השבילים טמא בודאי, והלוא נכנס למקדש לאחר שהיה באחד מהם. \u0003ר' שמעון פוטר\u0004 בזה, משום שבשתי הפעמים שנכנס לא היתה ודאות שהוא טמא, שהרי לאחר הפעם הראשונה נטהר. \u0003ור' שמעון בן יהודה פוטר בכולן משום ר'\u0004 \u0003שמעון.\u0004","ושואלים: \u0003בכולן\u0004 פטור,"],["\u0003ואפילו בקמייתא\u0004 \u0005[ב\u0006מקרה \u0005הראשון],\u0006 שעבר בשני השבילים ולא נטהר בינתיים? הרי \u0003ממה נפשך\u0004 \u0005[רצונך],\u0006 מכל צד שתרצה \u0003טמא הוא,\u0004 שהרי באחד משני השבילים בוודאי נטמא! \u0003אמר רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שהלך ב\u0004שביל ה\u0003ראשון, ו\u0004אחר כך \u0003בשעה שהלך בשני שכח שהלך בראשון, דהויא ליה\u0004 \u0005[שהריהי לו]\u0006 הידיעה שנעלמה ממנו בזמן שנכנס למקדש רק \u0003מקצת ידיעה,\u0004 שכאשר נכנס למקדש, נעלמה ממנו רק הידיעה שהלך בשביל השני. והעלם ידיעה זו לעצמה לא היה מחייב אותו קרבן (שהרי ספק הוא אם נטמא שם).","\u0003ובהא קא מיפלגי\u0004 \u0005[ובזה הם חלוקים],\u0006 \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 בשם ר' שמעון \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 ש\u0003מקצת ידיעה\u0004 של טומאה דינה \u0003ככל ידיעה, ור' שמעון\u0004 בן יהודה בשם ר' שמעון \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 ש\u0003מקצת ידיעה ככל ידיעה.\u0004","שנינו בברייתא: \u0003הלך בראשון ונכנס, הזה ושנה וטבל, חזר והלך בשני ונכנס\u0004 — \u0003חייב, ור' שמעון פוטר.\u0004 ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003חייב\u0004 לשיטת התנא הראשון? הלוא \u0003ספק ידיעה\u0004 של טומאה \u0003הוא\u0004 שנעלם ממנו כל פעם שנכנס למקדש! \u0003אמר ר' יוחנן: כאן\u0004 בענין זה של טומאת מקדש וקדשיו \u0003עשו ספק ידיעה כידיעה\u0004 גמורה. \u0003וריש לקיש אמר: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' ישמעאל היא,\u0004 ש\u0003אמר: לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 כלל \u0003ידיעה\u0004 של טומאה \u0003בתחלה\u0004 קודם שנכנס למקדש, ודי אם נודע לו בסוף שהיה טמא.","","ומעירים: \u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 בין דברי \u0003ר' יוחנן\u0004 על דברי \u0003ר' יוחנן, ורמי\u0004 \u0005[ו\u0006כן \u0005משליכים,\u0006 מראים סתירה\u0005]\u0006 בין דברי \u0003ריש לקיש\u0004 על דברי \u0003ריש לקיש. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אכל ספק חלב ונודע\u0004 לו שהיה זה ספק חלב, ושוב אכל \u0003ספק חלב\u0004 אחר \u0003ונודע\u0004 לו — \u0003רבי אומר: כשם ש\u0004אם נודע לו שאכל חלב ודאי \u0003מביא חטאת על כל אחד ואחד\u0004 מן החלבים, אם אכל ונודע לו, וחזר ואכל ושוב נודע לו — \u0003כך מביא אשם תלוי על כל אחד ואחד,\u0004 אם לאחר כל אכילה נודע לו שאכל ספק חלב. \u0003ר' שמעון בן יהודה ור' אלעזר בר' שמעון אמרו משום ר' שמעון:\u0004 למרות שנודע לו שאכל ספק חלב בין כל אכילה ואכילה \u0003אינו מביא אלא אשם תלוי אחד, שנאמר\u0004 באשם התלוי: \"והביא איל תמים... \u0003על שגגתו אשר שגג\"\u0004 (ויקרא ה, יח), לומר: \u0003התורה ריבתה\u0004 בלשון זו \u0003שגגות הרבה ואשם תלוי אחד,\u0004 לומר שעל שגגות הרבה מביא אשם אחד. ונחלקו ריש לקיש ור' יוחנן בהבנת דברי רבי, באיזה מקרה בדיוק אמר שמביא חטאת על כל אחד ואחד.","","\u0003ואמר ריש לקיש, כאן שנה רבי\u0004 ש\u0003ידיעות ספיקות\u0004 הן \u0003מתחלקות לחטאות\u0004 שאם ייוודע לו לאחר מכן שמה שאכל היה חלב ודאי, יצטרך להביא שתי חטאות על החלבים שאכל קודם, למרות שהידיעה שחילקה בין שני החלבים היתה ידיעת ספק. \u0003ור' יוחנן אמר:\u0004 אין רבי אומר שידיעות ספק מחלקות גם לענין חטאות, אלא רק קבע כלל: \u0003כשם שידיעות ודאי בעלמא\u0004 \u0005[בכלל]\u0006 \u0003מתחלקות לחטאות,\u0004 במקרה שאכל חלב ונודע לו שאכל חלב ודאי, ונעלם ממנו ושוב אכל, \u0003כך ידיעות ספק מתחלקות לאשמות\u0004 תלויים. הרי שבמחלוקת זו סבור ר' יוחנן שידיעת ספק אינה נחשבת כידיעה, וריש לקיש סבור שהיא נחשבת כידיעה. ובניגוד למה שאמרו לעיל!","","ומוסיפים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מדברי \u0003ר' יוחנן\u0004 על דברי \u0003ר' יוחנן לא קשיא\u0004 \u0005[אינו קשה],\u0006 אפשר להסביר שר' יוחנן דייק בדבריו ואמר כי \u0003כאן\u0004 בהלכה זו של טומאת מקדש וקדשיו דווקא \u0003עשו\u0004 ספק ידיעה כידיעה, \u0003ולא בכל התורה כולה עשו,\u0004 ויש טעם להבדלה זו, כי \u0003הכא\u0004 \u0005[כאן]\u0006 בטומאת המקדש \u0003הוא\u0004 ש\u0003לא כתיבא\u0004 \u0005[כתובה]\u0006 \u0003ידיעה בהדיא\u0004 \u0005[במפורש],\u0006 אלא \u0003מ\u0004מה שנאמר \u0003\"ונעלם\" הוא דקא אתי\u0004 \u0005[שבא]\u0006 שצריך שתהיה לו ידיעה שנעלמה, ואם כן די גם בידיעה שאינה גמורה. \u0003ו\u0004אולם, \u0003לא בכל התורה כולה עשו\u0004 ספק ידיעה כידיעה — משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"או הודע אליו\u0004 חטאתו\" (ויקרא ד כח), לומר ש\u0003ידיעה מעלייתא בעינן\u0004 \u0005[מעולה אנו צריכים].\u0006 \u0003אלא ל\u0004דעת \u0003ריש לקיש, אדמוקים ליה\u0004 \u0005[עד ש\u0006הוא \u0005מעמיד את\u0006 ההלכה \u0005הזו]\u0006 של שני שבילים, \u0003כר' ישמעאל\u0004 שאינו מצריך ידיעה בתחילה, \u0003נוקמה\u0004 \u0005[יעמיד אותה]\u0006 \u0003כרבי\u0004 שהוא סבור שידיעות ספק נחשבות כידיעות! ומשיבים: ריש לקיש \u0003הא קא משמע לן\u0004 \u0005[דבר זה\u0006 עצמו \u0005משמיע לנו],\u0006 ש\u0003ר' ישמעאל לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003ידיעה בתחלה\u0004 לענין טומאת מקדש וקדשיו.","","ותוהים: \u0003פשיטא דלא בעי\u0004 \u0005[פשוט שאינו צריך],\u0006 \u0003מדלא מייתרי ליה קראי\u0004 \u0005[מכיון שאין הכתובים מיותרים לו\u0006 לשיטתו\u0005],\u0006 שר' עקיבא למד מייתור זה שצריך ידיעה גם בתחילה, ואילו לדעתו \u0003\"ונעלם\"\u0004 (ויקרא ה, ד) בא לומר ענין אחר — \u0003דמיחייב\u0004 \u0005[שחייב]\u0006 \u0003על העלם מקדש!\u0004 ודוחים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כי לית ליה מקראי\u0004 \u0005[כאשר אין לו\u0006 הלכה זו הרי זה \u0005מן המקרא]\u0006 שאינו דורש כן את הכתובים, \u0003אבל מגמרא אית ליה\u0004 \u0005[מן המסורת יש לו]\u0006 הלכה זו, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ריש לקיש שלדעת ר' ישמעאל אין צורך בידיעה בתחילה.","","\u0003שבועות\u0004 ביטוי שמביא עליהן קרבן עולה ויורד, ששנינו שהן \u0003שתים שהן ארבע,\u0004 מה הן? אמר \u0003\"שבועה שאוכל\" ו\u0004\"שבועה \u0003שלא אוכל\",\u0004 \"שבועה \u0003שאכלתי\", ו\u0004\"שבועה \u0003שלא אכלתי\".\u0004","אם נשבע \u0003\"שבועה שלא אוכל\" ואכל כל שהוא\u0004 (אפילו פחות כזית, שהוא שיעור אכילה בכל מקום) — \u0003חייב, דברי ר' עקיבא. אמרו לו לר' עקיבא: היכן מצינו\u0004 (מצאנו) דוגמא לכך \u0003באוכל כל שהוא שהוא חייב,\u0004 שאתה אומר \u0003שזה חייב? אמר להם ר' עקיבא: וכי היכן מצינו ב\u0004מי ש\u0003מדבר ומביא קרבן\u0004 על כך, \u0003שזה מדבר\u0004 כלומר, מוציא שבועה מפיו \u0003ומביא קרבן?\u0004 ואם כן על הפרת שבועתו הוא מתחייב, ולא על האכילה.","תחילה באים לברר את לשון המשנה: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שלשון \u0003\"שאוכל\", דאכילנא משמע\u0004 \u0005[שאוכל משמעו]?\u0006 \u0003ורמינהי\u0004 \u0005[ומקשים\u0006 ומשליכים, מראים סתירה על כך\u0005]\u0006 ממה ששנינו במשנה במסכת נדרים, שאם אמר אדם: \u0003\"שבועה לא אוכל לך\"\u0004 (אצלך, או משלך), או: \u0003\"שבועה שאוכל לך\",\u0004 או: \u0003\"לא שבועה שלא אוכל לך\"\u0004 — בכל שבועות אלה \u0003אסור\u0004 באכילה. הרי שהשבועה \"שאוכל\" משמעה — שלא אוכל!","\u0003אמר אביי: לעולם\u0004 \"שאוכל\" \u0003דאכילנא משמע\u0004 \u0005[שאוכל משמעו],\u0006 אלא \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 כי יש הבדל בין שני אופנים של שבועה כזו: \u0003כאן\u0004 במסכת נדרים, מדובר \u0003ב\u0004מי שהיו \u0003מסרבין\u0004 (מפצירים) \u0003בו לאכול,\u0004 וכשהוא אומר \"שבועה שאוכל לך\" כוונתו שהוא מסרב, שאינו רוצה. \u0003כאן\u0004 במשנתנו, מדובר \u0003בשאין\u0004"],["\u0003מסרבין בו לאכול.\u0004","מתניתין \u0005[משנתנו]\u0006 מדברת \u0003בשאין מסרבין בו לאכול,\u0004 ואם כן יש לפרש ביטוי זה כפשוטו, שנשבע שיאכל. ואילו \u0003ברייתא\u0004 כלומר, המשנה האחרת מדברת \u0003במסרבין בו לאכול וקאמר\u0004 \u0005[והוא אומר]\u0006 \u0003\"לא אכילנא\u0004 \u0005[אוכל]\"\u0006\u0003ו\"לא אכילנא\u0004 \u0005[אוכל]\",\u0006 \u0003דכי קא משתבע\u0004 \u0005[שכאשר הוא נשבע]\u0006 על כך ואומר \"שאוכל לך\", \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]\u0006 כך כוונתו לומר: \u0003שבועה שלא אוכל.\u0004","\u0003רב אשי אמר, תני\u0004 \u0005[שנה\u0006 באותה משנה\u0005]\u0006 במסכת נדרים: \u0003\"שבועה שאי אוכל לך\".\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מאי למימרא\u0004 \u0005[מה\u0006 בא \u0005לומר]\u0006 במשנה במקרה זה? הרי בפירוש אמר שאינו אוכל! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003לישניה דאיתקילא ליה\u0004 \u0005[לשונו\u0006 היא \u0005שנכשלה לו],\u0006 שרצה לומר \"שאוכל\" ואמר \"שאי אוכל\", \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין חוששים לכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"מבטא\"\u0004 האמור בתורה הוא \u0003שבועה, \"אסר\"\u0004 הוא \u0003שבועה,\u0004 הגדרתו של ה\u0003איסור\u0004 שיש ב\u0003אסר, אם אתה אומר: אסר\u0004 הוא \u0003שבועה\u0004 — הרי הוא \u0003חייב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פטור.\u0004 ותוהים על לשון הברייתא, \u0003\"אם אתה אומר: אסר\u0004 הוא \u0003שבועה\"? והא\u0004 \u0005[והרי]\u0006 כבר \u0003אמרת\u0004 ש\u0003איסר שבועה הוא!\u0004","\u0003אמר אביי, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003\"מבטא\"\u0004 הרי זה \u0003שבועה\u0004 ממש, ואילו \u0003איסור\u0004 הוא \u0003מיתפיס\u0004 \u0005[התפסה]\u0006 \u0003בשבועה,\u0004 שאומר על דבר או מעשה מסויים שיהא אסור עליו כמו זה שכבר נאסר בו בשבועה. ובאשר ל\u0003איסור\u0004 של ה\u0003איסר\u0004 מה דינו? \u0003אם אתה אומר: מיתפיס\u0004 \u0005[התפסה]\u0006 \u0003בשבועה כמוציא שבועה מפיו דמי\u0004 \u0005[נחשב]\u0006 — הרי הוא \u0003חייב\u0004 קרבן (בשגגה), ומלקות (במזיד) אם עובר על מה שאסר על עצמו באיסר, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פטור.\u0004","ומדקדקים בהסברו של אביי: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 אתה לומד ש\u0003\"מבטא\" שבועה\u0004 הוא? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"או נפש כי תשבע לבטא בשפתים\"\u0004 (ויקרא ה, ד). לומר ש\"לבטא בשפתים\" הריהו אחד ממיני השבועה. אולם אם כן \u0003איסר נמי\u0004 \u0005[גם כן]\u0006 הריהו שבועה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל נדר וכל שבעת אסר\"\u0004 (במדבר ל, יד)!","\u0003אלא ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 אתה למד ש\u0003איסר\u0004 רק \u0003מיתפס\u0004 \u0005[התפסה]\u0006 \u0003בשבועה הוא? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"או אסרה אסר על נפשה בשבעה\"\u0004 (במדבר ל יא), ומשמע שאסרה עצמה בדבר שיש עליו כבר איסור שבועה, אם כן,","\u0003מבטא נמי\u0004 \u0005[גם כן]\u0006 ייחשב התפסה בשבועה, שכן \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"לכל אשר יבטא האדם בשבעה\"\u0004 (ויקרא ה, ד)!","\u0003אלא אמר אביי: \"מבטא\"\u0004 שהוא \u0003שבועה\u0004 למדים \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"ואם היו תהיה לאיש ונדריה עליה או מבטא שפתיה אשר אסרה על נפשה\"\u0004 (במדבר ל, ז), \u0003ואילו שבועה לא קאמר\u0004 \u0005[אמר\u0006 פסוק זה\u0005],\u0006 ואם כן \u0003במאי\u0004 \u0005[במה]\u0006 \u0003אסרה עצמה? ב\u0004לשון \u0003\"מבטא\",\u0004 הרי שמבטא הוא שבועה.","\u0003רבא אמר: לעולם אימא\u0004 \u0005[יכול אני לומר]\u0006 \u0003לך\u0004 ש\u0003מיתפיס\u0004 \u0005[התפסה]\u0006 \u0003בשבועה לאו\u0004 \u0005[אינה]\u0006 \u0003כמוציא שבועה מפיו דמי\u0004 \u0005[נחשבת],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך הוא אומר]\u0006 בברייתא: \u0003\"מבטא\"\u0004 הוא \u0003שבועה, \"איסר\" נמי\u0004 \u0005[גם כן]\u0006 הוא עצמו לשון \u0003שבועה,\u0004 אלא שלשון \"איסר\" יש לה כמה מובנים, כי \u0003אסריה דאיסר\u0004 \u0005[איסורו של איסר]\u0006 \u0003הטילו הכתוב בין נדר לשבועה,\u0004 לומר שאם \u0003הוציאו\u0004 מפיו (השתמש בו) \u0003בלשון נדר\u0004 — הרי זה \u0003נדר,\u0004 אם \u0003בלשון שבועה\u0004 — הרי זה \u0003שבועה.\u0004","ושואלים: \u0003היכן הטילו\u0004 הכתוב לאיסר בין נדר לבין שבועה? שנאמר \u0003\"ואם בית אישה נדרה או אסרה אסר על נפשה בשבעה\" וגו'\u0004 (במדבר ל יא), שנמצא לשון איסר בפסוק בין שני לשונות אלה.","\u0003ו\u0004מעירים: מה שנחלקו לעיל אביי ורבא, \u0003אזדו לטעמייהו\u0004 \u0005[הולכים לשיטתם],\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בדינו של \u0003מתפיס בשבועה\u0004 — \u0003אביי אמר: כמוציא שבועה מפיו דמי\u0004 \u0005[נחשב\u0006 הוא\u0005],\u0006 \u0003ורבא אמר: לאו\u0004 \u0005[לא]\u0006 \u0003כמוציא שבועה מפיו דמי\u0004 \u0005[נחשב\u0006 הוא\u0005].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003איזה איסר האמור בתורה? האומר: \"הרי עלי שלא אוכל בשר ושלא אשתה יין כיום שמת בו אביו\",\u0004 או \u0003\"כיום שמת בו פלוני\",\u0004 או \u0003\"כיום שנהרג בו גדליה בן אחיקם\",\u0004 או \u0003\"כיום שראה\u0004 את \u0003ירושלים בחורבנה\"\u0004 — הרי זה \u0003אסור. ואמר שמואל: והוא\u0004 (ובלבד) \u0003שנדור ובא מאותו היום\u0004 שהתפיס בו, כלומר שביום שמת אביו אסר על עצמו בנדר שלא לאכול בשר ולשתות יין.","ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי, מדמתפיס\u0004 \u0005[כיון שהמתפיס]\u0006 \u0003בנדר\u0004 נחשב ל\u0003נדר,\u0004 אף ה\u0003מתפיס\u0004 \u0003בשבועה\u0004 נחשב כ\u0003שבועה\u0004 עצמה."],["\u0003אלא לרבא קשיא\u0004 \u0005[קשה],\u0006 שהרי מכאן עולה שיש התפסה בנדר!","ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך רבא\u0004 בתשובה לשאלה זו, \u0003תריץ ואימא הכי\u0004 \u0005[תרץ ואמור כך]:\u0006 \u0003איזהו איסר\u0004 (איסור) \u0003נדר האמור בתורה? האומר: \"הרי עלי שלא אוכל בשר ושלא אשתה יין כיום שמת בו אביו\",\u0004 או: \u0003\"כיום שנהרג בו פלוני\", ואמר שמואל: והוא שנדור ובא מאותו היום.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"איש כי ידר נדר לה' \"\u0004(במדבר ל, ג), בלשון כפולה, לומר — \u0003עד שידור\u0004 כלומר, יתפיס את נדרו \u0003בדבר הנדור,\u0004 דבר שנאסר בנדר.","שנינו בברייתא: \u0003\"כיום שמת בו אביו\".\u0004 ושואלים: הואיל ולדברי שמואל מדובר כשהיה נדור מאותו יום, \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, הרי כן הוא הדין בכל יום שהיה נדור בו, ומדוע הוזכר יום שמת בו אביו? ומשיבים: \u0003\"כיום שנהרג בו גדליה בן אחיקם\" איצטריך ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005],\u0006 כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003כיון דכי\u0004 \u0005[שאם]\u0006 \u0003לא נדר\u0004 שלא יאכל בשר וישתה יין באותו יום \u0003נמי\u0004 \u0005[גם כן]\u0006 היה \u0003אסור,\u0004 שהרי הוא יום של תענית (צום גדליה), \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003נדר\u0004 מאכילה ושתיה באותו יום \u0003נמי לא הויא עליה\u0004 \u0005גם כן לא חל עליו]\u0006 \u0003איסור\u0004 נדר, \u0003והאי\u0004 \u0005[וזה]\u0006 שהוא נודר עכשיו \"כיום שנהרג בו גדליה בן אחיקם\" \u0003לאו מיתפיס\u0004 \u0005[לא התפסה]\u0006 \u0003בנדר הוא\u0004 אלא באיסור, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאם הוסיף ונדר באותו יום — הרי זה נחשב כיום שנדר בו, ויכול להתפיס בנדר זה נדר אחר.","ומעירים: \u0003ואף ר' יוחנן סבר לה להא\u0004 \u0005[סבור כזו שאמר]\u0006 \u0003רבא,\u0004 ש\"איסר\" אינו התפסה בשבועה. \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: \"מבטא לא אוכל לך\",\u0004 או \u0003\"איסר לא אוכל לך\"\u0004 — הרי זו \u0003שבועה,\u0004 כשם שאמר רבא.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר\u0004 בשם \u0003ר' יוחנן:\u0004 אם נשבע להבא \u0003\"אוכל\" ו\u0004כן \u0003\"לא אוכל\"\u0004 ולא קיים את דבריו — הרי זו שבועת \u0003שקר, ואזהרתיה מהכא\u0004 \u0005[ואזהרתו,\u0006 איסור הלאו שיש בזה הוא \u0005מכאן]:\u0006 שנאמר \u0003\"לא תשבעו בשמי לשקר\"\u0004 (ויקרא יט, יב). אבל אם נשבע \u0003\"אכלתי\" ו\"לא אכלתי\"\u0004 והוא לא עשה כן, ושיקר בשבועתו — הרי זו שבועת \u0003שוא, ואזהרתיה מהכא\u0004 \u0005[ואזהרתו מכאן]:\u0006 \u0003\"לא תשא את שם ה' אלהיך לשוא\"\u0004 (שמות כ, ז).","\u0003קונמות\u0004 כלומר, נדרים (שאמר \"קונם עלי דבר פלוני\", שהוא לשון של נדר) שעבר עליהם — \u0003עובר ב\u0004מה שנאמר \u0003\"לא יחל דברו\"\u0004 (במדבר ל, ג).","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003\"שוא\" ו\"שקר\"\u0004 שנאסרו בתורה \u0003אחד הן. מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003מ\u0004מה ש\u0003\"שוא\"\u0004 כוונתו שבועה המתייחסת \u0003לשעבר, אף \"שקר\" נמי\u0004 \u0005[גם כן]\u0006 שבועה \u0003לשעבר? אלמא\u0004 \u0005[מכאן]\u0006 יוצא ש\u0003\"אכלתי\" ו\"לא אכלתי\"\u0004 שבועת \u0003שקר הוא,\u0004 שלא כדברי יוחנן, שאמר ששקר הוא דווקא שבועה לעתיד!","ומשיבים: \u0003מידי איריא\u0004 \u0005[כלום יש קשר]\u0006 בין הדברים? אפשר לומר כי \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זה כמו שהוא וזה כמו שהוא]\u0006 כלומר, שבועת שוא ושבועת שקר הם דברים שונים, זה לעבר וזה לעתיד, \u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003\"דבר אחד הן\"?\u0004 הכוונה ש\u0003בדיבור אחד נאמרו\u0004 במתן תורה, \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"זכור\u0004 את יום השבת לקדשו\" (שמות כ, ז) \u0003ו\"שמור\u0004 את יום השבת לקדשו\" (דברים ה, יב) \u0003בדיבור אחד נאמרו,\u0004 והרי זה \u0003מה שאין יכול הפה לדבר\u0004 שני דברים כאחד, \u0003ומה שאין האוזן יכול לשמוע\u0004 בבת אחת.","ומקשים: \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 \"זכור\" ו\"שמור\" \u0003בדיבור אחד נאמרו,\u0004 כדי ללמדנו דבר הלכה, כמו שאמר \u0003רב אדא בר אהבה,\u0004 ש\u0003אמר רב אדא בר אהבה: נשים חייבות בקידוש היום\u0004 של שבת מ\u0003דבר תורה,\u0004 למרות שהוא מצות עשה שהזמן גרמה, ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"זכור\" ו\"שמור\",\u0004 ושני הדברים הריהם כדיבור אחד, ולכן \u0003כל\u0004 מי \u0003שישנו\u0004 (שנכלל) \u0003בשמירה\u0004 כלומר, שמוזהר על שמירת השבת ואסור לחללה, \u0003ישנו\u0004 גם \u0003ב\u0004מצוה של \u0003זכירה\u0004 של השבת, מצות עשה שבה. \u0003והני נשי\u0004 \u0005[ונשים אלו]\u0006 \u0003הואיל ואיתנהו\u0004 \u0005[וישנן]\u0006 \u0003בשמירה\u0004 שהן חייבות לשמור את השבת במצוות לא תעשה שיש בה, \u0003איתנהו נמי\u0004 \u0005[ישנן גם כן]\u0006 \u0003ב\u0004מצות \u0003זכירה,\u0004 בקידוש. \u0003אלא הכא למאי הלכתא מיבעי ליה\u0004 \u0005[כאן לאיזו הלכה נצרך לו]\u0006 שייאמרו בדיבור אחד?","\u0003אלא\u0004 יש להסביר ש\"שווא ושקר אחד הן\", כוונתו: \u0003כשם שלוקה על שוא, כך לוקה נמי\u0004 \u0005[גם כן]\u0006 \u0003על שקר.\u0004","ותוהים: \u0003כלפי לייא\u0004 \u0005[לאן]\u0006 אתה הולך? להיפך צריך לומר, שהרי פשוט יותר לומר שילקה על שבועת שקר, שיש בה מעשה (כגון שנשבע \"שלא אוכל\" ואכל) מאשר על שבועת שווא שאין בה אלא דיבור! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003כשם שלוקה על שקר, כך לוקה נמי\u0004 \u0005[גם כן]\u0006 \u0003על שוא.\u0004","ואומרים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005],\u0006 ומה חידוש יש בדבר? \u0003האי\u0004 \u0005[זה]\u0006 \u0003לאו והאי\u0004 \u0005[וזה]\u0006 \u0003לאו\u0004 ומדוע יש מקום להניח כי על זה ילקה ועל זה לא ילקה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 בענין זה \u0003כדאמר ליה\u0004 \u0005[כמו שאמר לו]\u0006 \u0003רב פפא לאביי:\u0004 שמה שנאמר \"לא ינקה ה' את אשר ישא את שמו לשוא\" (שמות כ, ז) אולי כוונתו — \u0003לא ינקה כלל,\u0004 שאין לו תקנה, ואין עונש שיכול לכפר את חטאו,"],["\u0003קא משמע לן כדשני ליה\u0004 \u0005[משמיע לנו כמו שתירץ לו]\u0006 אביי (להלן בעמוד זה).","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \"שוא ושקר אחד הן\" כוונתו: \u0003כשם שמביא קרבן על\u0004 שבועת \u0003שקר\u0004 (\"אוכל\" ו\"לא אוכל\") \u0003כך מביא קרבן על\u0004 שבועת \u0003שוא\u0004 (\"אכלתי\" ו\"לא אכלתי\"), \u0003ו\u0004שיטת \u0003ר' עקיבא היא,\u0004 ש\u0003מחייב\u0004 קרבן לעל שבועה \u0003לשעבר כ\u0004על שבועה \u0003להבא.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על דברי רב דימי בשם ר' יוחנן, ששבועה לעתיד היא שבועת שקר, מברייתא: \u0003אי זו היא שבועת שוא?\u0004 אם \u0003נשבע לשנות את הידוע לאדם,\u0004 שנשבע על דבר שאנשים יודעים שאינו נכון, \u0003שבועת שקר\u0004 — ש\u0003נשבע להחליף\u0004 כלומר, שנשבע לשנות מן האמת. ודבר זה הוא רק בשבועה על העבר! ומתקנים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן: \u0003נשבע ומחליף,\u0004 שנשבע (לעשות או לא לעשות) ומחליף (משנה) במעשהו ממה שנשבע.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' ירמיה אמר ר' אבהו אמר ר' יוחנן:\u0004 הנשבע \u0003\"אכלתי\" ו\"לא אכלתי\",\u0004 ולא היה הדבר נכון — הרי זה שבועת \u0003שקר, ואזהרתיה\u0004 \u0005[ואזהרתו]\u0006 היא \u0003מ\"לא תשבעו בשמי לשקר\"\u0004 (ויקרא יט, יב). אם נשבע לעתיד: \u0003\"אוכל\" ו\"לא אוכל\",\u0004 ועבר על שבועתו — \u0003עובר ב\"לא יחל דברו\"\u0004 (במדבר ל, ג). \u0003ואי זו היא שבועת שוא?\u0004 ש\u0003נשבע לשנות את הידוע לאדם,\u0004 שהכל יודעים שהיא שוא.","\u0003אמר רב פפא: הא\u0004 \u0005[\u0006אימרה \u0005זו]\u0006 של \u0003ר' אבהו\u0004 בשם ר' יוחנן — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמרה],\u0006 \u0003אלא מכללא איתמר\u0004 \u0005[מכלל\u0006 הדברים \u0005נאמרה],\u0006 שהסיקו אותה מדברים אחרים שאמר. ש\u0003אמר רב אידי בר אבין אמר רב עמרם אמר רב יצחק אמר ר' יוחנן,\u0004 כך \u0003ר' יהודה אומר משום\u0004 (בשם) \u0003ר' יוסי הגלילי: כל לא תעשה שבתורה,\u0004 אם הוא \u0003לאו שיש בו מעשה\u0004 ועבר עליו ועשהו — \u0003לוקין עליו, ושאין בו מעשה\u0004 — \u0003אין לוקין עליו, חוץ מנשבע, ו\u0004כן \u0003מימר\u0004 בהמת קודש בבהמת חולין, שאומר שתהא קדושה במקומה, שנאסר הדבר בתורה (ויקרא כז, י), \u0003ומקלל את חבירו בשם\u0004 (ויקרא יט, יד), שעל כל אלה נענשים במלקות אף על פי שאין בהם מעשה אלא דיבור בלבד.","ושואלים: \u0003נשבע מנלן\u0004 \u0005[מנין לנו]\u0006 שלוקים עליו? \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בר יוחאי, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא תשא את שם ה' אלהיך לשוא כי לא ינקה\u0004 ה' את אשר ישא את שמו לשוא\" (שמות כ, ז), לומר: \u0003בית דין של מעלה אין מנקין אותו,\u0004 שאין לו כפרה בתשובה בלבד, \u0003אבל בית דין של מטה מלקין אותו ומנקין אותו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי, דלמא הכי קאמר רחמנא\u0004 \u0005[שמא כך אמרה התורה]:\u0006 \u0003לא ינקה כלל,\u0004 שאין לו תקנה כלל לעוונו! והשיב לו: \u0003אי כתיב\u0004 \u0005[אם היה כתוב]\u0006 רק \u0003\"כי לא ינקה\"\u0004 — הייתי מפרש \u0003כדקאמרת\u0004 \u0005[כמו שאתה אומר],\u0006 \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"כי לא ינקה ה' \",\u0004 יש לדייק: \u0003ה' הוא\u0004 ש\u0003אינו מנקה, אבל בית דין של מטה מלקין אותו ו\u0004בכך \u0003מנקין אותו.\u0004","ושאלו: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 דין זה לגבי \u0003שבועת שוא,\u0004 שלוקה למרות שאין בו מעשה, על \u0003שבועת שקר מנלן\u0004 \u0005[מנין לנו]\u0006 שמלקים אותו? \u0003ר' יוחנן דידיה\u0004 \u0005[משלו]\u0006 ולא בשם התנאים \u0003אמר:\u0004 נאמר \u0003\"לשוא\" \"לשוא\" שתי פעמים\u0004 באותו פסוק \"לא תשא את שם ה' אלקיך לשוא\", ובהמשך הדברים \"כי לא ינקה ה' את אשר ישא את שמו לשוא\", ומייתור לשון זה נלמד: \u0003אם אינו ענין לשבועת שוא\u0004 שכבר נאמרה פעם אחת, \u0003תנהו ענין לשבועת שקר.\u0004","\u0003והוי\u0004 \u0005[והיה עוסק,\u0006 מתקשה\u0005]\u0006 \u0003בה ר' אבהו: האי\u0004 \u0005[זו]\u0006 \u0003שבועת שקר\u0004 שלמד ר' יוחנן שמלקים עליה מ\"לשוא\" \"לשוא\", \u0003היכי דמי\u0004 \u0005[כיצד היא]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003\"שבועה שלא אוכל\" ואכל\u0004 — \u0003לאו שיש בו מעשה הוא,\u0004 שהרי כאשר אכל עשה מעשה, וממילא הוא לוקה! \u0003ואלא\u0004 ש\u0003אמר \"שבועה שאוכל\" ולא אכל,\u0004 אולם \u0003האי מי\u0004 \u0005[זה האם]\u0006 הוא \u0003לוקה? והא איתמר\u0004 \u0005[והרי נאמר]\u0006 לגבי מי שאמר: \u0003\"שבועה שאוכל ככר זו היום\", ועבר היום ולא אכלה\u0004 — \u0003ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]:\u0006 \u0003אינו לוקה\u0004 על כך,","\u0003ר' יוחנן אמר: אינו לוקה משום דהוה\u0004 \u0005[שהריהו]\u0006 \u0003לאו שאין בו מעשה,\u0004 שהרי במה שעבר על שבועתו לא עשה מעשה, \u0003וכל לאו שאין בו מעשה אין לוקים עליו. וריש לקיש אמר: אינו לוקה משום דהוה\u0004 \u0005[שהריהו]\u0006 \u0003התראת ספק,\u0004 שהרי צריך להתרות בו סמוך לזמן העבירה, והרי אין יודעים האם כוונתו שלא לאכול או לא, ובכל רגע ספק הוא, \u0003והתראת ספק לא שמה התראה!\u0004","\u0003ואמר ר' אבהו: תהא\u0004 (יש להעמיד) הלכה זו שלוקה על שבועת שקר למרות שאין בה מעשה \u0003ב\"אכלתי\" ו\"לא אכלתי\",\u0004 ומכאן למד רבין שלשיטת ר' אבהו בשם ר' יוחנן, הנשבע \"אכלתי\" ו\"לא אכלתי\" עובר ולוקה משום שבועת שקר. ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה,\u0006 מדוע \u0005שונה]\u0006 שבועה לשעבר משבועה לעתיד לענין זה, שהנשבע \"אכלתי\" ולא אכל לוקה אף שלא עשה מעשה, ואילו הנשבע שיאכל ולא אכל אינו לוקה משום שלא עשה מעשה? \u0003אמר רבא: בפירוש ריבתה תורה שבועת שקר דומה ל\u0004שבועת \u0003שוא, מה שוא\u0004 הריהו שבועה \u0003לשעבר, אף שקר נמי\u0004 \u0005[גם כן]\u0006 מתחייב מלקות דוקא על שבועה \u0003לשעבר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' ירמיה לר' אבהו\u0004 ממה ששנינו: מי שאמר \u0003\"שבועה שלא אוכל ככר זו\",\u0004 וחזר ואמר \u0003\"שבועה שלא אוכלנה\",\u0004 ועוד \u0003\"שבועה שלא אוכלנה\"\u0004 — \u0003ואכלה,\u0004 למרות שנשבע כמה פעמים — \u0003אינו חייב אלא אחת.\u0004 שבועה כגון \u0003זו היא שבועת בטוי, שחייבין על זדונה\u0004 אם עבר עליה בזדון — \u0003מכות, ועל שגגתה\u0004 אם עבר בשגגה על שבועתו — מביא \u0003קרבן עולה ויורד.\u0004","ונדייק: \u0003\"זו היא\" למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 \u0003לאו למעוטי\u0004 \u0005[האם לא למעט]\u0006 את המקרה של הנשבע \u0003\"אכלתי\" ו\"לא אכלתי\", דלא לקי\u0004 \u0005[שאינו לוקה]\u0006 על כך?","ודוחים: \u0003לא, למעוטי\u0004 \u0005[למעט]\u0006 את \u0003\"אכלתי\" ו\"לא אכלתי\" מקרבן.\u0004 וכך נדייק: \u0003זו היא\u0004 ש\u0003על שגגתה\u0004 מביא \u0003קרבן עולה ויורד, אבל \"אכלתי\" ו\"לא אכלתי\" לא\u0004 מביא קרבן. \u0003ו\u0004שיטת \u0003ר' ישמעאל\u0004 \u0003היא,\u0004 ש\u0003אמר: אינו חייב\u0004 קרבן \u0003אלא על העתיד לבא, אבל מילקא לקי\u0004 \u0005[ללקות\u0006 הוא \u0005לוקה]\u0006 על שבועה לשעבר, משום שנשבע לשקר."],["ומקשים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של משנה זו, המשנה הבאה אחריה: הנשבע שבועת שוא, כגון שנשבע שאבן היא זהב, ועוד, \u0003זו היא שבועת שוא שחייבין על זדונה מכות ועל שגגתה פטור.\u0004 ונדייק: הלשון \u0003\"זו היא\" למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 \u0003לאו למעוטי\u0004 \u0005[\u0006האם \u0005לא\u0006 בא הדבר \u0005למעט]\u0006 את \u0003\"אכלתי\" ו\"לא אכלתי\",\u0004 שאף היא מעין שבועת שוא, \u0003דלא לקי\u0004 \u0005[שאינו לוקה]\u0006 כלל!","ודוחים: \u0003לא,\u0004 אין מדובר לענין מלקות. אלא: \u0003זו היא\u0004 ש\u0003על שגגתה פטור מקרבן, אבל \"אכלתי\" ו\"לא אכלתי\"\u0004 — \u0003על שגגתה חייב קרבן; ו\u0004שיטת \u0003ר' עקיבא היא,\u0004 ש\u0003מחייב\u0004 על שבועה \u0003לשעבר כלהבא.\u0004","וחוזרים ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 ופירשת קודם כי \u0003רישא\u0004 \u0005[תחילתה]\u0006 של משנה זו כשיטת \u0003ר' ישמעאל היא;\u0004 וכי \u0003רישא\u0004 \u0005[תחילתה]\u0006 כשיטת \u0003ר' ישמעאל וסיפא\u0004 \u0005[וסופה]\u0006 כ\u0003ר' עקיבא?\u0004 אלא יש לפרש כי \u0003כולה\u0004 שיטת \u0003ר' עקיבא\u0004 היא, \u0003ורישא לאו למעוטי\u0004 \u0005[ותחילתה לא\u0006 באה \u0005למעט]\u0006 (כמו שפירשנו קודם) \u0003\"אכלתי\" ו\"לא אכלתי\" מקרבן, אלא למעוטי\u0004 \u0005[למעט]\u0006 מי שנשבע \u0003\"אוכל\" ולא אכל ממלקות, אבל\u0004 ב\u0003קרבן מיחייב\u0004 \u0005[מתחייב]\u0006 גם על כך.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]?\u0006 מדוע אתה מפרש את המשנה דווקא באופן זה? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 הדבר, שכאשר הוא \u0003קאי\u0004 \u0005[עומד,\u0006 עוסק\u0005]\u0006 \u0003ב\u0004שבועה \u0003להבא ממעט\u0004 שבועה אחרת \u0003להבא,\u0004 אבל אם \u0003קאי\u0004 \u0005[עומד]\u0006 \u0003ב\u0004שבועה \u0003להבא ממעט\u0004 שבועה \u0003לשעבר?\u0004 ואם כן מסתבר לומר שהכל כשיטת ר' עקיבא וכמו שהסברנו, ש\"זו היא\" שברישא ממעט \"לא אוכל\" ממלקות, ובסיפא שנשבע על העבר ממעט \"אכלתי\" ו\"לא אכלתי\", לחייב על כך קרבן.","שנינו במשנה: \u0003\"שבועה שלא אוכל\", ואכל כל שהוא\u0004 — \u0003חייב,\u0004 כדברי ר' עקיבא. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003ר' עקיבא בכל התורה כולה כ\u0004דעת \u0003ר' שמעון סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003מחייב\u0004 על אכילת כל האיסורים גם \u0003ב\u0004שיעור \u0003משהו, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 על אכילת \u0003כל\u0004 שיעור \u0003שהוא\u0004 מאיסורי אכילה הרי הוא נידון \u0003למכות, ולא אמרו\u0004 שיעור \u0003כזית אלא לענין\u0004 חיוב \u0003קרבן,\u0004 שאם הוא איסור אכילה שחייבים עליו קרבן אינו מביא קרבן אלא כשאכל כזית.","\u0003ו\u0004באמת \u0003בדין הוא\u0004 (ראוי היה) \u0003דבעי איפלוגי בעלמא\u0004 \u0005[ש\u0006היו \u0005צריכים\u0006 חכמים ור' עקיבא \u0005לחלוק בכלל],\u0006 בכל איסורי תורה. \u0003והאי דקא מיפלגי הכא\u0004 \u0005[וזה שהם חלוקים כאן]\u0006 דווקא בענין שבועה, הרי זה \u0003להודיעך כוחן דרבנן\u0004 \u0005[של חכמים],\u0006 \u0003דאף על גב דאיכא למימר\u0004 \u0005[שאף על פי שיש\u0006 מקום \u0005לומר]:\u0006 \u0003הואיל ו\u0004אם היה \u0003מפרש\u0004 בשבועתו שהוא אוסר על עצמו במשהו היה \u0003חייב\u0004 על כך, לכן הנשבע \u0003סתם נמי\u0004 \u0005[גם כן]\u0006 יהיה \u0003חייב\u0004 אם אכל משהו, \u0003קא משמע לן דפטרי\u0004 \u0005[משמיע לנו ש\u0006בכל זאת הם \u0005פוטרים].\u0006","זו היא אפשרות אחת, ויש צד אחר: \u0003או דלמא בעלמא כרבנן סבירא ליה\u0004 \u0005[או שמא בכלל כ\u0006דעת \u0005חכמים סבור הוא\u0006 ר' עקיבא\u0005],\u0006 שבכל איסורי תורה השיעור הוא כזית, \u0003והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם],\u0006 \u0003הואיל ו\u0004אם היה \u0003מפרש\u0004 שאוסר על עצמו כלשהו, היה \u0003חייב\u0004 — אם נשבע \u0003סתם נמי\u0004 \u0005[גם כן]\u0006 \u0003חייב?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ש\u0003אמרו לו לר' עקיבא: היכן מצינו\u0004 (מצאנו) \u0003באוכל כל שהוא חייב, שזה חייב? ואם איתא\u0004 \u0005[אכן]\u0006 ר' עקיבא סבור שכל האיסורים במשהו, \u0003לימא להו\u0004 \u0005[שיאמר להם]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003בכל התורה כולה כ\u0004דעת \u0003ר' שמעון סבירא לי\u0004 \u0005[סבור אני],\u0006 שחייב בכלל על כל שהוא!","ומשיבים: מכאן אין הוכחה, שאפשר לומר כי \u0003לדבריהם\u0004 ולשיטתם \u0003דרבנן קאמר להו\u0004 \u0005[של חכמים אמר להם].\u0006 וכך יש להבין את דבריו: \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 \u0003בכל התורה כולה כר' שמעון סבירא לי\u0004 \u0005[סבור אני],\u0006 ואין דין זה יוצא מן הכלל. אבל גם \u0003לדידכו\u0004 \u0005[לשיטתכם]\u0006 שאתם אומרים שחייבים בכל מקום רק בכזית — \u0003אודו\u0004 \u0005[הודו]\u0006 \u0003לי מיהא\u0004 \u0005[על כל פנים]\u0006 בענין שבועה, \u0003הואיל ומפרש חייב, סתם נמי\u0004 \u0005[גם כן]\u0006 \u0003חייב. ואמרו ליה רבנן\u0004 \u0005[לו חכמים]:\u0006 \u0003לא.\u0004 ואם כן, אין להוכיח מכאן.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנה במסכת נזיר, \u0003ר' עקיבא אומר: נזיר ששרה פתו ביין ויש בה כדי לצרף\u0004 מן היין והלחם יחד ל\u0003כזית\u0004 — \u0003חייב. ואי סלקא דעתך בעלמא\u0004 \u0005[ואם עולה על דעתך שבכלל]\u0006 \u0003כר' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 אם כן \u0003למה לי לצרף?\u0004 על שתיית יין כל שהוא יתחייב!","\u0003ועוד תנן\u0004 \u0005[שנינו\u0006 במשנה להלן\u0005],\u0006 אמר: \u0003\"שבועה שלא אוכל\", ואכל נבילות וטריפות, שקצים ורמשים\u0004 — הרי זה \u0003חייב, ור' שמעון פוטר. והוינן\u0004 \u0005[והיינו מתעסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה: אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב\u0004 על השבועה? הלוא \u0003מושבע\u0004 ועומד \u0003מהר סיני הוא,\u0004 שלא יאכל איסורים, ואין שבועה חלה על שבועה! ובתשובה לכך, \u0003רב ושמואל ור' יוחנן דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 כאן הרי מדובר \u0003בכולל דברים המותרין עם דברים האסורין\u0004 כלומר, כאשר אמר \"שבועה שלא אוכל\", יש בכלל זה גם דברים מותרים שחלה עליהם שבועה, ומתוך כך גם הדברים האסורים באכילה חל עליהם איסור שבועה.","\u0003ו\u0004אילו \u0003ריש לקיש אמר: אי\u0004 (אין) \u0003אתה מוצא\u0004 דבר זה, שיתחייב על אכילת איסור משום השבועה, \u0003אלא אי\u0004 \u0005[או]\u0006 \u0003במפרש\u0004 שהוא אוסר על עצמו בשבועה \u0003חצי שיעור\u0004 (פחות מכזית) שעליו אינו מושבע מהר סיני, \u0003ואליבא דרבנן\u0004 \u0005[ולפי שיטת חכמים],\u0006 שבנשבע בסתם נאסר רק בשיעור כזית, \u0003אי\u0004 \u0005[או]\u0006 אף בנשבע \u0003בסתם ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' עקיבא,\u0004 ש\u0003אמר: אדם אוסר עצמו\u0004 בשבועה \u0003בכל שהוא.\u0004","ומעתה, לענייננו: \u0003ואי סלקא דעתך בעלמא\u0004 \u0005[ואם עולה על דעתך\u0006 ש\u0005בכלל]\u0006 ר' עקיבא \u0003כר' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 אם כן כיצד אמר כך ריש לקיש? הרי לשיטת ר' שמעון \u0003כל שהוא נמי\u0004 \u0005[גם כן]\u0006 \u0003מושבע ועומד מהר סיני הוא,\u0004 ומדוע תחול השבועה? \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 על שיטת ר' עקיבא ש\u0003בעלמא כרבנן סבירא ליה\u0004 \u0005[בכלל,\u0006 בכל התורה כולה, \u0005כ\u0006דברי \u0005חכמים סבור הוא]\u0006 שכל האיסורים בכזית, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה, \u0003אמרו לו לר' עקיבא: היכן מצינו\u0004 באוכל כל שהוא שהוא חייב? ותוהים: \u0003ולא\u0004 מצאנו דבר כזה? \u0003והרי נמלה,\u0004 האוכל אותה חייב, למרות שאין בה כזית! ומשיבים: \u0003בריה שאני\u0004 \u0005[שונה],\u0006 שכיון שהיא בריה שלימה — חשובה היא לעצמה.","ומקשים: \u0003והרי\u0004 אוכל \u0003הקדש\u0004 חייב על אכילתו אפילו אין בו שיעור כזית! ומשיבים: \u0003הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 שיהיה ההקדש שנהנה ממנו \u0003שוה פרוטה\u0004 ולא פחות, ואם כן אף הוא יש לו שיעור ואינו נאסר בכל שהוא.","ומקשים: \u0003והרי מפרש\u0004 בשבועתו, כגון הנשבע שלא יאכל כל שהוא, אף לדעת חכמים הוא חייב! ומשיבים: \u0003מפרש נמי\u0004 \u0005[גם כן]\u0006 \u0003כבריה דמי\u0004 \u0005[נחשב],\u0006 שלגבי אדם זה, השיעור הקטן הוא בעיניו דבר חשוב לעצמו.","ומקשים: \u0003והרי עפר\u0004 שאם נשבע שלא יאכל עפר ואכל, בוודאי אין צריך לזה שיעור כזית שהרי אינו בר־אכילה, ומתחייב הוא על כך! \u0003אלא\u0004"],["\u0003תיפשוט\u0004 \u0005[תפתור\u0006 מכאן\u0005]\u0006 אותה שאלה \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבא:\u0004 מי שאמר \u0003\"שבועה שלא אוכל\" ואכל עפר, בכמה\u0004 שיעור איסורו? \u0003תפשוט\u0004 \u0005[תפתור\u0006 מכאן\u0005]:\u0006 \u0003עד דאיכא\u0004 \u0005[שיש\u0006 בו\u0005]\u0006 \u0003כזית!\u0004 ודוחים: \u0003כי קאמרינן\u0004 \u0005[כאשר אמרנו]\u0006 במשנה שצריך שיעור כזית, דווקא \u0003במידי\u0004 \u0005[בדבר]\u0006 שהוא \u0003בר\u0004 \u0005[בן]\u0006 \u0003אכילה קאמרינן\u0004 \u0005[אומרים אנו],\u0006 ולא בדבר שאינו מאכל.","וחוזרים ומקשים: \u0003והרי קונמות\u0004 אדם אוסר על עצמו דבר כקרבן, והריהו אסור בכל שהוא! ומשיבים: \u0003קונמות נמי\u0004 \u0005[גם כן]\u0006 \u0003כמפרש דמי\u0004 \u0005[נחשב],\u0006 כאילו אמר בפירוש שאוסר עצמו בכלשהו.","שנינו במשנה ש\u0003אמר להן\u0004 ר' עקיבא לחכמים: יכול אני להקשות אף עליכם: \u0003היכן מצינו במדבר ומביא קרבן, שזה\u0004 הנשבע \u0003מדבר ומביא קרבן\u0004 בגלל דיבורו? ותוהים: \u0003ולא\u0004 מצאנו הבאת קרבן בגלל דיבור? \u0003והרי\u0004 לשיטת ר' עקיבא עצמו \u0003מגדף\u0004 (מקלל את ה') מביא קרבן! ומשיבים: \u0003מדבר ואוסר קאמרינן\u0004 \u0005[אומרים אנו],\u0006 שאינו מביא קרבן, \u0003והאי\u0004 \u0005[ו\u0006אילו \u0005זה]\u0006 המגדף, \u0003מדבר וחוטא הוא,\u0004 אבל אינו אוסר דבר בגידופו.","ומקשים: \u0003והרי נזיר,\u0004 על ידי דיבורו שנדר להיות נזיר אוסר את עצמו ביין, וחייב להביא קרבן בסוף נזירותו! ומשיבים: היכן מצינו \u0003מביא קרבנו על דבורו קאמרינן\u0004 \u0005[אומרים אנו],\u0006 \u0003והאי\u0004 \u0005[ו\u0006אילו \u0005זה]\u0006 הנזיר כשהוא \u0003מביא קרבן, לאשתרויי ליה חמרא הוא דקא מייתי\u0004 \u0005[להתיר לו את היין הוא שהוא מביא].\u0006","ומקשים: \u0003והרי הקדש\u0004 אוסר דברים על ידי דיבור בלבד, ומביא קרבן על המעילה! ומשיבים: \u0003אוסר לעצמו קאמרינן\u0004 \u0005[אומרים אנו],\u0006 שאינו מביא קרבן, \u0003והאי\u0004 \u0005[ו\u0006אילו \u0005זה]\u0006 המקדיש \u0003אוסר על כל העולם כולו הוא.\u0004","ומקשים: \u0003הרי קונמות\u0004 שאדם אוסר על עצמו דבר כקרבן, ומביא קרבן אם נהנה ממנו! ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ר' עקיבא ש\u0003אין מעילה בקונמות.\u0004","\u0003אמר רבא: מחלוקת\u0004 זו במשנתנו בין ר' עקיבא וחכמים — היא \u0003בסתם,\u0004 שנשבע סתם שלא יאכל, \u0003אבל במפרש\u0004 ואומר שאוסר עצמו בכל שהוא — \u0003דברי הכל בכל שהוא. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מפרש נמי\u0004 \u0005[גם כן]\u0006 \u0003כבריה דמי\u0004 \u0005[נחשב],\u0006 שכיון שקבע איסור על משהו, הרי זה נחשב כדבר מסויים, שחל עליו איסור.","\u0003ו\u0004עוד \u0003אמר רבא\u0004 בענין זה: \u0003מחלוקת\u0004 ר' עקיבא וחכמים — \u0003בש\u0004 אמר \u0003\"לא אוכל\", אבל\u0004 אם אמר \u0003\"שלא אטעום\"\u0004 — \u0003דברי הכל\u0004 נאסר \u0003בכל שהוא.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, שהרי \"לא אטעום\" אין לו שיעור! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליטעום נמי כדאמרי אינשי\u0004 \u0005[גם כן כמו שאומרים בני אדם],\u0006 שאומרים גם על אכילה \"לטעום\", \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין הדבר כן, ואף בכל שהוא חייב.","\u0003אמר רב פפא: מחלוקת\u0004 זו במשנתנו היא — \u0003בשבועות, אבל בקונמות\u0004 — \u0003דברי הכל\u0004 נאסר \u0003בכל שהוא. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003קונמות נמי\u0004 \u0005[גם כן],\u0006 \u0003כיון דלא קא מדכר שמא דאכילה\u0004 \u0005[כיון שאינו מזכיר שם אכילה]\u0006 שיש לה שיעור מסויים, אלא אומר שדבר זה קונם עליו — הרי הוא \u0003כ\u0004מי ש\u0003מפרש\u0004 שאיסורו בכל שהוא \u0003דמי\u0004 \u0005[נחשב].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003שני קונמות\u0004 \u0003מצטרפין\u0004 לאיסור אכילה בכזית, \u0003שתי שבועות אין מצטרפות, ר' מאיר אומר: קונמות\u0004 דינם \u0003כשבועות. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 ש\u0003חייב\u0004 על קונם \u0003בכל שהוא,\u0004 אם כן, \u0003למה לי לצרף?\u0004 הרי כבר נתחייב על כלשהו!","ומשיבים: כגון ש\u0003אמר \"אכילה מזו עלי קונם\", \"אכילה מזו עלי קונם\".\u0004 שכיון שהזכיר לשון אכילה — אין אכילה אלא בכזית. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שבאופן זה נדר, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מצטרפות? סוף סוף,\u0004 לפי דבריו שנדר שני נדרים שונים, \u0003זיל להכא ליכא שיעורא\u0004 \u0005[לך לכאן\u0006 לאכילה מזו \u0005אין פה שיעור\u0006 אכילה\u0005],\u0006 \u0003וזיל להכא ליכא שיעורא\u0004 \u0005[ולך לכאן אין פה שיעור]!\u0006 ומשיבים: מדובר פה בנדר אחד, ש\u0003אמר \"אכילה משתיהן עלי קונם\".\u0004","ושואלים: \u0003דכוותה גבי\u0004 \u0005[שכיוצא בה אצל]\u0006 \u0003שבועות,\u0004 אם \u0003אמר \"שבועה שלא אוכל משתיהן\", אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין מצטרפין? אומר רב פנחס: שאני\u0004 \u0005[שונות]\u0006 \u0003שבועות, מתוך שחלוקות לחטאות\u0004 שאם אסר על עצמו שני דברים בשבועה אחת, ואכל את שניהם — חייב חטאת על כל אחד, לכן גם \u0003אין מצטרפות,\u0004 שהרי כל דבר שאסר בשבועה נחשב כיחידה לעצמה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 ממה ש\u0003ר' מאיר אומר: קונמות כשבועות,\u0004 יש להקשות: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שבועות\u0004 אין מצטרפות — \u0003הואיל וחלוקות לחטאות, אלא קונמות אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יצטרפו יחד? ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות, ש\u0003ר' מאיר אמר: שבועות כקונמות\u0004 שמצטרפים, \u0003ולית ליה\u0004 \u0005[ואין לו,\u0006 ואינו סובר\u0005]\u0006 כדברי \u0003רב פנחס\u0004 שהדבר תלוי בחלוקה לענין חטאות.","\u0003רבינא אמר: כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב פפא\u0004 שבקונמות נאסר בכל שהוא — הרי זה \u0003לענין מלקות,\u0004 שאם עבר ואכל מן הדבר שאסר קונם לוקה בכלשהו. \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 שקונמות מצטרפים — הרי זה \u0003לענין קרבן\u0004 מעילה, \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שיהיה במה שנהנה מן הקונם \u0003שוה פרוטה.\u0004","ומתקשים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מכאן, \u0003דסברי רבנן\u0004 \u0005[שסבורים חכמים]\u0006 ש\u0003יש מעילה בקונמות? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 אם אמר \u0003\"ככר זו הקדש\" ואכלה\u0004 — \u0003בין הוא\u0004 עצמו, \u0003בין\u0004 שאכלה \u0003חבירו\u0004 הרי האוכל \u0003מעל, לפיכך יש לה פדיון\u0004 שיכול לפדות את הכיכר הזו כמו כל הקדש. אבל אם אמר \u0003\"ככר זו עלי הקדש\"\u0004 שהיא עניינו של קונם — \u0003הוא מעל\u0004 אם נהנה ממנה, \u0003חבירו לא מעל, לפיכך\u0004 כיון שאין זה הקדש גמור \u0003אין לה פדיון,\u0004 אלו \u0003דברי ר' מאיר.\u0004"],["\u0003וחכמים אומרים: בין הוא ובין חבירו\u0004 — \u0003לא מעל, לפי שאין מעילה בקונמות!\u0004","ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות ואמור כך: \u0003אחד זה ואחד זה\u0004 — \u0003לא מעל, לפי שאין מעילה בקונמות,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: הוא\u0004 — \u0003מעל, וחבירו\u0004 — \u0003לא מעל.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מה ש\u0003ר' מאיר אומר\u0004 בברייתא הקודמת: \u0003קונמות כשבועות\u0004 שאינם מצטרפים לשיעור של מעילה, \u0003אלא\u0004 מכלל הדברים אתה למד: \u0003קונמות אצטרופי הוא דלא מצטרפי\u0004 \u0005[להצטרף הם שאינם מצטרפים]\u0006 לשיעור מעילה, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003מעילה\u0004 כשלעצמה \u0003אית בהו\u0004 \u0005[יש בהם]?\u0006 \u0003והאמר\u0004 \u0005[והרי אומר]\u0006 כאן \u0003ר' מאיר\u0004 לפי היפוך השיטות: \u0003אין מעילה בקונמות כלל!\u0004","ומשיבים: מה שאמר ר' מאיר לענין צירוף, \u0003לדבריהן דרבנן קאמר להו\u0004 \u0005[של חכמים אמר להם]\u0006 ולשיטתם, ולא לדעת עצמו. וכך יש להבין את דבריו: \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 — \u0003אין מעילה בקונמות כלל, לדידכו\u0004 \u0005[לשיטתכם]\u0006 שיש בהם מעילה — \u0003אודו\u0004 \u0005[הודו]\u0006 \u0003לי מיהת\u0004 \u0005[על כל פנים]\u0006 ש\u0003קונמות כשבועות\u0004 ואינם מצטרפים.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים בתשובה לכך: \u0003שבועות איכא\u0004 \u0005[יש]\u0006 הנימוק של \u0003רב פנחס\u0004 (שיש חילוק לחטאות), ואילו ב\u0003קונמות ליכא\u0004 \u0005[אין]\u0006 הנימוק של \u0003רב פנחס.\u0004","\u0003אמר רבא:\u0004 אם אמר \u0003\"שבועה שלא אוכל\", ואכל עפר\u0004 — \u0003פטור,\u0004 שאין אכילת עפר נחשבת אכילה. ואולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אם אמר במפורש: \u0003\"שבועה שלא אוכל עפר\", בכמה\u0004 הוא חייב אם אכל עפר? וצדדי השאלה: האם \u0003כיון\u0004 ש\u0003אמר \"שלא אוכל\"\u0004 יש לומר ש\u0003דעתיה\u0004 \u0005[דעתו]\u0006 על \u0003כזית\u0004 שהוא שיעור אכילה הרגיל בכל מקום, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דלאו מידי דאכלי אינשי הוא\u0004 \u0005[ש\u0006עפר \u0005אינו דבר שאוכלים בני אדם],\u0006 \u0003בכל שהוא\u0004 גם כן יהיה חייב? לשאלה זו לא נמצאה תשובה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אם אמר \u0003\"שבועה שלא אוכל חרצן\", בכמה\u0004 הוא חייב? וצדדי השאלה: \u0003כיון דמתאכיל\u0004 \u0005[ש\u0006הוא \u0005נאכל]\u0006 \u0003על ידי תערובת,\u0004 שהרי פעמים אוכל החרצן עם הענבים — \u0003דעתיה\u0004 \u0005[דעתו]\u0006 על \u0003כזית\u0004 שלם, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דלא בעיניה אכלי ליה אינשי\u0004 \u0005[שלא בעינו,\u0006 בעצמו, \u0005אוכלים אותו בני אדם]\u0006 אלא תמיד בתערובת, והוא פירש דווקא חרצן — \u0003דעתיה\u0004 \u0005[דעתו]\u0006 על \u0003משהו?\u0004 גם שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי\u0004 בהמשך לשאלות אלה של רבא: \u0003נזיר שאמר \"שבועה שלא אוכל חרצן\", בכמה\u0004 הוא מתחייב? וצדדי השאלה: \u0003כיון\u0004 ש\u0003כזית איסורא דאורייתא\u0004 \u0005[איסור תורה]\u0006 \u0003הוא\u0004 עליו, שהרי כנזיר אסור לו מן התורה לאכול חרצן של ענבים (במדבר ו, ד), ואיסור אכילה הוא כזית, \u0003כי קא משתבע\u0004 \u0005[כאשר הוא נשבע]\u0006 לאסור על עצמו — \u0003אהתירא קא משתבע\u0004 \u0005[על ההיתר הוא נשבע]\u0006 על מה שאינו אסור מן התורה, \u0003ודעתיה\u0004 \u0005[ודעתו]\u0006 בזמן השבועה היא איפוא על \u0003משהו, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003אמר \"שלא אוכל\"\u0004 — \u0003דעתיה\u0004 \u0005[דעתו]\u0006 על \u0003כזית\u0004 שהוא שיעור אכילה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: האומר \u0003\"שבועה שלא אוכל\", ואכל נבילות וטריפות, שקצים ורמשים\u0004 — \u0003חייב, ור' שמעון פוטר. והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה: אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב?\u0004 הלוא \u0003מושבע ועומד מהר סיני הוא\u0004 שלא יאכל את אלה, ואין שבועה חלה על שבועה! בהסבר דבר זה שווים \u0003רב ושמואל ור' יוחנן דאמרי\u0004 \u0005[שאומרים]:\u0006 מדובר \u0003בכולל דברים המותרין עם דברים האסורין,\u0004 שהרי נשבע באופן כללי \"שלא אוכל\", וכיון שחלה שבועה על דברים המותרים חלה גם על האסורים.","\u0003וריש לקיש אמר: אי\u0004 (אין) \u0003אתה מוצא\u0004 שתחול שבועה זו \u0003אלא אי\u0004 \u0005[או]\u0006 \u0003במפרש\u0004 בזמן השבועה שהוא אוסר על עצמו \u0003חצי שיעור, ואליבא דרבנן\u0004 \u0005[ו\u0006הוא \u0005על פי שיטת חכמים]\u0006 במשנה, שאין סתם שבועה על אכילה מחייבת אלא על כזית ויותר, \u0003אי\u0004 \u0005[או]\u0006 אף שנשבע \u0003בסתם ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' עקיבא,\u0004 ש\u0003אמר: אדם אוסר עצמו\u0004 בשבועה \u0003בכל שהוא. ,\u0004 ומדברי ריש לקיש יש להוכיח לענייננו:","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003נבילה\u0004 ש\u0003מושבע ועומד מהר סיני הוא, דכי\u0004 \u0005[שכמו]\u0006 \u0003חרצן לגבי נזיר דמיא\u0004 \u0005[דומה],\u0006 \u0003וטעמא\u0004 \u0005[והטעם\u0006 שחייב, דווקא\u0005]\u0006 משום \u0003דפריש\u0004 \u0005[שפירש]\u0006 ואמר שהוא אוסר עצמו בפחות מכשיעור, \u0003הא לא פריש\u0004 \u0005[אבל\u0006 אם \u0005לא פירש]\u0006 — \u0003דעתיה\u0004 \u0005[דעתו]\u0006 על \u0003כזית\u0004 שלם, \u0003שמע מינה\u0004 \u0005[תלמד מכאן]\u0006 שאף לגבי חרצן כן הדין.","ושואלים: \u0003אלא\u0004 לפי זה \u0003תפשוט\u0004 \u0005[תפתור]\u0006 את הבעיה \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבא: \"שבועה שלא אוכל עפר\", בכמה\u0004 מתחייב על שבועתו? אם כן, \u0003תפשוט\u0004 \u0005[תפתור]\u0006 שאינו מתחייב \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003כזית,\u0004 ולא בפחות, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003נבילה כעפר דמיא\u0004 \u0005[נחשבת],\u0006 \u0003וטעמא\u0004 \u0005[והטעם,\u0006 דווקא\u0005]\u0006 משום \u0003דפריש\u0004 \u0005[שפירש]\u0006 שהוא אסור בכל שהוא הריהו מתחייב, \u0003הא לא פריש\u0004 \u0005[אבל\u0006 אם \u0005לא פירש]\u0006 בכמה הוא אוסר עצמו — \u0003דעתיה\u0004 \u0005[דעתו]\u0006 על \u0003כזית,\u0004 וכשם שהוא בנבילה כן הוא בעפר!","ומשיבים: \u0003לא,\u0004 יש הבדל בין הדברים, \u0003עפר לאו\u0004 \u0005[אינו]\u0006 \u0003בר אכילה הוא כלל,\u0004 ואין מקום לדבר בו כלל על שיעור אכילה. ואילו \u0003נבילה\u0004 כשלעצמה \u0003בת אכילה\u0004 היא, ויש עליה שם אוכל, אלא \u0003אריא\u0004 \u0005[אריה]\u0006 \u0003הוא דרביע עילווה\u0004 \u0005[שרובץ עליה]\u0006 כלומר, איסור הוא שמונח עליה ואינו מניח לאכול ממנה, ולכן יש בה שיעור אכילה.","\u0003\"שבועה שלא אוכל\", ואכל ו\u0004גם \u0003שתה\u0004 — \u0003אינו חייב אלא אחת,\u0004 שהשתיה נכללת בשבועה על אכילה. אבל אם פירט ואמר: \u0003\"שבועה שלא אוכל ושלא אשתה\", ואכל ושתה\u0004 — \u0003חייב שתים,\u0004 שעל כל אחד מהפרטים נשבע לחוד. אם אמר: \u0003\"שבועה שלא אוכל\", ואכל פת חטין ופת שעורין ופת כוסמין\u0004 — \u0003אינו חייב אלא אחת,\u0004 שכולם בכלל שבועתו. אבל אם פירש: \u0003\"שבועה שלא אוכל פת חטין ופת שעורין ופת כוסמין\", ואכל\u0004 את כולן — \u0003חייב על כל אחת ואחת.\u0004 וכן אם נשבע: \u0003\"שבועה שלא אשתה\", ושתה\u0004 סוגי \u0003משקין הרבה\u0004 — \u0003אינו חייב אלא אחת.\u0004 אבל אם פירט ואמר: \u0003\"שבועה שלא אשתה יין ושמן ודבש\", ושתה\u0004 את כולם — \u0003חייב על כל אחת ואחת.\u0004","אם אמר \u0003\"שבועה שלא אוכל\", ואכל אוכלין שאינן ראוין לאכילה,\u0004 או \u0003שתה משקין שאינן ראוין לשתיה\u0004 — \u0003פטור,\u0004 שאין אלה בכלל אכילה. אבל אם אמר: \u0003\"שבועה שלא אוכל\", ואכל נבילות וטריפות, שקצים ורמשים,\u0004 שאסורים באכילה מן התורה — הרי זה \u0003חייב,\u0004 שהרי הם ראויים לאכילה מצד עצמם. \u0003ור' שמעון פוטר\u0004 אותו משבועה זו, לפי שהוא כבר מושבע מהר סיני שלא לאוכלם, ואין שבועה חלה על שבועה. אבל אם \u0003אמר: \"קונם אשתי נהנית לי אם אכלתי היום\", והוא אכל נבילות וטריפות שקצים ורמשים\u0004 — \u0003הרי אשתו אסורה,\u0004 שהרי מכל מקום אכל דבר מה.","\u0003אמר ר' חייא בר אבין אמר שמואל:\u0004 אמר \u0003\"שבועה שלא אוכל\", ושתה\u0004 — \u0003חייב,\u0004 וטעמו של דבר זה: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003סברא\u0004 \u0005[\u0006מן ה\u0005סברה],\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 מן \u0003קרא\u0004 \u0005[הכתוב].\u0006","ומפרטים: \u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור סברה],\u0006 \u0003דאמר ליה אינש לחבריה\u0004 \u0005[שאומר לו אדם לחבירו]:\u0006 \u0003\"נטעום מידי\u0004 \u0005[דבר מה]\",\u0006 \u0003ועיילי ואכלי ושתו\u0004 \u0005[ו\u0006הם \u0005נכנסים ואוכלים ושותים],\u0006 משמע ששתיה היא בכלל אותה טעימה. \u0003ואיבעית אימא קרא\u0004 \u0005[ואם תרצה אמור\u0006 מן \u0005הכתוב]:\u0006 \u0003שתיה בכלל אכילה\u0004 היא, ש\u0003אמר ריש לקיש: מנין לשתיה שהיא בכלל אכילה? שנאמר: \"ואכלת לפני\u0004 \u0003ה' אלהיך במקום אשר יבחר לשכן שמו שם מעשר דגנך ותירשך\"\u0004 (דברים יד, כג),"],["\u0003ותירוש חמרא\u0004 \u0005[יין]\u0006 \u0003הוא, וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ואכלת\",\u0004 משמע ששתיה היא בכלל אכילה.","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 מדובר באכילה ולא בשתיה של יין, והוא \u0003על ידי אניגרון\u0004 (תבשיל ירקות ויין), ש\u0003אמר רבה בר שמואל:\u0004 \u0003אניגרון\u0004 הנזכר בברייתא הוא \u0003מיא דסילקי\u0004 \u0005[מים של סלק]\u0006 כלומר, סלק מבושל, ואילו \u0003אכסיגרון\u0004 — \u0003מיא דכולהו סילקי\u0004 \u0005[מים של כל\u0006 מיני דברים \u0005שלוקים],\u0006 ואם כן, אין זו שתיה אלא אכילה!","\u0003אלא אמר רב אחא בר יעקב: מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה, שנאמר: \u0003\"ונתתה הכסף בכל אשר תאוה נפשך בבקר ובצאן וביין ובשכר...\u0004 ואכלת שם\" (דברים יד, כו), והרי \u0003\"יין\"\u0004 האמור בכתוב הרי \u0003חמרא\u0004 \u0005[יין]\u0006 \u0003הוא, וכתיב\u0004 \u0005[ונאמר]\u0006 על כך \u0003\"ואכלת\"\u0004 (דברים יד, כו).","ומקשים: \u0003ודלמא הכא נמי\u0004 \u0005[ושמא כאן גם כן]\u0006 מדובר באכילת יין \u0003על ידי אניגרון!\u0004","ודוחים: \u0003\"שכר\" כתיב\u0004 \u0005[נאמר]\u0006 בפסוק זה, ללמדנו: \u0003מידי\u0004 \u0005[דבר]\u0006 ש\u0003משכר,\u0004 ויין בתערובת של אניגרון אינו משכר.","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \"שכר\" האמור כאן אין כוונתו ליין, אלא ל\u0003דבילה קעילית\u0004 שמרוב המתיקות שבה היא משכרת, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 כהן ש\u0003אכל דבילה קעילית\u0004 או \u0003שתה דבש וחלב, ונכנס למקדש ועבד\u0004 עבודה — הרי זה \u0003חייב\u0004 משום שתוי יין!","\u0003אלא\u0004 יש לומר כך: \u0003גמר\u0004 \u0005[למד]\u0006 \u0003\"שכר\" \"שכר\"\u0004 בגזירה שווה \u0003מנזיר,\u0004 שנאמר בו \"מיין ושכר יזיר\" (במדבר ו, ג), \u0003מה להלן\u0004 בנזיר \"שכר\" הכתוב בו כוונתו \u0003יין, אף כאן יין.\u0004","\u0003אמר רבא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 במשנתנו, כדברי שמואל, ששתיה היא בכלל אכילה, ששנינו שהאומר \u0003\"שבועה שלא אוכל\", ואכל ושתה\u0004 — \u0003אינו חייב אלא אחת. אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003שתיה בכלל אכילה,\u0004 משום כך \u0003איצטריך ליה\u0004 \u0005[הוצרך לו]\u0006 \u0003לתנא לאשמועינן\u0004 \u0005[להשמיע לנו]\u0006 ש\u0003אינו חייב\u0004 על אכילה ושתיה \u0003אלא אחת,\u0004 שאף ששתיה היא אכילה, אין אלו שתי אכילות נפרדות. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003שתיה לאו\u0004 \u0005[אינה]\u0006 \u0003בכלל אכילה,\u0004 מדוע צריך לומר שאם נשבע שלא יאכל שאינו עובר על שתיה? הרי כיוצא בזה, מי שאמר \u0003\"שבועה שלא אוכל\" ואכל ועשה מלאכה, מי איצטריך לאשמועינן\u0004 \u0005[האם\u0006 הוא \u0005צריך להשמיע לנו]\u0006 ש\u0003אינו חייב אלא אחת?\u0004 מובן שהוא כן, שהרי עשיית מלאכה אינה בכלל שבועתו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מאי\u0004 \u0005[מה]\u0006 אתה רוצה לומר, שהתנא סבור ש\u0003שתיה בכלל אכילה? אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 המשכה\u0005]\u0006 של המשנה: \u0003\"שבועה שלא אוכל ושלא אשתה\", ואכל ושתה\u0004 — \u0003חייב שתים.\u0004 ואילו לשיטתך, \u0003כיון\u0004 ש\u0003אמר \"שלא אוכל\"\u0004 הרי כבר \u0003איתסר ליה\u0004 \u0005[נאסר לו]\u0006 גם \u0003בשתיה,\u0004 ואם כן, \u0003כי\u0004 \u0005[כאשר]\u0006 חזר ו\u0003אמר \"שלא אשתה\" אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב? אילו אמר \"שלא אשתה\" תרי זימני\u0004 \u0005[שתי פעמים],\u0006 \u0003מי מיחייב תרתי\u0004 \u0005[האם\u0006 הוא \u0005מתחייב שתים]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 תחילה: \u0003התם\u0004 \u0005[שם]\u0006 מדובר במי ש\u0003אמר\u0004 רבא \u0003\"שלא אשתה\" והדר\u0004 \u0005[וחזר]\u0006 ו\u0003אמר \"שלא אוכל\",\u0004 ש\u0003שתיה\u0004 אמנם \u0003בכלל אכילה איתא\u0004 \u0005[ישנה],\u0006 אבל \u0003אכילה בכלל שתיה ליתא\u0004 \u0005[איננה],\u0006 ומאחר שהשבועה השניה מוסיפה על הראשונה, חלה גם השבועה השניה.","ומקשים: לשיטה זו יש לדייק: \u0003אבל אמר שבועה \"שלא אוכל ושלא אשתה\" ואכל ושתה מאי\u0004 \u0005[מה]\u0006 יהא דינו — \u0003אינו חייב אלא אחת\u0004 (לפי שהשבועה השניה אינה חלה, שהרי שתיה כבר נכללה באכילה). \u0003אי הכי, אדתני רישא\u0004 \u0005[אם כך, עד ש\u0006הוא \u0005שונה בראשה\u0006 של המשנה\u0005]:\u0006 \u0003\"שבועה שלא אוכל\", ואכל ושתה\u0004 — \u0003אינו חייב אלא אחת, ליתני\u0004 \u0005[שישנה]\u0006 הלכה זו שיש בה חידוש גדול יותר: \u0003\"שבועה שלא אוכל ושלא אשתה\"\u0004 — \u0003אינו חייב אלא אחת, ו\u0004יש ללמוד כי \u0003כל שכן\u0004 אם נשבע \u0003\"שלא אוכל\" לחודיה\u0004 \u0005[לחוד]\u0006 שחייב רק אחת!","\u0003אלא\u0004 יש לחזור מדרך פירוש זו ולהסביר בדרך אחרת. \u0003לעולם\u0004 יש להשאיר את המשנה \u0003כדקתני\u0004 \u0005[כמו ששנה],\u0006 \"שלא אוכל ושלא אשתה\", שחייב שתים. \u0003ו\u0004אף על פי ששתיה בכלל אכילה \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 הדין, כי \u0003כיון\u0004 ש\u0003אמר \"שלא אוכל\" והדר\u0004 \u0005[וחזר]\u0006 ו\u0003אמר\u0004 שבועה אחרת \u0003\"שלא אשתה\", גלי אדעתיה\u0004 \u0005[גילה דעתו]\u0006 \u0003דהך\u0004 \u0005[שאותה]\u0006 \u0003אכילה\u0004 ש\u0003אמר\u0004 קודם בשבועתו — \u0003אכילה גרידתא\u0004 \u0005[בלבד]\u0006 \u0003היא,\u0004 ואין שתיה בכללה.","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כדברי שמואל, ששתיה בכלל אכילה, שכך שנינו בה: האומר \u0003\"שבועה שלא אוכל\", ואכל אוכלין שאין ראוין לאכילה, ושתה משקין שאין ראוין לשתיה\u0004 — \u0003פטור.\u0004 ואפשר לדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם היו המשקים \u0003ראוין\u0004 לשתיה — \u0003חייב, ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 רק \u0003\"שבועה שלא אוכל\" קאמר\u0004 \u0005[אמר]!\u0006 אלא ודאי ששתיה בכלל אכילה.","ודוחים: מכאן אין ראיה גמורה, \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר ש\u0003אמר תרתי\u0004 \u0005[שתים]:\u0006 \u0003\"שבועה שלא אוכל\", \"שבועה שלא אשתה\",\u0004 ולא פירט את הדבר במשנה, משום שעיקר חידושה הוא שדבר שאינו ראוי אינו בכלל אכילה ושתיה.","שנינו במשנה: האומר \u0003\"שבועה שלא אוכל\", ואכל פת חטין\u0004 ומינים אחרים חייב רק אחת, אבל אם פירש ואמר: \"שבועה שלא אוכל פת חיטין ופת שעורין\" וכו' — חייב על כל מין ומין שאוכל, שנחשב כאילו נשבע על כל מין לעצמו. על הלכה זו תוהים: \u0003ודלמא למיפטר נפשיה מאחרנייתא קאתי\u0004 \u0005[ושמא לפטור עצמו\u0006 מדברים אחרים \u0005בא]\u0006 כלומר, שמה שפירט את כל הדברים שלא יאכל, לא התכוון להחיל שבועה מיוחדת על כל מין ומין, אלא רק להגדיר אלו מינים אסר על עצמו!","ומשיבים: אם לכך נתכוון, \u0003הוה ליה למימר\u0004 \u0005[היה לו לומר]\u0006 \u0003\"חטין ושעורין וכוסמין\"\u0004 ולא להזכיר פת חיטין ופת שעורין וכו'. ודוחים: מכאן אין ראיה, \u0003ודלמא\u0004 \u0005[ושמא]\u0006 הוצרך לומר \"פת\" כדי להדגיש שהוא אוסר על עצמו רק פת מכל אותם מינים, ולא אסר על עצמו \u0003לכוס\u0004 (לכסוס) אותם כשהם חיים!","ומשיבים: אם רק לשם כך, לא היה צריך לפרט \"פת\" על כל אחד מן המינים, \u0003דהוה ליה למימר\u0004 \u0005[שהיה לו לומר]\u0006 רק \u0003\"פת חטין ושעורין וכוסמין\",\u0004 והיינו יודעים שכוונתו לפת ולא לכסיסת גרעינים. ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אם היה אומר כך, היינו מסבירים כי כוונתו לאסור על עצמו \u0003פת חטין לאכול, שעורין וכוסמין לכוס,\u0004 ולכן הוצרך לפרט!","ומשיבים: \u0003דהוה ליה למימר\u0004 \u0005[שהיה לו לומר]\u0006 \u0003\"פת חטין ושל שעורין ושל כוסמין\",\u0004 שאז מובן שאוסר עצמו דווקא בפת של מינים אלה. ואם כן מה שפירט \"פת\" בכל אחד מהם מחייבו על כל אחד ואחד."],["ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 בלשון זו היה אוסר \u0003על ידי תערובת,\u0004 שאסר על עצמו רק פת שיש בה כל המינים האלה יחד ולכן השתמש בלשון \"פת\" לכל אחד ואחד!","ודוחים: אם רק משום כך, \u0003אימא\u0004 \u0005[\u0006היה לו \u0005לומר]\u0006 \u0003\"וכן של שעורים וכן של כוסמין\",\u0004 ואז היה ברור שכוונתו לכל אחד מהמינים לעצמו. ואילו מה שמחלק בדבריו ואומר \u0003\"פת\" \"פת\"\u0004 לפני כל מין \u0003למה לי? שמע מיניה\u0004 \u0005[למד מכאן]\u0006 שהתכוון בדבריו \u0003לחלק\u0004 ביניהם, שתחול שבועה נפרדת על כל אחד מן המינים הללו.","שנינו במשנה שהאומר \u0003\"שבועה שלא אשתה\", ושתה משקין הרבה\u0004 — \u0003אינו חייב אלא אחת\u0004 אבל אם פירש: \"שלא אשתה יין ושמן ודבש\" — חייב על כל מין ומין לעצמו. ומקשים: \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 בענין הנשבע שלא יאכל פת חיטים ופת שעורים וכו', ש\u0003אמרת\u0004 והסברת ש\u0003מייתרא ליה\u0004 \u0005[מיותרת לו]\u0006 החזרה על המלים \u0003\"פת\" \"פת\",\u0004 וכוונתו היתה \u0003לחיובא\u0004 \u0005[לחיוב]\u0006 על כל אחת ואחת, \u0003אלא הכא\u0004 \u0005[כאן]\u0006 אין זה ייתור לשון, שכן \u0003מאי הוה למימר\u0004 \u0005[מה היה לו לומר]?\u0006 \u0003דלמא למיפטר נפשיה ממשקין אחריני קאתי\u0004 \u0005[שמא לפטור עצמו ממשקים אחרים בא],\u0006 לומר שרק מאלו הדברים אסר עצמו בשתיה, ולא התכוון לשבועה לגבי כל פרט!","\u0003אמר רב פפא: הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004מקרה שהיו כל המינים הללו \u0003מונחין לפניו עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003שהיה לו לומר\u0004 בפשטות \u0003\"שבועה שלא אשתה אלו\",\u0004 וכיון שחזר ופירש \"יין ושמן ודבש\", משמע שעל כל אחד ואחד נשבע בנפרד. ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אם היה אומר רק \"אלו\" היינו מפרשים כך את שבועתו: רק \u0003אלו\u0004 המונחים לפני עתה \u0003הוא דלא שתינא\u0004 \u0005[שאין אני שותה],\u0006 אבל יין ושמן ודבש \u0003אחריני\u0004 \u0005[אחרים]\u0006 \u0003שתינא\u0004 \u0005[שותה אני]!\u0006","ומשיבים: \u0003אלא,\u0004 ש\u0003אמר \"שבועה דלא שתינא\u0004 \u0005[שאין אני שותה]\u0006 \u0003כגון אלו\".\u0004 ומקשים: \u0003דלמא\u0004 \u0005[שמא]\u0006 היינו מפרשים את דבריו לענין הכמות: \u0003כגון\u0004 \u0003אלו\u0004 הוא \u0003דלא שתינא\u0004 \u0005[שאין אני שותה],\u0006 אבל \u0003בציר מהכי, וטפי מהכי שתינא\u0004 \u0005[פחות מזה, ויותר מזה אני שותה]!\u0006","ומשיבים: \u0003אלא, כגון\u0004 ש\u0003אמר \"שבועה שלא אשתה ממין אלו\".\u0004 ושוב מקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אם היה אומר \"ממין אלו\", היינו אומרים שכך נשבע: \u0003מין אלו הוא דלא שתינא\u0004 \u0005[שאיני שותה],\u0006 \u0003הא אינהו גופייהו שתינא\u0004 \u0005[הרי אותם עצמם אני שותה]!\u0006","ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 שהיה יכול לומר \u0003\"שלא אשתה אלו ומינייהו\"\u0004 \u0005[ומיניהם],\u0006 והיה אוסר על עצמו מינים אלה. וכיון שפירש כל מין לעצמו, משמע שהתכוון להחיל שבועה על כל אחד ואחד.","\u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר: במסרהב\u0004 (מפציר) \u0003בו חבירו\u0004 לשתות אתו \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 והוא נשבע שלא ישתה על מנת לדחות מעליו הפצרה זו. וכגון ש\u0003אמר לו\u0004 החבר: \u0003\"בוא ושתה עמי יין ושמן ודבש\",\u0004 ש\u0003היה לו לומר\u0004 רק: \u0003\"שבועה שלא אשתה עמך\",\u0004 ומה שהזכיר \u0003\"יין ושמן ודבש\" למה לי?\u0004 הרי זה בא לומר שכוונתו \u0003לחייב על כל אחת ואחת.\u0004","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 בענין שבועת הפקדון שאם בא אדם לחבירו ואמר לו: \u0003\"תן לי חטין ושעורין וכוסמין שיש לי בידך\",\u0004 ואמר הנתבע: \u0003\"שבועה שאין לך בידי כלום\",\u0004 ונמצא שהוא משקר וכל אלה הופקדו אצלו — על כולם \u0003אינו חייב\u0004 קרבן אשם \u0003אלא\u0004 משום שבועה \u0003אחת,\u0004 אבל אם אמר הנתבע: \u0003\"שבועה שאין לך בידי חטין ושעורין וכוסמין\"\u0004 — \u0003חייב על כל אחת ואחת,\u0004 אם היה משקר בה.","\u0003ואמר ר' יוחנן: אפילו פרוטה מכולם מצטרפת.\u0004 שאם היה חייב לו אפילו שווה פרוטה המצטרף מכל המינים הללו יחד, שאין בכל אחד מהם שווה פרוטה — הרי זה חייב.","ובהלכה זו \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה רב אחא ורבינא,\u0004 במי שאמר \"שבועה שאין לך בידי חטין ושעורין וכוסמין\", \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אפרטי\u0004 \u0005[על הפרטים]\u0006 שהזכיר \u0005—\u0006 \u0003מיחייב\u0004 \u0005[חייב\u0006 אשם\u0005],\u0006 \u0003אכללי\u0004 \u0005[על הכלל]\u0006 שאמר \"שבועה שאין לך בידי\" — \u0003לא מיחייב\u0004 \u0005[חייב].\u0006 ודברי ר' יוחנן ש\"אפילו פרוטה מכולם מצטרפת\" מתייחסים רק לחלק הראשון של המשנה, שאמר \"שאין לך בידי כלום\". \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אכללי נמי מיחייב\u0004 \u0005[על הכלל גם כן חייב],\u0006 שמה שאמר \"אין לך בידי\" היא כשבועה כללית, שאינו חייב דבר. ולפיכך דברי ר' יוחנן מתייחסים גם לחלק זה של המשנה, שאם חייב שווה פרוטה ממין אחד — חייב על שבועה זו, ואם מצטרפת פרוטה מכל המינים — חייב על כך גם משום השבועה הכללית. וכאמור, דברים אלו נאמרו לענין שבועת הפקדון.","ויש לשאול: \u0003הכא\u0004 \u0005[כאן]\u0006 בשבועת ביטוי, אם נשבע לאסור עצמו דברים שונים בשבועה אחת כבמשנתנו, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם יש חיוב גם על השבועה הכללית (ש\"אינו אוכל\" ו\"שאינו שותה\") או רק על כל פרט ופרט לעצמו?","\u0003אמר רבא: הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 האם ניתן להשוות את הדינים? \u0003התם מיחייב אכללא ומיחייב אפרטא\u0004 \u0005[שם,\u0006 בשבועת הפקדון, \u0005חייב על הכלל וחייב על הפרט],\u0006 וטעמו של דבר, \u0003דהא אי משתבע והדר משתבע\u0004 — \u0003מיחייב תרתי\u0004 \u0005[שהרי אם היה נשבע\u0006 על דבר אחד שאינו ברשותו, \u0005וחוזר ונשבע\u0006 — \u0005היה חייב שתים],\u0006 שהרי הוא שוב חוזר וכופר ממון בשבועה. \u0003הכא\u0004 \u0005[כאן],\u0006 כשאוסר דבר על עצמו בשבועה, \u0003אי סלקא דעתך איתא בכללא\u0004 \u0005[אם עולה על דעתך שיש בכלל\u0006 עצמו\u0005]\u0006 חיוב שבועה, שבכגון זה כשאמר \"איני אוכל\" כבר אסר עצמו באיסור כללי על הפרטים, אם כן \u0003אפרטי אמאי מיחייב\u0004 \u0005[על הפרטים מדוע\u0006 הוא \u0005חייב]?\u0006 הלוא \u0003מושבע ועומד הוא\u0004 כבר עליהם, ואין שבועה חלה על שבועה! אם כן, ברור שחיובו הוא רק על הפרטים, והשבועה הראשונה אינה נחשבת כשבועה לעצמה.","שנינו במשנה שמי שאמר \u0003\"שבועה שלא אוכל\",\u0004 ואכל אוכלים ומשקים שאינם ראויים לאכילה או לשתיה — פטור, ואולם אם אכל נבילות ואיסורי אכילה אחרים — הרי זה חייב. ושואלים: \u0003הא גופא קשיא\u0004 \u0005[\u0006זו המשנה \u0005עצמה קשה]\u0006 מתוכה, שכן \u0003אמרת\u0004 בתחילה: \u0003\"שבועה שלא אוכל\", ואכל אוכלין שאין ראוין לאכילה, ושתה משקין שאין ראוין לשתיה\u0004 — \u0003פטור,\u0004 שאין אלו בכלל אכילה. \u0003והדר תני\u0004 \u0005[וחזר ושנה]:\u0006 \u0003\"שבועה שלא אוכל\", ואכל נבילות וטריפות, שקצים ורמשים\u0004 — \u0003חייב.\u0004 ויש לשאול: \u0003מאי שנא רישא\u0004 \u0005[במה שונה ההתחלה]\u0006 שאתה אומר ש\u0003פטור, ומאי שנא סיפא\u0004 \u0005[ובמה שונה הסוף]\u0006 ש\u0003חייב?\u0004 הלא גם נבילות ושקצים אינם ראויים לאכילה!","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה]:\u0006 \u0003רישא\u0004 \u0005[בהתחלה]\u0006 מדובר שאמר \u0003סתם\u0004 שלא יאכל, ומסתבר שלא כלל בדבריו דברים שאין אנשים אוכלים. \u0003וסיפא\u0004 \u0005[וסופה]\u0006 \u0003במפרש,\u0004 שנשבע במפורש שלא יאכל נבילות וכו', ובכל זאת אכלם.","ושואלים: \u0003מפרש נמי גופיה תיקשי\u0004 \u0005[גם כן\u0006 הוא \u0005עצמו יקשה],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהיה חייב על כך? הלוא \u0003מושבע מהר סיני הוא\u0004 שלא יאכלם, ואין שבועה חלה על שבועה!","בתירוץ קושי זה שווים הם \u0003רב ושמואל ור' יוחנן דאמרי\u0004 \u0005[שאומרים]\u0006 שמדובר כאן \u0003בכולל\u0004 בשבועתו \u0003דברים המותרין עם דברים האסורין,\u0004 שהרי נשבע באופן כללי שלא יאכל, וכיון שחלה השבועה על דברים המותרים באכילה, אגב כך היא חלה גם על האסורים באכילה.","\u0003וריש לקיש אמר: אי\u0004 (אין) \u0003אתה מוצא\u0004 הסבר לנאמר במשנה שחייב על שבועה שלא יאכל איסור, \u0003אלא אי\u0004 \u0005[או]\u0006 \u0003במפרש\u0004 שנשבע שלא יאכל \u0003חצי שיעור\u0004 מן הדברים האסורים, \u0003ואליבא דרבנן\u0004 \u0005[ועל פי\u0006 שיטת \u0005חכמים]\u0006 שבסתם שבועה פטור על חצי שיעור, \u0003אי\u0004 \u0005[או]\u0006 כשנשבע \u0003סתם\u0004 שלא יאכלם \u0003אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 \u0003ר' עקיבא,\u0004 ש\u0003אמר: אדם אוסר עצמו בכל שהוא,\u0004 ובאופן זה חלה השבועה, שהרי על חצי שיעור אינו מושבע מהר סיני.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מובן מדוע \u0003ר' יוחנן לא אמר כריש לקיש,\u0004 משום \u0003דמוקים לה למתניתין\u0004 \u0005[ש\u0006הוא \u0005מעמיד אותה את משנתנו]\u0006 \u0003כדברי הכל,\u0004 לפי הסברו, \u0003אלא ריש לקיש מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כ\u0004דברי \u0003ר' יוחנן?\u0004","ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]:\u0006 \u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 שיש \u0003איסור כולל\u0004"],["הרי זה \u0003באיסור הבא\u0004 (החל) \u0003מאליו\u0004 על האדם, כגון יום הכיפורים, שעל ידו נאסר האדם בכל אכילה שהיא, אבל \u0003באיסור הבא על ידי עצמו\u0004 כלומר, איסור הבא על ידי נדר ושבועה, שהאדם עצמו יוצר את האיסור — \u0003לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 שייחשב כאיסור כולל, לאסור את האדם במה שכבר נאסר עליו מן התורה.","ושואלים עוד: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ריש לקיש,\u0004 שמעמיד את משנתנו במי שנשבע על חצי שיעור, \u0003משום הכי קא פטר\u0004 \u0005[כך פוטר]\u0006 \u0003ר' שמעון, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: כל שהוא למכות, ולא אמרו\u0004 שיעור \u0003כזית אלא ל\u0004התחייב \u0003קרבן.\u0004 ולכן אין שבועה חלה אפילו על איסור כלשהו. \u0003אלא ל\u0004דעת \u0003ר' יוחנן, מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון\u0004 ש\u0003פטר?\u0004","ומשיבים: \u0003מידי\u0004 \u0005[כלום]\u0006 \u0003הוא טעמא\u0004 \u0005[הטעם]\u0006 שחייבה משנתנו \u0003אלא משום איסור כולל,\u0004 ובענין זה \u0003ר' שמעון\u0004 הולך \u0003לטעמיה דלית ליה\u0004 \u0005[לטעמו,\u0006 לשיטתו \u0005שאין לו]\u0006 ענין זה של \u0003איסור כולל,\u0004 וסבור שבמקרה כזה אין איסור חל על איסור. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: האוכל נבילה ביום הכפורים\u0004 — \u0003פטור,\u0004 משום יום הכיפורים. ואף שאיסור יום הכיפורים הוא איסור כולל, שהרי אסור לאכול בו כל דבר, ולא רק נבילה.","ושואלים עוד: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ריש לקיש, משכחת לה\u0004 \u0005[מוצא אתה]\u0006 את השבועה הזו לדעת חכמים \u0003בלאו והן,\u0004 שאחד התנאים לחייב על שבועת ביטוי הוא ששבועה זו יכולה לחול בין שנשבע שלא יעשה דבר ובין שנשבע שיעשה כן. וגם כאן, בין אם נשבע שלא יאכל כלשהו מן האיסור, ובין אם נשבע שיאכל כלשהו — חלה השבועה, לפי שאינו אסור בכך מן התורה. \u0003אלא לר' יוחנן, בשלמא\u0004 \u0005[נניח]\u0006 ב\u0003לאו משכחת לה\u0004 \u0005[מוצא אתה אותה],\u0006 שהרי כפי שהסביר ר' יוחנן חל איסור על הנבילה על ידי איסור כולל שאסר על עצמו גם דברים מותרים, \u0003אלא\u0004 בצד של \u0003הן\u0004 שנשבע שיאכל נבילה ושאר דברים מותרים, \u0003היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]?\u0006 שהרי אין שבועה יכולה להתיר דבר האסור מן התורה!","\u0003אלא\u0004 לדעת ר' יוחנן עלינו לחזור מדרך ההבנה הקודמת של המשנה, שהאוכל דברים שאינם ראויים לאכילה פטור מן השבועה משום שנשבע בסתם, והאוכל נבילות וכו' חייב, למרות שאינם ראויים לאכילה, משום שפירש אותם בשבועתו. ונאמר כי בכל מקרה מדובר כשנשבע בסתם, ובאוכלים שאינם ראויים פטור, \u0003כדרבא,\u0004 ש\u0003אמר רבא:\u0004 אם אמר \u0003\"שבועה שלא אוכל\", ואכל עפר\u0004 — \u0003פטור,\u0004 שאין זו אכילה כלל. אבל בנבילות וכיוצא בהן — ראויים הם לאכילה מצד עצמם, אלא שחל עליהם איסור. ולכן כשנשבע בסתם שלא יאכל — הרי כלל דברים האסורים עם דברים המותרים וחלה עליהם השבועה.","\u0003אמר רב מרי, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]:\u0006 אם אמר \u0003\"קונם אשתי נהנית לי אם אכלתי היום\", ואכל נבילות וטריפות שקצים ורמשים\u0004 — \u0003הרי אשתו אסורה לו,\u0004 ומכאן שאכילה של דברים אסורים נחשבת לאכילה.","על דברי רב מרי תוהים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003כיון דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003אכל\u0004 דבר אסור, \u0003והדר אשתבע ליה\u0004 \u0005[ואחר נשבע\u0006 שלא אכל\u0005],\u0006 הרי מתחילה כשאכל"],["\u0003חשובי אחשביה\u0004 \u0005[החשיב אותם]\u0006 את אכילת הנבילות והטריפות, הנאה שלגביו הרי זה בגדר דבר הנאכל. \u0003אלא הכא\u0004 \u0005[כאן]\u0006 כשנשבע מתחילה באופן כללי שלא יאכל \u0003מי אחשביה\u0004 \u0005[האם החשיב אותם]?\u0006 ומשום כך אין משם ראיה.","כפי שהובא לעיל, העמידו חכמים את משנתנו ששבועה חלה על איסורים בכולל דברים המותרים עם האסורים. ובענין זה \u0003אמר רבא: מאי טעמא דמאן דאית ליה\u0004 \u0005[מה הטעם של מי שיש לו,\u0006 שסובר\u0005]\u0006 \u0003איסור כולל\u0004 שהוא חל על דבר שכבר היה אסור?","\u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 ביחס ל\u0003איסור מוסיף,\u0004 שאיסור חל על איסור אם יש בו תוספת של איסור. שהרי אף כאן יש תוספת איסור.","\u0003ומאן דפטר\u0004 \u0005[ומי שפוטר],\u0006 \u0003דלית ליה\u0004 \u0005[שאין לו,\u0006 שאינו סבור\u0005]\u0006 שיש איסור כולל, טעמו הוא: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר\u0004 שאיסור חל על איסור הרי זה ב\u0003איסור מוסיף,\u0004 שיש בו תוספת איסור \u0003בחדא\u0004 \u0005[באחת\u0006 באותה\u0005]\u0006 \u0003חתיכה\u0004 עצמה, באותו הדבר האסור, אבל \u0003בשתי חתיכות\u0004 שונות \u0003לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 שמפני שחל איסור על חתיכה אחת יחול גם על האחרת.","\u0003ואמר רבא: למאן דאית ליה\u0004 \u0005[ל\u0006דעת \u0005מי שיש לו,\u0006 שסבור\u0005]\u0006 ש\u0003איסור כולל\u0004 חל על איסור, אם \u0003אמר \"שבועה שלא אוכל תאנים\", וחזר ואמר \"שבועה שלא אוכל תאנים וענבים\"\u0004 — \u0003מיגו דחייל\u0004 \u0005[מתוך שחלה]\u0006 השבועה האחרונה על ה\u0003ענבים, חייל נמי\u0004 \u0005[חלה גם כן]\u0006 על ה\u0003תאנים\u0004 אף שכבר נאסרו על ידו.","ואומרים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003איסור הבא מאליו אמרינן\u0004 \u0005[אומרים אנו]\u0006 שיש בו כח לחול על איסור אחר באופן זה, אבל \u0003איסור הבא מעצמו\u0004 על ידי דיבורו בלבד \u0003לא אמרינן\u0004 \u0005[אומרים אנו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין הבדל.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה,\u0004 ממה ששנינו \u0003יש אוכל אכילה אחת וחייב עליה\u0004 אם היה שוגג \u0003ארבע חטאות ואשם אחד, ואלו הן: טמא שאכל חלב, והוא נותר, מן המוקדשין, ביום הכפורים,\u0004 שנמצא שחייב חטאת משום טמא שאכל מן המוקדשים, ומשום אכילת חלב, ומשום אכילת נותר, ומשום אכילה ביום הכיפורים. וחייב אשם מעילות — משום שנהנה מן ההקדש.","\u0003ר' מאיר אומר: אף אם היתה שבת והוציאו\u0004 בפיו מרשות לרשות — הרי זה \u0003חייב,\u0004 ונמצא שיכול להיות בזה עוד חיוב חטאת. \u0003אמרו לו: אינו מן השם\u0004 אין זה מאותו סוג של שאר החיובים, שהרי אינו מתחייב משום אכילה, ואין אלא ארבע חטאות באכילה אחת.","\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לומר שיכול להחיל שבועה (על ידי כולל) גם על איסור, הרי \u0003משכחת לה\u0004 \u0005[מוצא אתה]\u0006 שיכולות להיות \u0003חמש\u0004 חטאות באכילה אחת, \u0003כגון שאמר \"שבועה שלא אוכל תמרים וחלב\", מיגו דחייל\u0004 \u0005[מתוך שחלה]\u0006 השבועה על \u0003תמרים חיילא נמי\u0004 \u0005[חלה גם כן]\u0006 על \u0003חלב!\u0004","ומשיבים: ניתן להסביר כי אף שהתנא סבור שיש אפשרות להחיל איסור שבועה בכולל, מכל מקום \u0003כי קתני\u0004 \u0005[כאשר שנה\u0006 שם במשנה\u0005]\u0006 מספר חטאות — הרי זה ב\u0003איסור הבא מאליו,\u0004 \u0003איסור הבא מעצמו\u0004 (מחמת דברי עצמו) \u0003לא קתני\u0004 \u0005[שנה].\u0006","ומקשים: \u0003והרי הקדש,\u0004 שאיסורו בא מעצמו על ידי הקדשתו, הריהו נכלל באותה רשימה!","ומשיבים: מדובר פה \u0003בבכור,\u0004 ש\u0003קדושתו מרחם\u0004 מעצם היוולדו ראשון, ואינו תלוי בהקדשת אדם.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר מדוע אין כאן קרבן על שבועה: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 הרי זה \u0003מידי דלית ליה\u0004 \u0005[\u0006ב\u0005דבר שאין לו]\u0006 \u0003שאלה,\u0004 שאי אפשר להישאל עליו לחכם ולהתירו למפרע, אבל \u0003שבועה דאית ליה\u0004 \u0005[שיש לה]\u0006 \u0003שאלה,\u0004 שיש בה מקום להישאל עליה, ולא יתחייב עליה קרבן, \u0003לא קתני\u0004 \u0005[שנה].\u0006","ומקשים: \u0003הרי הקדש,\u0004 שגם על הקדש, כמו שאר נדרים, יכול המקדיש להישאל עליו ולהתירו, ובכל זאת שנה אותו!","ומשיבים: \u0003הא אוקמינן\u0004 \u0005[הרי\u0006 כבר \u0005העמדנו]\u0006 שמדובר כאן \u0003בבכור,\u0004 ובכור קדושתו היא מרחם, ולא בהקדשת אדם, ואי אפשר לבטל קדושתו על ידי שאלה.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר נוסף, מדוע אין מוזכר כאן קרבן שבועה, משום ש\u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 — שנה חטאות שהן \u0003קרבן קבוע\u0004 שאינו משתנה מאדם לאדם, אבל \u0003קרבן עולה ויורד\u0004 (שמשתנה לפי מצבו הכלכלי של האדם, אם עני הוא או עשיר), כמו חטאת של שבועת ביטוי, \u0003לא קתני\u0004 \u0005[שנה].\u0006","ומקשים: \u0003הרי טמא שאכל את הקדש\u0004 בשגגה, \u0003קרבן עולה ויורד הוא!\u0004","ומשיבים: מדובר כאן \u0003בנשיא\u0004 טמא שאכל קודש, שמביא חטאת קבועה, \u0003ו\u0004שיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר: נשיא\u0004 טמא שאכל קודש \u0003מביא שעיר\u0004 (שהוא קרבן חטאתו הקבועה).","\u0003רב אשי אמר\u0004 תירוץ אחר: \u0003כי קתני\u0004 \u0005[כאשר שנה\u0006 שם\u0005]\u0006 הרי זה \u0003מידי דחיילא\u0004 \u0005[דבר שחל]\u0006 על \u0003כשיעור,\u0004 אבל \u0003שבועה דחיילא\u0004 \u0005[שחלה]\u0006 גם על \u0003פחות מכשיעור לא קתני\u0004 \u0005[שנה],\u0006 שהרי אדם שנשבע במפורש שלא יאכל כלשהו — לכל הדעות מביא קרבן.","ומשיבים: \u0003הרי הקדש\u0004 שחל גם על פחות מכשיעור כזית!","ומשיבים: \u0003הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 על כל פנים שיהיה בו שיעור \u0003שוה פרוטה.\u0004","\u0003ורב אשי מאויריא אמר\u0004 בשם \u0003ר' זירא\u0004 תירוץ אחר: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 — הרי זה דבר ש\u0003זדונו\u0004 (אם עשה אותו בזדון) חייב \u0003כרת,\u0004 אבל שבועת ביטוי \u0003זדונו לאו\u0004 (באיסור מלקות) \u0003לא קתני\u0004 \u0005[שנה].\u0006","ומקשים: \u0003והרי אשם\u0004 שמנה שם, ש\u0003זדונו לאו\u0004 אין בו חיוב כרת אלא מלקות, על מעילה בקדש, \u0003וקתני\u0004 \u0005[ושנה\u0006 אותו\u0005]!\u0006"],["ומשיבים: \u0003בחטאת קאמרינן\u0004 \u0005[אומרים אנו],\u0006 שמדובר במשנה רק על חטאות שיש חיוב כרת על זדונן.","\u0003רבינא אמר\u0004 תירוץ אחר: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 הרי זה \u0003מידי דחייל אמידי דבר\u0004 \u0005[דבר שחל על דבר שבן]\u0006 \u0003אכילה הוא,\u0004 אבל \u0003שבועה דחיילא אמידי דלאו בר\u0004 \u0005[שחלה\u0006 גם \u0005על דבר שלא בן]\u0006 \u0003אכילה הוא\u0004 — \u0003לא קתני\u0004 \u0005[שנה].\u0006","ומקשים: \u0003והרי\u0004 שנה \u0003הקדש, דחייל נמי\u0004 \u0005[שחל גם כן]\u0006 על \u0003עצים ואבנים\u0004 שאינם בני אכילה!","\u0003אלא\u0004 כך צריך לומר: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 — הרי זה \u0003מידי דחייל אמידי דאית בה מששא\u0004 \u0005[דבר שחל על דבר שיש בו ממש],\u0006 \u0003שבועה דחיילא אמידי דלית ביה מששא\u0004 \u0005[שחלה\u0006 גם \u0005על דבר שאין בו ממש],\u0006 \u0003כגון\u0004 הנשבע \u0003\"שאישן\" ו\"שלא אישן\",\u0004 שאין ממש במעשה זה של השינה, כיון שהיא איסור מסוג אחר \u0003לא קתני\u0004 \u0005[שנה]\u0006 אותה כאן.","בכלל שבועת ביטוי שחייב עליה קרבן עולה ויורד, אם עבר עליה בשוגג, \u0003אחד\u0004 שבועה על \u0003דברים של עצמו\u0004 הנוגעים לו, \u0003ואחד\u0004 הנשבע על \u0003דברים של אחרים, ואחד דברים שיש בהן ממש, ואחד\u0004 הנשבע על \u0003דברים שאין בהן ממש.\u0004","ומפרשים את הכללים: \u0003כיצד\u0004 הם \"דברים של אחרים\"? \u0003אמר \"שבועה שאתן לאיש פלוני\"\u0004 או \"שבועה \u0003שלא אתן\",\u0004 וכן שבועה לשעבר — \u0003\"שנתתי\u0004 לאיש פלוני\" או \u0003\"שלא נתתי\u0004 לאיש פלוני\", שבכל אלה שבועתו מתייחסת לאנשים אחרים.","ו\"דברים שאין בהם ממש\" — כגון שנשבע \u0003\"שאישן\" ו\u0004כן שנשבע \u0003\"שלא אישן\",\u0004 וכיוצא בזה לשעבר: \u0003\"שישנתי\" ו\"שלא ישנתי\",\u0004 שהשינה הריהו דבר שאין בו ממש. וכן אם נשבע \u0003\"שאזרוק צרור לים\" ו\"שלא אזרוק\", \"שזרקתי\" ו\"שלא זרקתי\".\u0004 זו שיטת סתם משנה.","\u0003ר' ישמעאל אומר: אינו חייב אלא על העתיד לבא\u0004 כלומר, אינו חייב אלא כשנשבע על דבר שיהיה לעתיד לבוא ולא על מה שהיה בעבר, \u0003שנאמר\u0004 בשבועת ביטוי: \"או נפש כי תשבע לבטא בשפתים \u0003להרע או להיטיב\"\u0004 (ויקרא ה, ד), ומשמעות הדברים היא להבא.","\u0003אמר לו ר' עקיבא\u0004 לר' ישמעאל: \u0003אם כן,\u0004 אם אתה לומד מכאן שאין חייבים אלא על שבועה כלשון הכתוב, \u0003אין לי אלא דברים שיש בהן הרעה והטבה, דברים\u0004 אחרים \u0003שאין בהן הרעה והטבה, מנין\u0004 שיש בהם חיוב על השבועה?","\u0003אמר לו\u0004 ר' ישמעאל בתשובה: לומדים אנו דברים אלה \u0003מריבוי הכתוב. אמר לו\u0004 ר' עקיבא: \u0003אם ריבה הכתוב לכך,\u0004 גם דברים שאינם הרעה והטבה, \u0003ריבה הכתוב\u0004 גם \u0003לכך,\u0004 לנשבע על העבר כנשבע על העתיד.","ובענין הנזכר במשנה ששבועה חלה על דבר שאין בו ממש \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 יש \u0003חומר\u0004 (צד חומרה) \u0003בנדרים\u0004 יותר \u0003מבשבועות,\u0004 ו\u0003חומר בשבועות מבנדרים.\u0004 ומפרטים: \u0003חומר בנדרים\u0004 — \u0003שהנדרים חלים על דבר מצוה,\u0004 שאם אסר עליו בנדר דבר שמקיים בו מצוה — חל הנדר \u0003כדבר הרשות, מה שאין כן בשבועות,\u0004 שאינו יכול להישבע על מצוה לבטלה, ואם נשבע לעשות מצוה — אין שבועתו חלה.","מצד שני \u0003חומר בשבועות\u0004 — \u0003שהשבועות חלות\u0004 גם \u0003על דבר שאין בו ממש כדבר שיש בו ממש, מה שאין כן בנדרים\u0004 שאינם חלים אלא על דבר ממשי.","שנינו במשנה: \u0003כיצד? אמר \"שבועה שאתן לפלוני\" ו\"שלא אתן\".\u0004 ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אתן\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שאמר \"אתן \u0003צדקה ל\u0004פלוני \u0003עני\",\u0004 הלוא \u0003מושבע ועומד\u0004 על כך \u0003מהר סיני הוא, שנאמר: \"נתון תתן לו\"\u0004 (דברים טו, י), ואין שבועה חלה על שבועה!","\u0003אלא\u0004 הכוונה היא שאמר \"אתן \u0003מתנה ל\u0004פלוני \u0003עשיר\",\u0004 שאין בה צד של מצוה.","שנינו במשנה: \u0003\"שאישן\" ו\"שלא אישן\",\u0004 שהשבועה חלה עליו, וחייב קרבן אם עובר על שבועתו. ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: האומר \"שבועה שלא אישן שלשה ימים\"\u0004 — \u0003מלקין אותו וישן לאלתר,\u0004 ואין מחכים עד שיעבור על שבועתו, לפי שיודעים מראש שהשבועה היא שבועת שוא. ואילו מכאן יוצא שרק כשעובר על השבועה הוא מתחייב!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בדברי ר' יוחנן מדובר ש\u0003אמר\u0004 \"שלא אישן \u0003שלשה\u0004 ימים\", \u0003הכא\u0004 \u0005[כאן]\u0006 במשנה מדובר ש\u0003לא אמר \"שלשה\u0004 ימים\".","שנינו במשנה שאם נשבע: \u0003\"שאזרוק צרור לים\" ו\"שלא אזרוק\",\u0004 הרי זה בכלל שבועת ביטוי שמביאים עליה קרבן אם עבר עליה בשוגג. ובענין זה \u0003איתמר\u0004 \u0005[נאמרה]\u0006 מחלוקת אמוראים, אם אמר: \u0003\"שבועה שזרק פלוני צרור לים\"\u0004 או: \"שבועה \u0003שלא זרק\",\u0004 \u0003רב אמר:\u0004 אם התברר לאחר מכן שהוא שקר — הרי זה \u0003חייב, ושמואל אמר: פטור.\u0004","ומסבירים את שיטותיהם: \u0003רב אמר חייב,\u0004 מדוע? \u0003איתיה\u0004 \u0005[ישנו]\u0006 \u0003בלאו והן,\u0004 שכיון שהוא יכול להישבע גם על שפלוני זרק וגם על שלא זרק, הרי זה בכלל הדברים שחלה עליהם שבועה. \u0003ושמואל אמר פטור,\u0004 מדוע? \u0003ליתיה\u0004 \u0005[אינו\u0006 שייך\u0005]\u0006 \u0003בלהבא,\u0004 שהרי אינו יכול להישבע שפלוני יזרוק או שלא יזרוק.","ושואלים: \u0003לימא בפלוגתא\u0004 \u0005[\u0006האם \u0005נאמר\u0006 כי \u0005במחלוקת]\u0006 של \u0003ר' ישמעאל ור' עקיבא קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' ישמעאל אומר: אינו חייב אלא על העתיד לבא, שנאמר: \"להרע או להיטיב\"\u0004 (ויקרא ה, ד). \u0003אמר לו ר' עקיבא: אם כן, אין לי אלא דברים שיש בהן הרעה והטבה, דברים שאין בהן הרעה והטבה מנין\u0004 שאסורים?","\u0003אמר לו: מריבוי הכתוב. אמר לו: אם ריבה הכתוב לכך\u0004 לדברים שאין בהם הרעה והטבה, \u0003ריבה הכתוב לכך\u0004 לשבועה על העבר.","ומעתה, האם נאמר כי \u0003רב דאמר\u0004 \u0005[שאומר]\u0006 שחייב על \"שבועה שזרק פלוני\" סבור \u0003כ\u0004דעת \u0003ר' עקיבא\u0004 שיש חיוב שבועה גם על דברים שהיו בעבר, \u0003ו\u0004אילו \u0003שמואל דאמר\u0004 \u0005[שאומר]\u0006 שפטור סבור \u0003כר' ישמעאל,\u0004 שאינו מחייב אלא על דברים לעתיד לבוא?","ודוחים: \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' ישמעאל כולי עלמא לא פליגי\u0004 \u0005[כולם\u0006 רב ושמואל \u0005אינם חולקים]\u0006 שאין שבועה \"שזרק פלוני\" חלה, שהרי \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003מילתא דאיתא\u0004 \u0005[דבר שישנו]\u0006 שאפשר להישבע עליו \u0003בלהבא לא מחייב עלה\u0004 \u0005[עליו]\u0006 \u0003ר' ישמעאל\u0004 אם נשבע עליו \u0003לשעבר, מילתא דליתא\u0004 \u0005[דבר שאינו]\u0006 יכול להישבע עליו \u0003בלהבא,\u0004 כגון \"שיזרוק פלוני\", שהרי אין זה תלוי בו, \u0003מיבעיא\u0004 \u0005[צריך\u0006 לומר\u0005]\u0006 שאינו יכול להישבע עליו על העבר?","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' עקיבא,\u0004 כי \u0003רב\u0004 סבור \u0003כר' עקיבא\u0004 שאדם מתחייב על שבועה לשעבר, ואף \"שזרק פלוני\" בכלל זה. \u0003ושמואל אמר\u0004 \u0005[אומר]:\u0006 \u0003עד כאן לא\u0004 שמענו ש\u0003מחייב ר' עקיבא התם\u0004 \u0005[שם]\u0006 על שבועה \u0003לשעבר, אלא מלתא דאיתא\u0004 \u0005[דבר שאפשר]\u0006 להישבע עליו \u0003בלהבא מחייב ר' עקיבא\u0004 אם נשבע עליו \u0003לשעבר, אבל מידי דליתיה\u0004 \u0005[דבר שאינו]\u0006 \u0003בלהבא\u0004 — \u0003לא,\u0004 אינו מחייב עליו. ואם כן אין מחלוקת רב ושמואל זהה למחלוקת ר' עקיבא ור' ישמעאל.","ומציעים עוד: \u0003לימא בפלוגתא\u0004 \u0005[\u0006האם \u0005לומר שבמחלוקת]\u0006"],["של \u0003ר' יהודה בן בתירא ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003קמיפלגי\u0004 \u0005[חלוקים הם\u0006 רב ושמואל\u0005]?\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003נשבע לבטל את המצוה ולא ביטל\u0004 — \u0003פטור\u0004 מקרבן שבועת ביטוי, נשבע \u0003לקיים את המצוה ולא קיים\u0004 — \u0003פטור\u0004 על השבועה. \u0003שהיה בדין\u0004 כלומר, מן הסברה היה \u0003שיהא חייב, כדברי ר' יהודה בן בתירא,\u0004 ש\u0003אמר ר' יהודה בן בתירא: ומה אם\u0004 \u0003הרשות\u0004 (דבר שאין בו מצוה) \u0003שאינו מושבע עליה מהר סיני\u0004 לעשות — \u0003הרי הוא חייב עליה\u0004 אם נשבע לעשות ולא עשה, \u0003מצוה שמושבע עליה מהר סיני\u0004 לעשות — \u0003אינו דין שיהא חייב עליה\u0004 אם נשבע לעשותה ולא עשאה?","\u0003אמרו לו\u0004 חכמים: \u0003לא,\u0004 אי אפשר לומר כך, \u0003אם אמרת בשבועת הרשות שכן עשה בה לאו כהן\u0004 כלומר, שיכול להישבע לעשות מעשה או שלא לעשותו, \u0003תאמר בשבועת מצוה שכן לא עשה בה לאו כהן,\u0004 שאף שיכול להישבע לקיים מצוה וודאי אינו יכול להישבע לבטלה?","אם כן, \u0003נימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003רב דאמר\u0004 \u0005[שאומר]\u0006 שחייב על שבועה לשעבר אף שאינה בלהבא, סבור \u0003כר' יהודה בן בתירא,\u0004 שלדבריו מתחייב אדם גם אם נשבע לעשות דבר שאינו יכול להישבע שלא לעשותו, \u0003ושמואל דאמר\u0004 \u0005[שאומר]\u0006 שאינו חייב על שבועה שאינה בלהבא סבור \u0003כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים]\u0006 שלדבריהם אינו חייב על שבועה שאינה בלאו?","ודוחים: \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יהודה בן בתירא כולי עלמא לא פליגי\u0004 \u0005[הכל,\u0006 רב ושמואל \u0005אינם חלוקים]\u0006 שבוודאי חייב על שבועה \"שזרק פלוני\", שכן \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם שתהא שבועה ב\u0003לאו והן לא בעי\u0004 \u0005[אינו צריך],\u0006 וכי \u0003להבא ולשעבר בעי\u0004 \u0005[צריך]?\u0006","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 רב ושמואל — הרי זה \u0003אליבא דרבנן\u0004 \u0005[לפי שיטת חכמים]\u0006 שפוטרים בשבועה שאינה בלאו והן, \u0003שמואל\u0004 סבור \u0003כרבנן\u0004 \u0005[כחכמים]\u0006 בפשטות, \u0003ורב\u0004 סבור: \u0003כי לא מחייבי רבנן\u0004 \u0005[כאשר אין מחייבים חכמים]\u0006 — הרי זה דווקא על שבועה שאינה בכלל \u0003לאו והן, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"להרע או להיטיב\"\u0004 (ויקרא ה, ד) \u0003בהדיא\u0004 \u0005[במפורש],\u0006 \u0003אבל\u0004 דבר זה של \u0003להבא ולשעבר, דמריבויא דקראי אתו\u0004 \u0005[שמריבוי המקראות באים]\u0006 ולא ממקראות מפורשים — \u0003מחייבי\u0004 \u0005[מחייבים]\u0006 חכמים גם בדבר שאינו להבא.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב המנונא\u0004 על שיטת שמואל ממה ששנינו, מי שאמר: \u0003\"לא אכלתי היום\" ו\"לא הנחתי תפילין היום\",\u0004 ואמר לו חבירו: \u0003\"משביעך אני\", ואמר: \"אמן\",\u0004 וכיון שענה \"אמן\" הרי זה כנשבע בעצמו, והתברר אחר כך שהיה זה שקר — הרי הוא \u0003חייב\u0004 על שבועתו. ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003\"לא אכלתי\" איתיה\u0004 \u0005[ישנו]\u0006 גם \u0003ב\"לא אוכל\",\u0004 ואם כן, יש בזה לאו והן, עתיד ועבר. \u0003אלא \"לא הנחתי\" מי איתיה\u0004 \u0005[האם ישנו]\u0006 \u0003ב\u0004שבועה לעתיד \u0003\"לא אניח\"?\u0004 ולמרות זאת הריהו חייב!","\u0003הוא,\u0004 רב המנונא, \u0003מותיב לה\u0004 \u0005[מקשה אותה]\u0006 את הקושיה הזו, \u0003והוא\u0004 עצמו גם \u0003מפרק לה\u0004 \u0005[מתרץ אותה]:\u0006 מה ששנה התנא במשנה זו שחייב, \u0003לצדדין קתני\u0004 \u0005[שנה]\u0006 כלומר, כל אחד משני המקרים הללו לעניינו, מה ששנינו \u0003\"לא אכלתי\"\u0004 שהוא חייב — הרי זה \u0003לקרבן,\u0004 שהרי ישנו בלהבא, ומה ששנינו \u0003\"לא הנחתי\"\u0004 שחייב — הרי זה \u0003ל\u0004חייבו \u0003מלקות\u0004 משום שבועת שקר, ולא לקרבן, שהרי אינו יכול להישבע כן לעתיד.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 גם הוא על שיטת שמואל, ממה ששנינו: \u0003איזו היא שבועת שוא?\u0004 כגון ש\u0003נשבע לשנות את הידוע לאדם, ואמר על עמוד של אבן שהוא במקום פלוני, שהוא של זהב, ואמר עולא\u0004 על משנה זו: מהו הנחשב כידוע לאדם? \u0003והוא שניכר לשלשה בני אדם\u0004 שהוא של אבן, ושזו היא שבועת שוא. ויש לדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003ניכר\u0004 הדין כן, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא ניכר\u0004 — \u0003עובר משום שבועת ביטוי\u0004 וחייב קרבן, \u0003ו\u0004לשיטת שמואל \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אינו ב\u0004שבועה להבא, שאינו יכול להישבע \u0003\"יהא\u0004 עמוד זה \u0003של זהב\"!\u0004","\u0003הוא,\u0004 רבא, \u0003מותיב לה\u0004 \u0005[מקשה אותה]\u0006 את הקושיה הזו, \u0003והוא מפרק לה\u0004 \u0005[מתרץ אותה]:\u0006 יש לדייק אחרת מן הדברים: אם הוא \u0003ניכר\u0004 לשלושה בני אדם — \u0003עובר משום שבועת שוא, לא ניכר\u0004 — אינו עובר משום שבועת שוא אלא \u0003עובר משום שבועת שקר\u0004 ולוקה על כך במזיד. אבל אינו חייב קרבן משום שבועת ביטוי, שהרי אינו בלהבא.","ובענין מחלוקת רב ושמואל \u0003אמר אביי: ומודה רב\u0004 המחייב על שבועת ביטוי גם אם אינה בלהבא, \u0003באומר לחבירו: \"שבועה שאני יודע לך עדות\" ואשתכח דלא ידע ליה\u0004 \u0005[ונמצא\u0006 אחר כך \u0005שאינו יודע לו]\u0006 — ש\u0003פטור\u0004 משום שבועת ביטוי, שהרי אין זה אלא בהן ולא בלאו, \u0003הואיל וליתיה\u0004 \u0005[ואיננו]\u0006 \u0003בכלל \"שאיני יודע לך עדות\",\u0004 כי כאשר נשבע כך שוב אינו מתחייב משום שבועת ביטוי אלא משום שבועת העדות, שיש בה דינים אחרים.","אבל אם נשבע \u0003\"ידעתי\" ו\"לא ידעתי\u0004 עדות\" — הרי זה בכלל \u0003מחלוקת\u0004 רב ושמואל, וכן \u0003\"העדתי\" ו\"לא העדתי\"\u0004 — אף זה בכלל \u0003מחלוקת\u0004 רב ושמואל. שלדעת שמואל כיון שאינו יכול להישבע באלה על העתיד אינו מתחייב גם לשעבר, ולדעת רב מתחייב עליה.","ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003שמואל\u0004 ש\u0003אמר: מילתא דליתיה\u0004 \u0005[דבר שאינו]\u0006 \u0003בלהבא לא מחייב עליה\u0004 \u0005[מתחייב עליו]\u0006 בשבועה \u0003לשעבר, להכי אפקה רחמנא\u0004 \u0005[משום כך הוציאה אותה התורה]\u0006 \u0003לשבועת עדות מכלל שבועת ביטוי,\u0004 שיש לגביה כתוב מיוחד באותה פרשה: \"...והוא עד או ראה או ידע אם לא יגיד ונשא עוונו\" (ויקרא ה, א), משום שלשיטת שמואל לא היה מתחייב עליה משום שבועת ביטוי, שהרי יכול להישבע עליה רק לעבר ולא לעתיד, ולכן נתייחד לה דין לעצמה. \u0003אלא ל\u0004שיטת \u0003רב\u0004 שמחייב גם במקרה כזה משום שבועת ביטוי, \u0003למאי הלכתא אפקה רחמנא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה הוציאה אותה התורה]\u0006 מכלל שבועת הביטוי?","\u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים לפני]\u0006 \u0003אביי:\u0004 שמא \u0003לאיחיובי עליה תרתי\u0004 \u0005[לחייב עליה שתים],\u0006 שני קרבנות \"עולה ויורד\", הן משום שבועת ביטוי והן משום שבועת העדות!","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003תרתי לא מציתו אמריתו\u0004 \u0005[שתים אין אתם יכולים לומר]\u0006 שיתחייב, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 פרשה זו נאמר בה: \"והיה כי יאשם \u0003לאחת מאלה\"\u0004 (ויקרא ה, ה), ולשון המיעוט הכתובה שם מלמדת: \u0003לאחת אתה מחייבו,\u0004 על כל אחת מאותן עבירות, \u0003ואי\u0004 (ואין) \u0003אתה מחייבו שתים.\u0004","ושואלים: \u0003ו\u0004אם כן, \u0003ל\u0004דעת \u0003אביי\u0004 \u0003למאי הלכתא אפקיה רחמנא\u0004 \u0005[לאיזו הלכה,\u0006 לאיזה ענין \u0005הוציאה התורה]\u0006 את שבועת העדות מכלל שבועת הביטוי, לשיטת רב?","ומשיבים: \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003בכולן\u0004 בכל העבירות שמביא עליהן קרבן עולה ויורד \u0003נאמר \"ונעלם\", וכאן\u0004 בשבועת העדות \u0003לא נאמר \"ונעלם\",\u0004 ומכאן למדים שבא הכתוב \u0003לחייב על המזיד\u0004 בעבירה זו \u0003כשוגג,\u0004 שבשבועת העדות חייב קרבן עולה ויורד גם אם משקר במזיד. ומשום כך הוצרך הכתוב להוציאה.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לאביי, אימא\u0004 \u0005[אמור]\u0006 כך: משום כך הוציאה התורה את שבועת העדות מכלל שבועת ביטוי — לומר כי \u0003במזיד מיחייב חדא\u0004 \u0005[מתחייב\u0006 קרבן \u0005אחד]\u0006 אם נשבע שאינו יודע עדות, \u0003בשוגג מיחייב תרתי\u0004 \u0005[מתחייב שתים],\u0006 גם משום שבועת העדות וגם משום שבועת ביטוי!","\u0003אמר להו\u0004 \u0005[להם],\u0006 \u0003לאו היינו דאמרי\u0004 \u0005[האם לא זהו שכבר אמרתי\u0006 לכם\u0005]\u0006 ששנינו בברייתא: \u0003\"לאחת\"\u0004 — ללמוד מכאן: חטאת \u0003אחת אתה מחייבו, ואי\u0004 \u0005[ואין]\u0006 \u0003אתה מחייבו שתים,\u0004 הרי שיש מצב בו היה מקום לחייבו שתי חטאות אלמלא מיעוט זה, \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003במזיד, מי איכא תרתי\u0004 \u0005[האם יש שתים]\u0006 שהיה מקום לחייבו? הרי בשבועת הביטוי אינו מביא חטאת אלא על השגגה!","\u0003רבא אמר\u0004 בתשובה לשאלת חכמים: אין מקום לחייב על שבועת העדות גם משום שבועת ביטוי מטעם אחר, \u0003משום דהוה\u0004 \u0005[שהיה זה]\u0006 דין שבועת העדות, \u0003דבר ש\u0004היה \u0003בכלל\u0004 של כל שבועות ביטוי \u0003ויצא לידון בדבר החדש,\u0004 ולפי המדות שהתורה נדרשת בהן \u0003אין לך בו אלא חידושו בלבד,\u0004 ואינו נכלל עוד בתוך אותו כלל, ולכן הופקעה שבועת העדות מכלל שבועת ביטוי בכל מקרה.","ושואלים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003אביי\u0004 שלא הסביר כך, \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003איתה\u0004 \u0005[יש]\u0006 \u0003לשבועה בעולם\u0004 כלומר, יש צד של שבועת ביטוי גם בשבועת העדות, גם אם בפועל, בגלל מיעוט הכתובים, אינו מתחייב בשתי חטאות?","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי: מודה רב, באומר לחבירו \"שבועה שאני יודע לך עדות\" ואשתכח דלא ידע ליה\u0004 \u0005[ונמצא שאינו יודע לו\u0006 עדות\u0005]\u0006 — ש\u0003פטור\u0004 מקרבן על שבועת ביטוי, ומדוע? \u0003הואיל וליתיה\u0004 \u0005[ואיננו]\u0006 בכגון זה \u0003ב\"איני יודע לך עדות\",\u0004 משום שהיא שבועת עדות. הרי שאין בה שבועת ביטוי כלל!","ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003אביי מההיא. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006"]]};
